/* 平成21年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h21.committeeSessions.push(...[{"id":"h21-20090623-9","meetingId":"h21-cm06","date":"2009年6月23日","dateIso":"2009-06-23","committee":"文教委員会","time":"午前１０時０２分～午後４時２４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を112件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"を聴取します。 はじめに、(1)校舎改築事業の進捗状況","agenda":"を聴取します。 はじめに、(1)校舎改築事業の進捗状況","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"品川地区のところなんですけれども、一般質問で、エコスクールとして事業計画書を申請したというお話があって、大変いいなと思いながらお聞きしていたんですけれども、そのことによって、こういうことをしますということだけではなくて、何か推進する体制にも、国の支援とかがあったりするのか、その辺のところの経過をお知らせいただきたい。ほかにどういうところに力を入れているのか。","respondent":"田村庶務課長","answer":"今回の答弁でも答えていますけれども、ご存じのとおり、特徴ある品川地区で、緑のネットワークにも囲まれていて、敷地も広いですから、まず、先陣を切って、エコスクールとして環境配慮というのは大切なんだという起点にしたいと考えております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"井上委員","kind":"質問・要望","question":"地熱利用は、八丈島とかでやっているのは知っているんですが、そういう地熱がないところでどうやるのかなと思いました。ほかの自治体でやっているということで、後でその自治体を教えていただきたい。詳しい状況はないにしても、こういう耐震の経過で、こういうふうになっているということはあってしかるべきだと思うんですが、そこについては、どのような対応をされているのでしょうか。","respondent":"田村庶務課長","answer":"ですから、いろいろな機会に説明して、知らなかったという状況がないように心がけて取り組んでまいりました。","voiceIndex":7,"id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"もう１点は、今、地域の方には、町会長会議でお知らせしたという話があったんですが、そこの立ち位置なんですけれども、町会長会議にお知らせしました、イコール、町会長たちが地域に発信をするというふうに、教育委員会はとらえているのか。その辺のお考えは、どのようなところに立っているのかがよくわからないんですけれども、その辺をしっかり教えてください。","respondent":"田村庶務課長","answer":"私どもの受けとめ方とすれば、当然、行政のほうで町会長会議に出てご説明しているので、温度差はあるかもしれないですが、町会長は自分だけで温めているのではなく、役員会なり、あるいは回覧板なりで情報提供しているのではないかと考えています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"井上委員","kind":"質問・要望","question":"これは要望になるんだと思うんですけれども、いろいろなお役目を町会長が担われていて、どこまでやらなきゃいけないのかというのはとても大変なことだと思いますので、町会長会議に発信をしたことが、当然、町会長なり町会が発信しているんだということではなくて、それは行政の仕事であるということをしっかり意識して進めていただきたいと、これは要望でしかないのではないかと思うので。","respondent":"市川教育次長","answer":"改築のケースによっては、これまで町会への回覧等もした事例もあります。地域の皆さんにどのようにお伝えしていくか、これは個々別々に検討して、対応していくという考え方です。","voiceIndex":11,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"はじめに、第三日野小学校のことなんですけれども、先ほどの説明で、ゴムチップから人工芝に、という話がありましたけれども、どういう要望があって、そういうふうに変えたのかということ。それから、人工芝は、大分質がよくなってきたという話は伺いますけれども、私なんかが子どものときは、転ぶと摩擦熱があるということがよくあったんですけれども、先の人工芝の状況も、ちょっと教えていただけますか。","respondent":"田村庶務課長","answer":"スケジュールを見ていただくとわかりますが、今回、人工芝で検討と言っていますが、実際には、外構工事に着工するのが来年の２月からになりますので、詳細についてはまだ固まっていません。ただし、まず一つが、地元の町会から連名で人工芝にという要望があった。","voiceIndex":13,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"第一日野小学校で、第一校庭は天然芝、本会議でも説明がありましたけれども、本会議の場で、幾つか課題が説明されて、それぞれの課題が対応できるというか、そんなような話だったと思ったんですけれども、改めて、どういった課題があって、第一日野小学校では、それがどういうふうに対応できるのかというところを教えていただきたい。","respondent":"田村庶務課長","answer":"養生期間の話がありますので、たまたま第一日野小学校は、今改築している新しいところは、自分の校庭もありますし、日野中学校の第二校庭もありますので、そちらの二つの校庭を利用できるというメリットがあるので、今回、あくまでもモデル的ではありますけれども。","voiceIndex":15,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"今のお話の中で、学校の協力、地元の協力、養生期間は一定の理解が必要と、そこの利用者、利用団体の協力が必要なわけですけれども、そこの調整というのは、今はどういう状況なのか。それとも、これからなのかわからないんですけれども、利用調整、協力調整はどういう状況なのか、教えていただきたい。エコスクールというのが、そもそもどういう事業なのか、そこをちょっと教えていただけますか。","respondent":"田村庶務課長","answer":"ただ、私もホームページを見て、リストアップしてみますと、全国レベルの事業で、継続的な事業なんです。ただし、北海道だとか、青森だとか、学校自体が広くて、そういう学校だけです。唯一世田谷区で１件あります。","voiceIndex":17,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"そのことを準備会の中ではどんなふうに説明をして、どういったご意見というか、要望というか、上がっているのか。先ほどの説明は一貫校の工事自体だったので、教育委員会で言う母体校という言い方でしたか、そのことについて、ちょっと経過と、準備会から上がっている要望と、そこの様子を教えていただけますか。","respondent":"和氣小中一貫教育担当課長","answer":"統合時期は変更ございませんので、荏原第三中学校、荏原第四中学校は平成２３年４月に統合いたします。杜松小学校および大間窪小学校については、平成２５年４月開校期に統合するという予定で進んでおります。","voiceIndex":19,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に専門部会という話がありましたけれども、どんな専門部会かあるのか、教えていただきたい。説明会の中で、スムーズな移行と、そういう要望ということでしたけれども、準備会の中でどういった意見が上がっているのか、もう少し具体的に教えていただけたらと思います。","respondent":"和氣小中一貫教育担当課長","answer":"専門部会ですけれども、学校運営部会、それから、これはまだ詳細は決まっていませんけれども、通常で言うと、標準服検討部会、校名・校章・校歌部会、ＰＴＡ部会、式典部会とか、大体そのぐらいが標準的な部会設定になります。","voiceIndex":21,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれの部会で詳細を決めていくんでしょうけれども、保護者のアンケートとか、子どものアンケートとか、地域のアンケートとか、そういった把握の仕方でぜひ進めていただきたいと思うんですけれども、そういった予定はあるのか、どうか、いかがでしょうか。","respondent":"和氣小中一貫教育担当課長","answer":"そこら辺の内容については、どう決めていくかということについても、その中でご検討いただきますし、最終決定は私どもであったり、学校が決定したりするわけですけれども、そこで、もちろん保護者、子ども、地域の意見を十分に反映してやっていきたいと考えております。","voiceIndex":23,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"幾つか教えてください。それから、荏原東地区小中一貫校は、これだけではちょっとわからないんですね。全体像がないと、あそこの地域は、どういうふうになるのかということが見えないので、今回は、こういう概要ですからよろしいかと思うんですけれども、そういうお示しをしていただきたい。どちらか進んでいる内容も、教えていただきたいと思います。","respondent":"田村庶務課長","answer":"２回目は１０月なんですが、それと同時に、今まで一貫校で建設した検討というか、こういう学校を進めました、校庭がどのぐらいとか何とかという話をご説明した。３回目が、プロポーザルで業者が決まりましたので、業者を紹介している。","voiceIndex":25,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"そういう経過だというのはわかるんですが、要は、うちの中にもプロジェクトがあって、そこで検討していきますという話ですよね。やっていることはあまり変わらないと思うんですけれども、その説明の仕方であったりとか、持っていき方であったりとかというところの工夫によって、もうちょっと地域の中で一緒につくっていくという雰囲気が出るのではないかと思うんですが、その辺のお考えは、いかがでしょうか。","respondent":"田村庶務課長","answer":"本日の資料で、私のほうで説明が不足していましたけれども、右側の下から２段目の荏原東地区小中一貫校を見ていただきますと、ほかの帯状のところにはない、昨年度から、基本計画という位置づけを初めてしました。","voiceIndex":27,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"幾つか施設上のことで確認とお願いです。そういうふうに体育館だけではなくて、日野学園、伊藤学園とつくってきて、施設上、どういうところを改善しなければいけないということは、日野学園の工事はいろいろあったかと思うんですけれども、これだけつくっていくんですから、そういう改善する項目として、何か挙がっているのかどうかということを確認したいということです。","respondent":"富田学務課長、和氣小中一貫教育担当課長、田村庶務課長","answer":"改築していない学校につきましても、校内ＬＡＮ整備を年次計画を立ててやっていきたいと、今後の検討課題ということになっております。それぞれ対応を考えております。近隣への配慮ということですが、校舎が北側で校庭が南側というのが、日当たりの問題も含めて、それが理想なんですが、これまでの実績を見ても。","voiceIndex":29,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"では最後にＩＴのことで、これは順次やっていくというお話なんですが、ＰＴＡ室のところで、ＰＴＡの人たちがインターネットをやろうと思っても、だめと言われてしまって、なかなか使えないという現状があるということなので、そこら辺の対応はいろいろ考えていただいて、いろいろ課題はあるかとは思うんですが、そこのところを改善していただきたいなと思いますが、いかがでしょうか。","respondent":"富田学務課長","answer":"ＰＴＡのパソコンの配置、またインターネットの活用ですが、学校においても、情報の安全管理が、今、非常に課題であると考えていますので、学校の回線と同一のものを使ってということはできないというお話をしているところです。","voiceIndex":33,"id":"exchange-014"},{"speaker":"浅野委員","kind":"質問・要望","question":"この図をしげしげと見るのは、今回、初めてなんですけれども、この中で、こういう形で随分きれいに整理をされて、それぞれの進捗状況がわかるので非常に見やすいと思って、今の説明を伺っていたんです。その中でちょっと何点か伺いんです。それと、すみません、どっちが西小山駅なのかというのが、ちょっとぴんと来なかったので、まずそれをちょっと教えていただきたいと思います。","respondent":"田村庶務課長","answer":"荏原第六中学校については、さっきの説明でも、基本設計と実施設計を実際に１年の中でやり終えるということで、荏原東地区小中一貫校も提案の内容はありますけれども、まだ全体の提案の内容も、庁内ＰＴもそうですし、地元の方にも、提示すると一人歩きしてしまうので。","voiceIndex":35,"id":"exchange-015"},{"speaker":"浅野委員","kind":"質問・要望","question":"一つちょっと気になっているのが、東急の地下化をした上の部分。これは要望であります。この図柄を見ると、かなりきれいな形になるかなと思うんですけれども、荏原第六中学校については、かなり校庭も狭かったのではないかなと思うので、仮設校舎ですとか、校庭の手当てとか、いろいろ考えられているとは思うんですけれども、ちょっとそこら辺、概要で結構ですので、教えていただければと思います。","respondent":"田村庶務課長","answer":"具体的な図面はまだこれからまとめる段階なので、まとめたら本委員会にもお示しして、ご説明したいと考えています。今の概要は、以上です。","voiceIndex":37,"id":"exchange-016"},{"speaker":"林副委員長","kind":"確認","question":"この予定というのは、５月末日でまとめたものだから、延びたのも入っていると理解をしていいんですか。最初に基本設計を立てたときとか、そういうときにできた予定とは大幅に狂っている、例えば小中一貫校荏原平塚学園の場合なんかもそうでしょうし、そこを確認させてください。ここに載っているものが、現在は、もう予定であると。これについては、もう延びないんですねという確認をしたいんです。","respondent":"田村庶務課長","answer":"おっしゃるとおりです。小中一貫校八潮学園、小中一貫校荏原平塚学園については、今現在の予定を書いていますので、これ以上先に延びるということはございません。","voiceIndex":39,"id":"exchange-017"},{"speaker":"林副委員長","kind":"質問・要望","question":"この６カ所で、もう先には一体型一貫校は進まないのですねというのが一つの質問です。これで全部という感じで出されているから、教育委員会の考え方は、一体型一貫校はもうここに載っているもので全部終了なんですか、ということが一つ。それから、荏原第六中学校まで計画を立ててきたんですけれども、この後、平成２１年度に取りかかる耐震工事の学校というのはあるんですか。","respondent":"市川教育次長、田村庶務課長","answer":"１点目の、施設一体型の一貫校の今後の計画です。計画をしていた６校については、今、それぞれが順調に計画の実現に向けて推移している。この考え方のベースにありましたのは、各ブロックに１校ずつという考え方で進めてまいりました。清水台小学校は３棟あるんですが、１棟だけは改築せざるを得ないという状況で、今、検討を進めている段階なので、それが決まり次第ということになります。","voiceIndex":41,"id":"exchange-018"},{"speaker":"林副委員長","kind":"意見","question":"耐震のほうは、いろいろ騒がれて、びりだとか何とかということから免れていくのにあと１年かかるということですね。それはわかりました。そうすると、６校で決まり、もうこれ以上は一体型は進めるつもりはありませんというふうに理解しないほうがいいんですね。決めてないですよ、理解をするときに、もう終わりという理解は持たないほうがいいですねと言っているんです。","respondent":"市川教育次長","answer":"実際に、日野学園から始まって、今、順次開校しているわけですが、その中で、例えば学校選択制の際の選択の状況がどうなのか、それから、実際の距離的な配置バランスがどうなのか、そういうことをこれから検討した上で、今後の計画をするかしないか。","voiceIndex":44,"id":"exchange-019"},{"speaker":"林副委員長","kind":"質問","question":"私なりに理解をしておきます。今日、これを出されたのは、一体型の一貫校にするというハード面の説明なんですよね。ですから、一つは、八潮学園ももう始まっている時期だけれども、ソフトの面で、授業、内容等について出てきた課題、それから、ハードの面で出てきた課題、それは教育委員会としてつかんでいるんですか。","respondent":"市川教育次長","answer":"そういう現実、ソフト、ハードの面の検証作業には取りかかっておりますので、それを報告できるような段階がいつになるかというのは、この場では、ちょっと明言できませんけれども、そういう作業に、教育委員会自身が取り組んでいるというご報告と、一定程度。","voiceIndex":46,"id":"exchange-020"},{"speaker":"林副委員長","kind":"質問","question":"予算があったのでしょう、それから、まだ使っていないから引き取ってくれたのかどうかわからないけれども、胸ぐらいのげた箱にぱっと変えた。そういう意味で、今、教育次長は、どのぐらいの期間でまとまってくるかわからないけれどもとおっしゃったから、教育委員会として次へ進む一つの反省をつかむという意味からしたら、いいところ、悪いところをピックアップして教えてほしい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-021"},{"speaker":"井上委員","kind":"質問・要望","question":"本来、教育施設であるので、子どもを中心にあるべきというのは理解をしながら、周りの方から、せっかくそこに何かつくるのであれば、地域が使えるようなという要望も出されているということを伺っていたんですが、何かそういうようなもの、この夏に設計図を示して、視察があるということなので、そこまでちょっと図案が出てこないのかなと思うんですけれども、その辺、何か検討されているとか。","respondent":"田村庶務課長","answer":"今度新しく改築すると、今の既存の体育館以外に、飛び地のほうにも体育館ができます。既存の体育館を何とか、もちろん学校としての体育館ですけれども、学校が使わないときに地元の人たちが利用できるような形で、拠点となるような形で検討している、そういうような感じです。","voiceIndex":49,"id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"ということは、地域の方たちは、スポーツ施設としてではなくて、学校の中で、イメージとしては山中小学校とかそういうことなのかと、周りの方から聞いて思っていたんですが、そういうことは検討には入っていないということですか。","respondent":"田村庶務課長","answer":"委員の質問とうまくかみ合うかどうかわかりませんけれども、その地域の人たちが利用できるスペースというか、部屋というか、そういうものを含めて、今、計画の俎上の中で具体的に検討しているという状況です。","voiceIndex":51,"id":"exchange-023"}]},{"id":"topic-02","title":"平成２２年度品川区固有教員の採用選考","agenda":"平成２２年度品川区固有教員の採用選考","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"そこに何かねらいがあるのかということを、教えていただきたい。それから、そもそも、私は、小中一貫教育の見直しが必要だと思っていますが、品川区教育改革の原動力を確保すると、目的に書いてありますけれども、改めて、なぜ改革の原動力を確保することが必要なのか、ご説明いただけますか。","respondent":"冠木指導課長","answer":"品川区の教育方針についても熟知する教員が、ある一定の期間が過ぎますと、ほかの区に行ってしまうというのは、せっかく品川区のために活躍していた先生が外に出て行ってしまうというのは、私どもとしても大変残念な思いをしていますので。","voiceIndex":58,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"ときには区の方針と異なるときもあるでしょう。でも、子どものために、というところで同じだと思うんです。この改革の原動力を確保するというのが、どうもイエスマンばかり周りに集めるような動きに見えてしまう。それが、子どものためなのかなと思うんです。そこをどんなふうにお考えなのか、教えていただけますか。","respondent":"若月教育長","answer":"一つの教育公務員という立場でもって仕事をするのであって、自分の個人的な教育感や教育理念を人に押しつけるということは、これは私立学校や塾の先生ならやってください。しかし、私たちは公務員なんですから、公のところで決めた方針や理念を実現する。","voiceIndex":60,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"あれはあらゆるすべての分野を問うものですから、いろいろご意見が寄せられるんですけれども、見たときに、教育の分野が一番、賛成、反対はありますよ、でも一番熱があるというか、思いがあるというか、とりわけ学校選択制については、地域との関係を壊すということがたくさん寄せられている。教育改革そのものが、今、見直しの時期にきているのだなと、私は思います。ぜひ、見直しが必要だと思います。","respondent":"若月教育長","answer":"学校選択制の話が出ましたけれども、もういい加減に次のステップにいってものを考えてください。学校選択をするということぐらい、保護者や何かの声を聞くことに他ならないじゃないですか。一番聞くことではないですか。リアルに評価されているじゃないですか。","voiceIndex":62,"id":"exchange-026"},{"speaker":"中塚委員","kind":"意見","question":"学校選択制について、地域のどこが壊れているんだというのは、あまりにも足元を見ていない。教育長は、自分たちのやっていることは正しいと思っているから、熱弁をお話しするんでしょうけれども、ここはやっぱり真摯に受けとめて、何が起きているのか、地域に目を向けるべきだと思うんです。おごっちゃいけないなと。どこが壊れているんだというのは、私には開き直りにしか思えない。","respondent":"若月教育長","answer":"私は本来、質問する立場にはないかもしれませんが、もう一度よく考えてください。では、品川区の地域の、具体的に何が、どうなっているから、地域が壊れているのであって、以前はどうであったのか。それはどういう根拠で地域が壊れていないとするのか。","voiceIndex":64,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"教えていただきたいという話なので、お話しいたしますけれども、町会の方々に聞いたり、ＰＴＡの方々に聞いたり、今も昔も、地域で子どもを育てる、この思いでみんな頑張っているわけですよ。そういった方々が、学校選択制の中で、地元の子どもが地元の学校に通わなくなった、また、その地域の事情を越えて、ほかの地域から来たときに、どうもうまくいかない。","respondent":"若月教育長","answer":"それはあまりにも地域を見ていなさ過ぎる。その地域といったようなものを、もう一度ゼロから地域はどうあるべきか、学校はどうあるべきか、選択制というものが行われたけれども、しかし、その中で地域と子どもの関係はどうあるべきなのか、それを考えるほうが大事なんですよ。","voiceIndex":66,"id":"exchange-028"},{"speaker":"中塚委員","kind":"意見","question":"きちんとアンケートをとってみて、満足、不満足という取り方は、この前にしていらっしゃいましたけれども、１回とられましたけれども、教育長の主張がどうなのか、私の主張がどうなのか、保護者、また地域の方々、区民の方々、いろいろな方々にアンケートなどを通じて教育改革の問題点、課題、それは率直に調査をして、しっかり説明すべきだと思っています。アンケート調査も引き続きやるべきだと思います。","respondent":"和氣小中一貫教育担当課長","answer":"近日中に報告できると思いますけれども、保護者３分の１を対象にしたアンケート結果でも、学校選択制に対しては高い支持を得ております。いろいろな意見があるのは確かですけれども、そういうさまざまな意見があるということをしっかり見ていただきたい。","voiceIndex":68,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"さっきは言いませんでしたけれども、どこかの意見とか、偏った意見とか、はっきり言って区民から選ばれている議員に対して、そういう言い方は失礼ですよ。品川区に議員が４０人いて、それぞれ託された願いがあって、出席しているわけですよね。その一人に対して、偏った意見だと、それは教育長、小中一貫教育担当課長もそうだけれども、そういう言いぐさは失礼です、はっきり言ってやめていただきたい。","respondent":"和氣小中一貫教育担当課長","answer":"その両方をしっかり見ていただきたい。片方の意見だけがすばらしくて、だから絶対にだめなんだということではなくて、ぜひ両方を見ていただきたいと、私はお願いをしているところです。","voiceIndex":70,"id":"exchange-030"},{"speaker":"井上委員","kind":"質問","question":"私はちょっと違う視点で質問します。このパンフレットについて、ちょっとお伺いをしたいんです。これは、多分、募集要綱としてつくられたものだろうと思うんですけれども、これの作成費用と、どのぐらいつくったかということと、どういうところに配られているのか、その辺のことをお伺いしたいと思います。","respondent":"冠木指導課長","answer":"今、始めたところですので、やっているところです。費用につきましては、ちょっと手元に資料がございませんので、またご案内をしてまいりたいと考えていますけれども、教員の区独自採用の予算の中で対応をしています。","voiceIndex":72,"id":"exchange-031"},{"speaker":"井上委員","kind":"質問","question":"ここのところをお知らせしたいのであれば、先ほど紹介がありました６ページにコメントが載っていますということをお知らせしたいのであれば、違うやり方もあったでしょうし、こういったところにお金をかける感覚が、私にはちょっとバランスが違うかなと思うので、それについて見解があれば、お伺いしたいと思います。","respondent":"若月教育長","answer":"ですから、今はそういう時期で、こういうことをやったという考え方があるということをご理解いただき、今後どうしていくかということは、十分にまた検討をしていく必要があるだろうなと思います。","voiceIndex":74,"id":"exchange-032"},{"speaker":"井上委員","kind":"質問・要望","question":"このことについては、検討をぜひしていただきたいなと思います。そのときに、その費用をなぜかけなきゃいけないか、だったらもっと子どもの校舎のこことか、こういう教材をとかいう具体的な要望もあると思いますので、独自でやっていることを一生懸命ＰＲせねばならない状況というのは、ちょっと考え方を変えていく必要があるなと思うんです。何か見解とかあれば、お願いします。","respondent":"若月教育長","answer":"そこら辺は、今の学校のＰＲのあり方は、教育委員会も含めてですけれども、今、一つの課題になっているなということは、私も感じています。それも十分に検討します。","voiceIndex":76,"id":"exchange-033"},{"speaker":"井上委員","kind":"質問・要望","question":"今のパターン化しているというところで、なぜパターン化しているかというその要因も、学校側のことを考えなくちゃいけないのかなと思うと、そこに労力を使っている余裕がないというのが、一方で、これはもう答弁は要らないですから、そういうところも含めて、そうまでしてＰＲをして生徒を呼び込むというのは、公立学校であれば、どこを選んでも同じ教育が受けられるということが大前提なわけですから。","respondent":"若月教育長","answer":"ああいうパンフレットの中で、うちは自信があるんだと、何もこれをつくるために特別に何かものを考えてやらなきゃいけない、そんなことなら、うちは普通にやっています、何も変わったことはやっていません、基礎、基本を淡々と教えて、確実にこういう力をつけます。","voiceIndex":78,"id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"２年目ということで、推進していただきたいと思いますが、そもそもこの趣旨は、今までもご説明いただいていると思うんです。ですから、一般の教員も必要だと思うんですが、むしろ校長先生こそ必要なんじゃないかと思ったんです。","respondent":"若月教育長","answer":"であるならば、なるべく一つの学校に長くいていただいて、その学校をご自分のお考えのような学校にしていただくような配慮をしているのが限界であります。ご指摘のところは、これから大きな課題であります。","voiceIndex":80,"id":"exchange-035"},{"speaker":"浅野委員","kind":"質問・要望","question":"もう１点は、先ほど、大学とか、区の施設に既に置いてあるというお話だったと思うんですけれども、最後のほうのページに問い合わせ先とか出ていますので、去年はどうだったというのは、もう過去の話でありますけれども、今年また特徴的な問い合わせの内容、この採用試験に挑戦しようとする方がどんなことを質問してくるのか、ちょっと興味があるので、そこら辺のことを教えていただければと思います。","respondent":"冠木指導課長、若月教育長","answer":"昨年との相違点といいますか、工夫した点ですけれども、幾つかございまして、先ほど、説明させていただいたように、応募資格につきましては、一般選考ということで、経験としてはない方も含めてではありますけれども、品川区のために。どうも違わないんですけれども。それから、住居ですね。全国からやっぱりお見えになりますから、住居は新しく探さなければならないのか、あるいは、何か手当があるのかといったような質問も、去年は受けました。","voiceIndex":82,"id":"exchange-036"},{"speaker":"浅野委員","kind":"質問","question":"やはり２年目となりますと、さまざまな方が目にして、そしてさまざまなご意見とか質問が来るかと思います。パンフレットの話も、今日、出ましたけれども、まずはやはりこういうことを品川区がやっているんだということを、ある意味では大きく知っていただくということは、私は重要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-037"},{"speaker":"林副委員長","kind":"意見","question":"これは教育委員会の標語というか、思いがここにあらわされているので、ぜひ、課長方もこういう気持ちになって、品川区の教育をはぐくんでほしいなと思います。一番後に出ているお２人は、選抜したんでしょうね、すごい文章が書かれている。すごい文章です。それからもう一つ、再任用の校長先生の延長も含めて、新しい先生方の感覚が品川区にどういういい影響を与えたのか、それをしっかり検証してほしい。","respondent":"冠木指導課長","answer":"私の説明が不十分で申しわけないんですが、一般選考のほうは、３１歳になってありますが、年齢はそうなんですけれども、教員免許は持っていないと受験資格がございませんので、そこはちょっと説明不足でございました。","voiceIndex":86,"id":"exchange-038"},{"speaker":"林副委員長","kind":"質問・要望","question":"もう１点だけ。独自に品川区の人事権をというのは、私はもう十五、六年になる。なぜかといったら、私は小学校は区立なんですけれども、中学校から大学まで含めて私立に行った。私立の先生たちには、母校愛というのがある。そういうことを、私は、品川区独自の教員たちが子どもたちに植えつけ、社会性を持った、偏っていない人を育てていただきたいというので、お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-039"},{"speaker":"井上委員","kind":"質問","question":"近県までに及んでいるということで、すべて郵送費をかけて郵送しているんですよね。何かの関係で届ける郵送費、そういった経費はわかるんですか。","respondent":"冠木指導課長、堺委員長","answer":"大学にもよりますけれども、持参をしたり、郵便で運んだりということで対応しています。金額につきましては、事務経費の中で対応しておりますので、詳細は、今、手元にございませんので、申し訳ありません。本件につきましては終了いたします。","voiceIndex":93,"id":"exchange-040"}]},{"id":"topic-03","title":"続きまして、(3)保幼小連携の推進","agenda":"続きまして、(3)保幼小連携の推進","exchanges":[{"speaker":"井上委員","kind":"確認","question":"第一回が５月１３日ということで、前回の文教委員会でも、公開というところでは前向きに、ということだったと聞いていますけれども、今後、第一回で確認がされたのかと思いますが、検討委員会の公開状況をどのようにされる予定なのか、お伺いしたい。","respondent":"冠木指導課長","answer":"検討委員会の公開につきましては、今後も、原則公開ということで対応してまいりたいと考えています。","voiceIndex":99,"id":"exchange-041"},{"speaker":"井上委員","kind":"意見","question":"公開ということですので、いつ開かれるかということが周知されなければ、公開の意味がありませんけれども、その周知の方法、開催の周知方法をどうする予定でいらっしゃるのかということ。作業部会と検討委員会のメンバーは、どのような重複があるのかということと、作業部会として一つなのか、幾つかの作業部会があるのか、また、構成メンバーの人数など、詳細はどのようになっていますか。","respondent":"冠木指導課長","answer":"日時、内容等を区の広報を通してご案内をしています。第二回の検討委員会につきましても、日程等が決まりましたら、そのような形でご案内をする予定です。検討委員会のメンバーについては、ちょっとお待ちください。","voiceIndex":101,"id":"exchange-042"},{"speaker":"井上委員","kind":"質問・要望","question":"一番最初の３月の新聞報道で、とてもびっくりして懐疑的な発想で見ていたところが、いろいろな議論を聞いていて、そこまでは幼児教育ではないということがわかってきたので、連携を取るという仕組みは必要だと思うけれども、今までの取り組みと、ここについてどういうふうに評価をしているのかということが一つありますので、そこをお聞かせいただきたいと思います。","respondent":"吉岡保育課長、冠木指導課長","answer":"そういう中で、一定の幼保と小の交流連携というのは図られていましたし、また、教員と幼稚園、保育園の保育士においての交流等も図られていて、一定の成果は上げてきていると思っているんですけれども、ただいまございましたように。このような検討委員会を、これまで以上に踏み込んだ形で進めていく理由、あるいは小一プロブレムの実態のところのご質問がございましたのでお答えいたします。","voiceIndex":103,"id":"exchange-043"},{"speaker":"井上委員","kind":"質問","question":"今のお話だと、６割ぐらいが時間をかけて指導しているから、逆に６割ぐらいがそうだろうという、何かよくわからない答弁だったんですけれども、私も子育てをしてきた経験者ですから、新しい環境になって、幼稚園や保育園と違う小学校というところに行って、子どもの顔も違う、先生も違う、また、遊びの先生という感覚ではないところで、落ち着きがなかったりする、それは当たり前のことだと思うんです。","respondent":"若月教育長","answer":"小一プロブレムというのはこういうものだということを規定しろと言ったって、できないんです。例えばいじめとか、不登校のように、こういう現象でこうなっていますというようなことを、小一プロブレムというもの自体に当てはめるというのは、ちょっと無理があるんです。","voiceIndex":106,"id":"exchange-044"},{"speaker":"井上委員","kind":"質問・要望","question":"検討委員会なんですけれども、たまたまだとは思うんですけれども、私立保育園長代表ということで、現職の区議会議員がここに入っているということで、私は、ここはどうなんだろうと。こういう選考の仕方というのは、何か配慮が必要ではなかったのかなと思うんですけれども、そこのところの判断をお聞かせいただきたいと思います。","respondent":"吉岡保育課長","answer":"ちなみに、私立幼稚園のほうにつきましても、やはり私立幼稚園の団体のほうへお願いをしまして、委員の推薦を２名お願いした中で、ご推薦をいただいた方に、検討委員会の委員をお願いしたという経過があります。","voiceIndex":108,"id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"経過はわかりました。推薦を依頼したんだから、来たというところで、あとはこちらの考え方だと思うんです。品川区の検討委員会として、そのときに、何かそれはいかがなものかというような検討とか、意識はないんでしょうかということをお伺いしたいんです。","respondent":"市川教育次長","answer":"井上委員が、先ほど、議員がこういう検討委員会のメンバーになることについて危惧される点を何点か指摘されましたけれども、私どもが選考する際の考え方、それから、川西議員の見識、そういったことを考えたときに、先ほどの件については危惧に及ばないと判断をいたしました。","voiceIndex":110,"id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"検討委員会の委員の名簿はいいんですけれども、直接の保護者といいますか、親といいますか、そういった方が入っていないんですけれども、大学の先生、幼稚園、保育園、品川区とそれぞれありますけれども、ほかの委員は、区民の公募の枠とかはどうなるんでしょうか、直接の保護者を入れるべきだったのではないかと思うんですけれども、その辺はどんな判断なのか、ご説明いただけますか。","respondent":"冠木指導課長","answer":"検討委員会の実施日につきましてですが、ちょっと学識の委員の先生方のご予定がなかなかそろわないということで、６月の後半の設定が、今まだ難航しておりまして、７月上旬になろうかと考えていますので、また決まり次第、ご案内をいたします。","voiceIndex":112,"id":"exchange-047"},{"speaker":"中塚委員","kind":"質問","question":"保幼小の問題、委員の皆様が何が問題意識なのかというところで、品川区全体で追っていきたいというお話がありましたけれども、先ほどから小一プロブレムのお話がありましたけれども、小一プロブレムの背景にどういう問題があるのか、小一プロブレムと言われている状況が起きている背景に何があるのか、品川区全体でとおっしゃるのであれば、基本的な背景、また保育的な背景、それだけではない労働的な背景。","respondent":"市川教育次長、冠木指導課長","answer":"検討委員会の保護者の参加についてのご質問ですけれども、この検討委員会の検討テーマが、先ほど、説明させていただきましたけれども、保育園、幼稚園、小学校の接続期に一体どういう指導内容で当たるべきか。小一プロブレムの起こる背景についてですけれども、家庭、保育園、幼稚園、小学校、地域社会など、さまざまな要素が複雑に絡んでおりまして、一概に原因を特定することは難しい、そういう現状だと考えております。","voiceIndex":114,"id":"exchange-048"},{"speaker":"中塚委員","kind":"質問・要望","question":"小一プロブレムというものが起きていると、それは交流活動が少ないから起きているかというと、そういうわけでもないわけですよね。ただ、これから進めようとしていることは、小学校の体験など、交流活動の推進とありますけれども、その辺の組み方がよくわからないので、教えていただきたい。今までは、どういった取り組みだったのか。そこと、今回の中身がどんなふうに違うのか、教えていただけますか。","respondent":"若月教育長","answer":"私事で恐縮ですけれども、私の子どもは２人とも保育園に大変お世話になりました、２人とも０歳児からです。その２人の子どもが小学校へ入ったときに、ちょっとあまりよくないんですけれども、２人とも行儀が悪いんです。","voiceIndex":117,"id":"exchange-049"},{"speaker":"中塚委員","kind":"質問","question":"先生方は研修しているのも知っていますし、ただ、親御さんの気持ちにしてみると、まず、認めるのも時間がかかったり、お医者さんに相談するのも時間がかかったり、お母さんから見ると、違いがよくわからないということも聞きますので、これはこれとして、一方でやっぱり、ちゃんと支援が必要な子どもを、どういうふうに分けると言ってはおかしいけれども、その辺をどういうふうに見ているのか。","respondent":"冠木指導課長","answer":"それを受けまして、学校のほうも対応しています。","voiceIndex":119,"id":"exchange-050"},{"speaker":"中塚委員","kind":"質問","question":"それと小一プロブレムとは別の支援が必要ではないかと思うんです。ただ、親御さんにしてみれば、子どもの様子を見るときに、同じように食生活が乱れたり、基本的な生活習慣が整わなかったり、そういうふうに受けとめられるわけですよね。実際に、戸惑いの中から時間がかかるわけですよね。そういうところを、どういうふうに取り組んでいくのか、そこをちょっと伺いたいんです。","respondent":"冠木指導課長","answer":"委員、ご指摘のような件も含めまして、今回の検討委員会では議論になってこようかとは思うんですけれども、いずれにいたしましても、現場の小学校では、含めて、一人ひとりの子どもたちに合った支援といいますか、指導といいますか、それができるように、今。","voiceIndex":121,"id":"exchange-051"},{"speaker":"西本委員","kind":"質問","question":"幾つかお伺いいたします。保幼小連携ということで、非常に期待をしておりますけれども、先ほど、ちょっと教育長のお話にもあったように、ここに入る前に、やっぱり問題だと思っているのが、保育園と幼稚園が違うんですね。私立というのは、その幼稚園、保育園の考え方で運営していきますので、そうしたらどうしたって、教育に関する考え方だって違うと思うんです。そこの考え方はどうでしょうか。","respondent":"吉岡保育課長","answer":"今、幼保一元化といいますか、一体化といいますか、幼稚園でも保育的な部分をやってきましたし、また、保育園のほうでも幼児教育の部分をやってきたわけですけれども、当然、まだ不充分な点があるのではないかというご指摘ですけれども、今、お話がございましたように。","voiceIndex":123,"id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、せっかくつくっても、かなり強烈な指導を持ってやっていかないと、多分、うまくいかないです。そこを何とかしていただきたいと思っているんです。意見はいろいろなところでいただければいいということなんですけれども、基本的なところにおいては、どういうふうにやっていくかということなので、こういうメンバーが中心になって、教育者が委員になってやっていくべきだと思うんです。","respondent":"市川教育次長、若月教育長","answer":"私どもが、幼児教育の何たるかを言えば、おそらく今さら何だというようなお気持ちで私どもの説明を聞かれているのではないかなと、そういう面はあります。今、教育次長が説明したとおりです。ただ、西本委員がご指摘になった問題意識というのは非常に重要なんですね。要するに私立の幼稚園なんですね。","voiceIndex":125,"id":"exchange-053"},{"speaker":"西本委員","kind":"質問・要望","question":"多分、気になると思います、報道もされていますので、何をするんだろうかというような、そういう気持ちも多分あると思うので、問題意識であるとか、こういう課題を今やっているというようなところは、ある程度宣伝というか、何でしょうか、検討しているということは何かの機会で話をして、できれば意識の改善ですね、特にそれをベースにして実際に行動をとっていかなきゃいけないので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-054"},{"speaker":"浅野委員","kind":"質問","question":"私も随分昔、小学校１年生だったころもあるんですけれども、では、そのときに自分はどうだったか、周りはどうだったかというと、全く覚えていないですね。ただ、私が小学校２年生のとき、１年生のときにどうだったか聞かれても、多分まともには答えられないだろうと思いますけれども、そこら辺の可能性はどうなんでしょうか。","respondent":"冠木指導課長","answer":"今、１点ありましたが、これからの状況の把握であるとか、作業部会の動きの中で、そういうような取り組みも提案をさせていただければ思っております。","voiceIndex":131,"id":"exchange-055"}]},{"id":"topic-04","title":"次世代育成支援対策推進計画の策定および推進協議会の開催","agenda":"次世代育成支援対策推進計画の策定および推進協議会の開催","exchanges":[{"speaker":"林副委員長","kind":"意見","question":"ちょっと質疑に入る前にごめんなさい。この文章で、国語的に、一番上の１行目、「平成１５年７月に次代の社会を担う子どもが健やかに生まれ」と、平成１５年７月に子どもが生まれるという文章になっているんですよね。だから「７月に」というところで句読点を入れ、「次代の社会を担う子どもが健やかに生まれ、かつ、育成される環境の整備を図る」となる。","respondent":"小林青少年育成課長","answer":"構文上、ご指摘のとおりです。以後よく注意します、ありがとうございました。","voiceIndex":138,"id":"exchange-056"},{"speaker":"中塚委員","kind":"質問","question":"前期行動計画をどう総括し、後期をどうしていくかというのは、今後の予定の中に若干入っておりますけれども、品川区自身が、今、前期行動計画をどんなふうに振り返って、何ができたのか、何ができなかったのか、新しい問題点は、こんなものが見つかったとか、品川区自身はどんなふうに思っているのか教えてください。","respondent":"小林青少年育成課長","answer":"もう一つは、事業体系が非常に柔軟に対応できる指向を持っている。そして三つ目には、全体として、各事業、ないしは実施主体が連携して、あるいは融合して取り組もうという視点が強まっている。こういった現状にあろうかと思います。","voiceIndex":140,"id":"exchange-057"},{"speaker":"中塚委員","kind":"質問","question":"それからもう一つ、委員名簿で、区民公募の方が５名いらっしゃいますけれども、何人ぐらい応募があって、どういう選考の結果この方々になったのか。なぜかというと、私の知っている人も応募したんだけれども、外れちゃったとおっしゃっていて、どのぐらいあったんだろうと言われたので、公募のところについて教えてください。","respondent":"小林青少年育成課長","answer":"そういった中から、視野の広さ、あるいは、主張していただくお立場の分布、そしてまた、年代ですね、子育て中の方や、子育てを応援する世代等を勘案いたしまして、５名の方にお願いをしたところです。","voiceIndex":142,"id":"exchange-058"},{"speaker":"西本委員","kind":"質問","question":"一つだけ、委員名簿なんですが、公募の方は新しい人なのかなと思うんですけれども、継続の方はどなたなのか教えてください。","respondent":"小林青少年育成課長","answer":"前期から引き続きお務めいただいている方をご紹介したいと思うんですけれども、お手元の名簿から、会長、副会長、それから、青少年委員の方、児童福祉事業主関係者の方、以上の４名が引き続きになっております。１１名が、それぞれ今回、新しく委員をお願いしております。","voiceIndex":144,"id":"exchange-059"},{"speaker":"西本委員","kind":"質問","question":"何を言いたいかというと、新しい人をどんどん入れて、いろいろな考え方のほうがいいかなと思っていることがあるので、公募の方は新しい人だと思われるので、スライド式というよりは、やっぱりいろいろな考え方を入れていただいたほうがいいかなと思っているんですが、それはいかがでしょうか。","respondent":"小林青少年育成課長","answer":"児童福祉事業主関係者の方につきましては、児童福祉の事業というのが、まだコミュニティビジネス的な要素もあって、なかなか広く選定するのが難しい中で、基本的なスタンスを踏まえて、子育てを議論していただく方として期待の上、今回も重ねて選定させていただいたところです。","voiceIndex":146,"id":"exchange-060"},{"speaker":"西本委員","kind":"質問・要望","question":"それぞれのところから推薦があってということなんでしょうけれども、こちらからもある程度条件づけまでははっきり言えないとは思いますけれども、やはりいろいろな方にしていただきたいというところにおいては、やっぱりなるべく新しい人という形でおっしゃるとか、児童福祉事業主関係者ということで、ご活躍は十分にわかっているんですけれども、でもほかのところでも、ＮＰＯの方とか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-061"},{"speaker":"林副委員長","kind":"意見","question":"だから、個人名を挙げて、この人は新しい人に変えるべきだという意見でしょう。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":151,"id":"exchange-062"},{"speaker":"林副委員長","kind":"意見","question":"だから、そういう意見にとれるから、私は両方ともよく知っているから、そういうことを言っていたら、そういう意見が出たと本人に言いますよ。そういうことに突っこんで、個人的なものに入るのは、私は議論としてはちょっと行き過ぎだと思う。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":153,"id":"exchange-063"},{"speaker":"西本委員","kind":"提案","question":"別にこのお二方がどうのこうのと言っているわけではなくて、いろいろな方に入っていただいて、会をもっと広げていただいてはいかがですかという提案なので、別に個人攻撃をしているわけではございません。","respondent":"古川子ども未来事業部長","answer":"この協議会は、ある程度継続して、そしてまた新たなご意見をいただくという両方の面から、今回、４名の方々に残っていただいたということは、この協議会を動かしていく私どもとしては、一定の形はつくれたなと思っています。","voiceIndex":154,"id":"exchange-064"},{"speaker":"井上委員","kind":"質問","question":"今回は、この計画に対しては新たな後期の行動計画として品川区が考える柱は、どういうものなのかということを伺いたいと思います。そうではなくて、品川区としてこういった柱を持ってこの計画をつくっていきますというのがあるのか、どうなのかということを、まずお聞かせください。","respondent":"小林青少年育成課長","answer":"もう一つは、品川区がやってきました事業を、ある意味では、子育てトータルのフィールドにマッピングしたときに、どの辺が手厚くて、どの辺がこうなっていますけれども、それが、皆さんのご見識に照らし合わせたときに。","voiceIndex":156,"id":"exchange-065"},{"speaker":"井上委員","kind":"質問","question":"今、前期の計画の到達点を踏まえてというところで、新たに加わった点はこういうことですよということを提示してからスタートしたいということだったんですけれども、新たに加わった点として、提示するところは何になるんでしょうか。","respondent":"小林青少年育成課長","answer":"いわゆるある意味で、保育園、幼稚園のような施設の事業、サービスだけはなくて、在宅の視点も含めた広い視点でもう一度考えてみましょう。三つ目には、子育てを含む生活と働く仕事との調和、ワークライフバランスの視点を踏まえて、要素として認識しましょう。","voiceIndex":158,"id":"exchange-066"},{"speaker":"井上委員","kind":"提案","question":"大変期待したいと思います。これは予算がつくものですので、ここの委員会でやってほしいという提案があったとしても、なかなか難しいかなと思うんですけれども、そういうことを、ここの部分で一番最初に挙げた視点であると思うので、ぜひ検討をしていただきたいと思うんですけれども、そのことについて何かお答えいただけますでしょうか。","respondent":"小林青少年育成課長","answer":"ただ、その意見を聞くときに、確かに、親御さんは一番よき理解者ですから、その声は真摯に受けとめてまいりたいと思いますけれども、その前提には、親御さんがご自分の子どもに対してかけがえのない宝として、親子のきずながしっかりと根付き、そして。","voiceIndex":160,"id":"exchange-067"},{"speaker":"井上委員","kind":"質問・要望","question":"結構意図が通じないなというジレンマがあるんですけれども、子ども当事者に、次世代を担うそういった世代の子どもたちの意見が、今、なかなか聞き取られていない状況にあるので、ここにいる皆さんも、子どもが何を考えているかすべてわかっているということはあり得ないと思いますから、そういう視点を、ぜひ持っていただきたいということ、これは要望しておきます。","respondent":"小林青少年育成課長","answer":"ならば、その中で、官の役割は何かというと、その協働をしていく区民が、ほかの今、苦労をされている方を支えていくシステム、環境を整えることが事業の中心の課題になると考えていますので、そこを含めて。","voiceIndex":162,"id":"exchange-068"},{"speaker":"井上委員","kind":"質問・要望","question":"難しいけれども、そうすることによって、推進チェックができるということがあるので、そうすると、もう１年は計画がスタートした段階になるんですが、今後の協議会の任期が２年ずつですから、その後どうするのかということ。それから、チェック体制は別であるということを要望するんですが、そのことについて、ご意見をお聞かせください。","respondent":"小林青少年育成課長","answer":"当推進協議会は、今年度は計画を策定いたしますが、次年度以降、２年の任期の中で、来年度は、実施初年度の推進状況を確認していく役割をあわせ持つ委員会として考えております。","voiceIndex":164,"id":"exchange-069"},{"speaker":"井上委員","kind":"意見","question":"これだけに限らず、評価とか、検証というのは、計画は立派なものをつくるけれども、なかなかそこが追いつかないという傾向がありますので、そこのところは、そういうふうな流れにぜひ変えるべきだということは、これは意見として言っておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":166,"id":"exchange-070"}]},{"id":"topic-05","title":"病児保育施設の開設","agenda":"病児保育施設の開設","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"この受付というか、申請の窓口というか、それは、直接病院なんですか。それとも、品川区が窓口になって一定の申請があってやるのか。つまり、この利用期間で、委託医療機関の医師が必要と判断した期間となっていますが、この委託医療機関というのが、ここの病院なんですか。要は、東京都とか国とかの負担というか、補助金というか、そういうのは、全体でどういうふうになっているのか、教えていただけますか。","respondent":"吉岡保育課長","answer":"受付の仕組みですけれども、実施をいたします医院のほうに事前の登録をいたしまして、利用をされるご予定があるという受付をして、登録をしていただきます。","voiceIndex":172,"id":"exchange-071"},{"speaker":"中塚委員","kind":"質問","question":"その補助金がどういうものなのかわからないので、要は、２,０００円が本人負担ですよね。東京都とか国とかの負担の仕組みがどういうふうになっているのか、教えてください。それから、直接病院に登録して、病院の診断を受けるということですけれども、この審査に当たっては、品川区は全く関与しないということなんですかね。","respondent":"吉岡保育課長、小林青少年育成課長","answer":"その後に、実際にご利用になるときに、病気の子どもですので、本来ですと。逆に入るほうは、子育て支援基盤の補助金の中で、病児・病後児保育の補助金というのがございまして、実質的な歳入ベース、病児保育につきましては。施設の整備にかかわる部分につきましては、２分の１ですけれども、運営につきましては、運営費の６００万円までが補助率３分の２で。","voiceIndex":174,"id":"exchange-072"},{"speaker":"中塚委員","kind":"質問","question":"利用料、１日２,０００円ということですけれども、これはどういう根拠で決まったのか、教えてください。それから、食事は原則持参と書いてありますけれども、生後６ヶ月の子どもから小学校前までというと大分幅があるわけで、食事と言ってもミルクだったり、離乳食だったり、いろいろあるかと思うんですけれども、病院で準備できないから持ってきてくださいということなんでしょうか。","respondent":"吉岡保育課長","answer":"だれでも、いつでも、どこでも手軽に利用できるというイメージと、この病児保育を実施する理念というのは若干違うのかなと。","voiceIndex":178,"id":"exchange-073"},{"speaker":"西本委員","kind":"質問","question":"利用期間ですけれども、７日間以内というのは、連続で７日間ということですか。それとも全体ですか。","respondent":"吉岡保育課長","answer":"原則として、継続して７日間以内と考えています。","voiceIndex":180,"id":"exchange-074"},{"speaker":"西本委員","kind":"質問","question":"そうすると、実績をお聞きしたいんですが、登録者がどのぐらいいて、利用者がどのぐらいいて、その利用者は、特定の方が何回も利用されているのか、そこら辺も、現状はいかがでしょうか。","respondent":"吉岡保育課長","answer":"中には、子どもによっては、体が弱いといいますか、病気がちの子どももいらっしゃるということだと思うんですけれども、年間で１０日を超えるような方も、二、三％だと思うんですが、そういう方が中にはいらっしゃいます。","voiceIndex":182,"id":"exchange-075"},{"speaker":"西本委員","kind":"質問","question":"やはり病気のときは親御さんが見るというのが基本ですので、使いやすくなってもいけないし、そこはやっぱり、親のほうがしっかりと子どもの様子を見て、子どもが病気のときぐらい、堂々と会社を休めるというそういう社会にあるべきだと思いますので、あまりこれは広げてほしくないと考えています。次に、ＮＰＯ法人フローレンスが運営サポートということですが、どういうことをされるんですか。","respondent":"吉岡保育課長","answer":"ただし、病児保育という事業自体が、幾つかの自治体でもやっておりますけれども、始まってからまだそれほど年数が経っておりませんし、その運営をするに当たって、普通の一般の病院は、既にノウハウを持っているということでもございませんので。","voiceIndex":184,"id":"exchange-076"},{"speaker":"西本委員","kind":"質問","question":"よくわからないんですけれども、ＮＰＯ法人フローレンスは病院ですか。病院に頼んだわけですね。鈴の木こどもクリニックも、病院の形で委託したと認識していたんですが、区から委託したのに、またさらに委託するとはどういう意味なのかよくわからないんです。ＮＰＯ法人フローレンスの中に、医者とか、そういう専門的な方がいるのか、どこの部分を委託されているんでしょうか。","respondent":"吉岡保育課長","answer":"その一定のノウハウを持っているということで、病院ですから、子どもの病気について対応するのは、もちろん可能なんですけれども、例えば１日から７日間でお預かりをして、保育をしながら健康的に万が一のことがあれば、医者が対応するという仕組みですので。","voiceIndex":186,"id":"exchange-077"},{"speaker":"西本委員","kind":"質問","question":"よくわかりません。今の説明は、非常にわかりにくいです。これは病児保育ですから、当然、委託は病院だと思うんです。その病院でやるべきところを、なぜＮＰＯ法人フローレンスに委託しなければならないかという事態がよくわからないです。ノウハウがないところに、なぜ委託するんですか、おかしいと思います。それで、この病院がさらに委託してしまうというその構図が、私はよくわからないです。","respondent":"吉岡保育課長","answer":"先ほど申しましたように、病院ですから、医療については万全の対応がとれるということですけれども、保育の部分で例えば保育士を手配したり、そういう部分につきましては、一般の病院では、たとえ小児科の医者であっても、その辺については、若干弱いといいますか。","voiceIndex":188,"id":"exchange-078"},{"speaker":"西本委員","kind":"質問","question":"実績として、鈴の木こどもクリニックでやっておられるわけですよね。鈴の木こどもクリニックも、ほかのところに委託していたという経緯があるんですか。それとも、鈴の木こどもクリニックは保育のノウハウもちゃんと持っていて、やれているという理解なんですか。なぜ、それができていて、今回、できないところに委託したということは、私はちょっとよくわからないです。","respondent":"吉岡保育課長","answer":"鈴の木こどもクリニックにつきましては、もう既に開設してから、平成１７年からですから４年ぐらいになるんですけれども、開設の時点で、それなりの準備をされたかと思うんですが、酒寄医院につきましては。","voiceIndex":190,"id":"exchange-079"},{"speaker":"西本委員","kind":"質問","question":"もう少しよく聞かないとわからないんですが、やっぱりこれは病児保育ですので、当然、そのノウハウがあるところに頼むべきだと思うんです。ということは、そういう鈴の木こどもクリニックのような両方を兼ね備えた対応ができるところがなかったという理解でよろしいんですか。","respondent":"古川子ども未来事業部長","answer":"そういう中での一定の協力関係が前提になって、酒寄医院が、病児保育に対するみずからの展開をしようとしていたということの中で、要員の確保において、若干フローレンス側の支援を受けるです。本質的な部分では、一切変わらないと考えております。","voiceIndex":192,"id":"exchange-080"},{"speaker":"西本委員","kind":"質問・要望","question":"私の方は、よくわかっていますので、あえてここでは言いませんけれども、先ほども言っているように、これはもうほんとうに保護者がどうしても見れないというときに使っていただきたいということになっていますので、そこの品川区の考え方をきっちりと病院のほうに伝えて、その方針でやっていただきたいと思いますので、その点だけ確認したいと思います。","respondent":"吉岡保育課長","answer":"ご利用につきましては、先ほども申し上げましたけれども、何らかの仕事上の理由でやむを得ず勤務せざるを得ないというような後ろ髪を引かれるような中で預けるという方については、一定のお預かりする事業を展開するということを基本にしていますので。","voiceIndex":194,"id":"exchange-081"},{"speaker":"井上委員","kind":"質問","question":"そのスペースを取っていただいて、病院で医者に見ていただいて、急変したときにも対応ができるというのが病児保育のあり方だと思っているので、ここの必要性はないに超したことはないけれども、今現在しようがないというのが、私たちがよくわかっていてお伺いしたところなんです。ほんとうに、再委託というのは基本的には禁止しているんだから、では、再委託は何の部分を再委託しているんですか。","respondent":"吉岡保育課長","answer":"それは、発注者、委託者の了承、承認のもとに行うという厳密な管理の中でやっているわけで、それについては、今回の事業について問題があるとは認識してございません。","voiceIndex":196,"id":"exchange-082"},{"speaker":"井上委員","kind":"質問","question":"だから、再委託の部分で、何をフローレンスの業務として委託をされるんですかということをお聞きしたんです。","respondent":"吉岡保育課長","answer":"保育士の派遣と、それから一部の受付の処理等の業務です。","voiceIndex":198,"id":"exchange-083"},{"speaker":"井上委員","kind":"質問","question":"その部分の費用は、キッズベル品川で言えば、人件費としてキッズベル品川のほうが、保育士を探すという業務で、一方で、こちらのほうはフローレンスの事業のほうから保育士を派遣という形で、その費用が、６００万円の３分の２の運営費というところのお金が出されているという、そういうことですか。","respondent":"吉岡保育課長","answer":"基本的に、経費の部分も、事業の内容についても、先行しておりますキッズベル品川と同様の内容になってありますし、金額の算定についても、同じ基準で算定をしているところです。","voiceIndex":200,"id":"exchange-084"},{"speaker":"井上委員","kind":"質問","question":"一番最初に、開設に対しての２分の１というところでは、酒寄医院は、この医院をよく承知してないんですが、病児保育室の部分の改築をして、ないところにつくっていただいたということですか。","respondent":"吉岡保育課長","answer":"もともと東大井で医院を開業されていたので、医院としての設備はお持ちだったんですけれども、当然、子どもを預かるような保育的な機能については持ってございませんので、病児保育室が運営可能なような一定の改修をほどこしたです。","voiceIndex":202,"id":"exchange-085"},{"speaker":"井上委員","kind":"質問・要望","question":"今ちょっと、よく仕組みがわかりませんでしたけれども、名称についても、ちょっと何か誤解を与えると思うので、要望があるのは当然だと思いますので、こんなふうな流れでつくったでしょうということにならないように、節度ある取り組みをしていってほしいなということを、同じ思いだと思いますけれども、ちょっと心配だなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":204,"id":"exchange-086"},{"speaker":"中塚委員","kind":"質問","question":"話を聞いていて、病児保育室は保育士はいらっしゃるわけですよね。それはフローレンスの社員なんですか。それとも病院の人なんですか。その保育士というのはだれなんですか、教えていただけますか。","respondent":"吉岡保育課長","answer":"病児保育室を運営をするに当たっては、看護師１名と保育士１名、配置をするという基準になっております。保育士につきましては、フローレンスというのは会社ではございませんので、社員という形ではありません。","voiceIndex":205,"id":"exchange-087"},{"speaker":"中塚委員","kind":"質問","question":"今のご答弁ですと、看護師１名、保育士１名の雇用状況は把握していないとおっしゃっていましたけれども、つまり病院に委託をし、フローレンスに再委託をし、さらにそこで働いている人は、また別のところの雇用関係がある人だという関係なんですかね。非常に責任の所在がますます不明確になってきている。つまり看護師１人と保育士１人というのは、この方たちはだれに雇われている人なんですか。","respondent":"吉岡保育課長","answer":"一義的には、再三申し上げておりますように、区と酒寄医院の契約ですので、責任を負うのは区であり、酒寄医院です。","voiceIndex":207,"id":"exchange-088"},{"speaker":"中塚委員","kind":"質問","question":"責任を負うのは品川区だと、だけれども、品川区が酒寄医院に委託をし、さらにフローレンスに再委託をし、さらにそこで働いている人はさらにその先、人材派遣会社なのか、別のところから呼んでくるのかわからないけれども、三つまたがっているわけですよね。その状況って、ちょっと不透明じゃないですか。私もやりとりを聞いて、初めてわかったぐらいなんですけれども。","respondent":"吉岡保育課長","answer":"仕様に基づいて、仕様書に規定をしたサービスを提供してもらうというのが委託契約の内容ですから、それがそのとおりにきちんと履行されるというのは、もちろん区として責任を持って確認いたしますし、受託者としての酒寄医院が責任を持って履行するという内容ですので、それ以上。","voiceIndex":209,"id":"exchange-089"},{"speaker":"中塚委員","kind":"質問・要望","question":"結局、今の話ですと、看護師１名、保育士１名がだれに雇われているのかさっぱり、ご答弁がありませんでした。しっかりそこは定めていただいて、責任の所在がどこにあるのか、不透明感をなくしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":211,"id":"exchange-090"},{"speaker":"浅野委員","kind":"質問・要望","question":"基本的なことで申しわけないんですけれども、多分簡単に答えていただけると思うんですけれども、対象となる方は、保育園、幼稚園等に通っている生後６ヶ月から就学前の子どもとなるんですけれども、保育園、幼稚園等の「等」というのは、どの範囲を示しているのか、ちょっと確認をしたい。そのときの診察費というのは発生するのかどうかということ。","respondent":"吉岡保育課長","answer":"診療費につきましては、２,０００円というのは、病児保育でお預かりする金額ですので、容態が悪くなって診療するというようなことが生じれば、それは当然、別の費用になります。","voiceIndex":212,"id":"exchange-091"}]},{"id":"topic-06","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"この支援についての制度は国で検討する。しかし、区の中でもさまざまな対応をしていくという答弁がありまして、その「さまざまな対応」について、どういうことをされているのか。「個別的に厳しい家庭」というところでは、父子家庭の生活保護を受けている割合とか、そういった基本的に、そういう方たちはどのぐらいいらっしゃるのかということを含めて、お答えいただきたいと思います。","respondent":"安井子育て支援課長","answer":"区のほうで、父子家庭に対するさまざまな対応ということで、どのようなことを行っているかということなんですけれども、品川区のほうでは、答弁で申しましたように、相談業務のほうは、母子家庭と同様に、ひとり親家庭ということで広く行っております。","voiceIndex":220,"id":"exchange-092"},{"speaker":"井上委員","kind":"質問","question":"今、言われた支援の中で、就職口があって、経済的にまだ支えがなくても大丈夫という方たちは、トワイライトステイとか、家庭あんしんセンターの利用が多分あるんだろうと思うんですけれども、そういう実績ですね、相談窓口にどのぐらいの方が相談にきていらっしゃるのかとか、レクリエーション、休養事業があったとして、どのぐらいの参加があるのか、そういうところの把握がないと。","respondent":"安井子育て支援課長","answer":"休養ホームの事業ですけれども、圧倒的に母子家庭のほうが多いということは事実としていますが、休養ホームについて言いますと、延べ１５日ぐらいのご利用があります。それから、介護人派遣事業なんですけれども、全体で１年で１５件ぐらいしかありません。","voiceIndex":222,"id":"exchange-093"},{"speaker":"井上委員","kind":"質問","question":"厳しい状況の家庭がわかっていて、その方たちに、今おっしゃっていた支援というのは、やっているということはわかりましたけれども、どのぐらい提供されているのか、区がどういうふうに、まだ課題があると思われるのか、必要なところに必要な支援がいっていますと認識をされているのか、その辺の課題、評価というか、その辺の認識はどのようなものでしょうか。","respondent":"安井子育て支援課長","answer":"そういった形で、これからは父子世帯についての対応ということで、よりご利用いただけるような形で進めてまいりたいと考えています。","voiceIndex":224,"id":"exchange-094"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほどの次世代育成のところでも、ここだけ支援すればやっていけるんだというその部分は、結構いろいろな項目が考えられると思いますので、そこはちょっと、もうそういう時代になってしまっているということを理解していただいて、ぜひ、研究、検討していただきたいということを、切に要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":226,"id":"exchange-095"},{"speaker":"中塚委員","kind":"質問・要望","question":"今度、部分日食が７月２２日にありますよね。ちょっと聞いたのが、五反田プラネタリウムの方々が少し考えているという話も伺っているので、ぜひ応援というか、アピールしていただけたらと思うんです。この機をとらえて、科学の楽しさを実感できるような取り組みをしていただきたいと思うんですけれども、いかがでしょうか。","respondent":"冠木指導課長、吉岡保育課長","answer":"理科について、子どもたちが興味を持って取り組むということは、非常に結構なことだと考えています。ご意見として承っておきます。この２園と区営住宅の改修スケジュールにつきましては、平成２１年度から設計に着手するということになっておりますけれども、詳細について、今後検討してまいりますので。","voiceIndex":234,"id":"exchange-096"},{"speaker":"林副委員長","kind":"質問","question":"一言つけ加えていいですか。あくまでも義務教育は義務教育ですから、小学校の仮設校舎を中学校に建てるとか、そういうことならまだあれだけれども、保育園の仮設を義務教育の施設の中につくるなんていうことはゆめゆめ考えないようにしてください。お願いしておきます。まだ、具体的に言わないから、こっちも具体的には言わないけれども、お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":238,"id":"exchange-097"},{"speaker":"井上委員","kind":"質問","question":"設計とかというときに、保育園の子どもたちは、工事をしながらそこにいるのか。そこだけちょっと。子どもたちはどうなるのか、教えてください。","respondent":"吉岡保育課長","answer":"ただいま、ご説明申し上げましたとおり、詳細につきましては、居ながらできるのか、あるいは仮に移転するのかも含めまして、今後、検討していくことになっております。","voiceIndex":239,"id":"exchange-098"},{"speaker":"林副委員長","kind":"質問","question":"ですから、資料をいただいているんですけれども、今までは文教委員会というと、学校教育と社会教育という範疇の他の行政を勉強、調査事項ということでしたけれども、今年は、それが変わったということを、皆さんそれぞれ意識をしておいていただかないと、どうしても学校教育というと、視察で選択するのが難しいところがあるんですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":245,"id":"exchange-099"},{"speaker":"中塚委員","kind":"意見","question":"子ども未来事業部のほうで言えば、保育園といっても、今年４月から学研こども園が開設したり、いろいろなタイプが増えているので、品川区の状況を深めていきたいという思いもあるんです。だから、なかなか難しいなと思います。ここの何年か、文教委員会でいろいろ全国の小中一貫校だったり、取り組みに行くんですけれども、向こうが恐縮しちゃう部分もあるので、これはどうしたものかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":247,"id":"exchange-100"},{"speaker":"中塚委員","kind":"意見","question":"あえて言えば、繰り返しになりますけれども、品川区の学校であったり、保育園であったり、もちろん幼稚園も公立、私立いろいろあるでしょうけれども、そういう状況を見たいなと思っています。そのことが、今の議題なのかなということはありますけれどもね。地方に行っても、なかなかうまくいくかどうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":249,"id":"exchange-101"},{"speaker":"西本委員","kind":"質問","question":"その取り組みがどうなのかと。家庭教育というのが、すごく中心的にされているということを聞いているので、ここら辺はどうかなと思っている。それから、やはり保幼小の連携というところでは、品川区は先駆的にやっているんでしょうけれども、そういうところがあれば、ちょっとお伺いしたいというところがあります。そういうところもあればいいかなと。ただ、場所はちょっと特定できてないので、すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":251,"id":"exchange-102"},{"speaker":"西本委員","kind":"意見","question":"秋田県で、全国一の学力になって、マスコミに取り上げられた部分があったので、どうして一位になったのかと聞くと、いろいろ理由はあるということで、詳しいことは聞いてないんですけれども、でもいろいろ理由があるらしいんですね。教育費から考えると、全然品川区のほうがいいですし、教育環境としては、品川区のほうが全然いいみたいなんですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":253,"id":"exchange-103"},{"speaker":"井上委員","kind":"意見","question":"テレビの報道では、家庭学習がメインで、塾に行く人がだれもいないと。ちょっと話を聞いてどうかなと思うのは、私はそこの先生が東京に出てきて、先生の話を聞いているのであれなんですけれども、高知県で、お弁当の日というのがあって、５年生でつくるというのが、大人が一切手伝わない。食の教育とか、食べ物、生きる、１年間かけて、お弁当の日という大イベントに向けての教育カリキュラムがあるんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":254,"id":"exchange-104"},{"speaker":"林副委員長","kind":"意見","question":"私は大きいくくりで言うと、山口県の萩市とか、松下村塾とか、いわゆる日本の教育の始まりみたいな、原点みたいなものを探りに、学校教育の関係でいくと。やっぱり勉学にいそしまなきゃいけないんだということを学んでくる、みんなが、委員が学んでくる。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":257,"id":"exchange-105"},{"speaker":"井上委員","kind":"質問","question":"文教委員会の平成１９年度の図書館機能の充実というところでは、何か、品川区は、多分図書館は充実している地域だと思うんですけれども、ないところでいくと、図書館が教育のメインというか、拠点というような感覚が、ほかの地方都市ではあると思うんです。ここで何か得たものがあって、その先にもうちょっと違う視点で、というのはないでしょうか。","respondent":"古川子ども未来事業部長、市川教育次長","answer":"これは、鶴岡市の日本で一番の読書活動のところですね。地方の図書館というのは一点豪華主義で、いいなと思うことはあっても、その距離を縮めるというのはなかなか難しい。","voiceIndex":258,"id":"exchange-106"},{"speaker":"本間委員","kind":"意見","question":"もう一つは、特色ある学校づくりの一貫だと思いますけれども、やはり、学力という部分がかなり出ていますけれども、体を鍛えるスポーツの部分だとか、音楽だとか、文化というような部分で、かなりいい指導者がいて、レベルアップして日本一だとか、それぞれの地方の一位になったというようなことがときどき出ますけれども、指導者がちょっと変わると、次が続かないというようなことがあるので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":264,"id":"exchange-107"},{"speaker":"本間委員","kind":"意見","question":"そういうことがあったということを聞きまして、よけいちょっと行ってみたいなと、その後どうなっているのかなと。そういうふうに歴史的なさかのぼって原点を振り返って勉強ができるようなところも、委員会としては、新しいものに飛びつく部分はありますけれども、もう１回基本に返って、探って、自分自身も勉強するというのもあっていいのかなと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":266,"id":"exchange-108"},{"speaker":"中塚委員","kind":"質問・要望","question":"教育の原点を探ってみるという話に、少し感じたんです。つまり、いろいろな時代で、上を求められる教育も変わってくるとはいえ、原点というものがやっぱりあるだろうなと思うんですよ。ただ、やっぱり、読み書きができて、基礎学力ができて、それが町だったり、村だったりの発展になる。教育の原点に戻ったときに、そういう時代、時代の流れというんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":267,"id":"exchange-109"},{"speaker":"本間委員","kind":"意見","question":"特に山口県というのは、どこかで聞いたことがありますけれども、総理大臣の数が一番だったか、ということを記憶しているんです。そんなことがあって、偉大な、優れたそういう偉人がどうして生れたか、どのような教育だったのか、教えはどうだったのかみたいなものも探りたいなという興味があると思っていました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":268,"id":"exchange-110"},{"speaker":"井桁委員","kind":"意見","question":"特定のここというのはあれなんですけれども、今回、文教委員会の中で、子ども未来事業部が入り、先ほども、報告事項の中でもあったように、保幼小の連携というのをもう１回、新たな体制になった上で、改めて見に行くというのもあるのかなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":269,"id":"exchange-111"},{"speaker":"浅野委員","kind":"意見","question":"具体的にどこというのはないんですけれども、私が今回、青少年健全育成ということで大きなことを言わせていただいたんですけれども、やはり学校は学校として、その周りの環境を考えた場合には、地域性というものが、随分影響されるのかなと思うんです。例えば都会で、こういうような環境の中で、子どもが育つ環境。具体的なところは浮かばないんですけれども、そういうことは希望したいです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":270,"id":"exchange-112"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4674#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":86397,"voices":274}},{"id":"h21-20090623-5","meetingId":"h21-cm06","date":"2009年6月23日","dateIso":"2009-06-23","committee":"総務委員会","time":"午前１０時０３分～午前１１時２６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"土井委員","kind":"確認","question":"じゃあ、もう１つ前のページの２２ページの安心生活創造事業補助金というのがありまして、高齢者の安否確認のところに補助金がついていますが、１０分の１０です。その辺は、この予算書の中では見えないものですから、１回１０分の１０入れたらずっと来るもんだとみんな信じていいのかという問題が起きますので、何かわかる方法はないのかなというのを含めて、ちょっとお聞かせください。","respondent":"金子企画財政課長","answer":"緊急雇用の問題ですが、これは東京都のほうで平成２１年度予算で計上してありますが、私どもは平成２１年度予算の編成が終わった後に存在が明らかになってきたもので、平成２１年度になりまして私どもは鋭意検討しておりましたけれども。","voiceIndex":5,"id":"exchange-001"},{"speaker":"土井委員","kind":"確認","question":"そうすると、それは場合によっては国の補助金がなくても一定程度続けなきゃならないとか、こういう問題が必ず起こってくるものですから、今のようなお話を、３年間の間に基礎をつくって、それは国のほうの勉強料としてとりあえずモデルのときには１０分の１０くれるけれども、今度はどうなのかというのはわかんなくなっちゃうようになりますね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"本多委員","kind":"質問","question":"２７ページの民間駐車場、コインパーキング２２台分の予算がついておりますけれども、庁舎に用のある方がその駐車場を使用されて、どこが窓口になるのかと、あと、その駐車場には表示がされるんでしょうか。その今の庁舎の耐震工事の期間までというふうな期間で考えていいのか、それを教えてください。","respondent":"阿部経理課長","answer":"区役所の中の各課にはそういう周知をしてまいります。期間ですけれども、今委員がおっしゃったように、総合庁舎が耐震工事をしている期間です。総合庁舎の耐震工事が終われば従来どおり第１駐車場が使えますので、要するに、平成２３年３月までというふうに考えております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"続けて、２９ページの発熱相談センターの保健師の雇用について教えていただきたいんですけれども、この対応については迅速な対応で、必要なことだと思うんですけれども、今後どのように発展していくのか、フェーズ６ということなので、ほんとうに危機管理を持って対応していただいていると思いますが、雇用の期間とか、その辺の、雇用についてはどのように考えていくのか教えてください。","respondent":"金子企画財政課長","answer":"発熱相談センターの運営についての説明ですけれども、今現在事務職が対応し、専門的な相談を保健師が担うというふうな対応にしておりますが、区の発熱相談センターの運営とともに、それから、東京都が２４時間対応しておりますが、こちらにも、毎日というわけではありませんが。","voiceIndex":11,"id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問","question":"緊急雇用のところでちょっとお伺いしたいんですけれども、まず、歩行喫煙と屋外広告物取締、放置自転車対策、それぞれありますね、こういうのは延べ人数といいますか、どのぐらいの雇用になるんですか。","respondent":"金子企画財政課長","answer":"緊急雇用の延べ人数ですが、私どもは人日という計算をするんですけれども、トータルで５,７０２人日が、１日１人が５,７０２人というふうな数値で予定しています。","voiceIndex":15,"id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"要するに、延べ人数ということですね。今回緊急雇用創出というのは３つの内容なんですけれども、これは東京都のほうから１０分の１０なんですけれども、緊急雇用については東京都のもっといろいろメニューがあったんじゃないかなと思うんですけれども、東京都のこのメニューのおおよそのところを、どういうのがあったかという、この３つを選択してやるんですね。これについて教えていただければと思います。","respondent":"金子企画財政課長","answer":"そういう意味では、今回は安全・安心といいますか、そういったところで考えているわけですけれども、私どもはこの緊急雇用の補助金を使うに当たって、区としての行政ニーズももちろん考えなければなりませんが、これはあくまでも、先ほどご答弁申し上げましたとおり。","voiceIndex":17,"id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問","question":"それに係わってもう１点なんですけれども、これは都からの１０分の１０なんですけれども、各自治体での、何というか、枠というか、そういうのがあるのか。例えば、これを選ぶとほかのは選べない、そういう規制がかかることなんですか。","respondent":"金子企画財政課長","answer":"東京都全体では、ご案内のとおりですが、３０億円というふうな予算になっておりますが、一応区の割り当てというか、目安で９,０００万円を提示されているところです。","voiceIndex":19,"id":"exchange-007"},{"speaker":"宮崎委員","kind":"提案","question":"住宅の耐震化の強化なんですが、そういうものというのは今急いでいる部類に入るんじゃないかと思うんですね。そういうところでの雇用創出だとか、それと合わせた、耐震化の促進とか、そういうのもぜひ今後、今回はこういう内容ですけれども、今後また出てくる場合には考えていただきたいなという、要望をしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今の緊急雇用の部分は、宮崎委員と大分聞きたいことが似ていたんでやめておきますけれども、庁舎の駐車場のことを聞きたいんですけれども、予算の組み立て方を教えてほしいんですね。そうなると、実質台数をどれぐらいで見込んで、どういう台数でこの２時間券をどれぐらい出してという予算組みの仕方があると思うんで、予算をどのように見込んで、どうやって組んだのかというのを教えていただきたい。","respondent":"阿部経理課長","answer":"駐車の件ですけれども、大体１台当たり単価として３００円を見込んでいます。それで、それは５回転するだろうというふうに思います。というのは、今第２庁舎のほうが大体１日平均７００台ぐらいとまります。実際は約５０台ですので、大体そのぐらいの回転をするわけです。","voiceIndex":23,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"意見","question":"半分ぐらいわかったようで半分ぐらいわかっていないんですが、１台当たり３００円で、それは５回転だろうと。そう考えると、今２２台あると５回転すると５倍で見ているという見方でしょう、ということですね。あいているところはバラバラであったとしても、その５台分の効果というふうな見方を私らが感じておけばいいのかというのかな。","respondent":"阿部経理課長","answer":"実際の第２駐車場の使われ方もそういう形ですので、延べにすれば７００台ですけれども、使い方として、３０分で借りられる方もいますし、会議に来れば当然長くなるという方もいらっしゃいますし、先ほど申し上げたとおり。","voiceIndex":25,"id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問","question":"それをあまり３０分だ何だというと、実質３台分のフルかなというふうになっちゃうから、と思うんだけれども、こういう予算の組み方はそれでいいんですけれども、それだけはちょっと教えてほしかったなと思っているんで、私の理解はそれでいいのかなということだけを教えてほしい。５台分ぐらいでと思っていていいんですか。","respondent":"阿部経理課長","answer":"ですから、台数としては５台分なのかどうなのかということはあるとは思いますけれども、考え方としては私どもそういう考え方をしておりますので、ご理解いただきたいと思います。","voiceIndex":27,"id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういうことを言うと、突っ込むとさ、８時から５時まで工事車両なんかとめているんだから、ずっととまっちゃっているんだから、何曜日とか、曜日の問題とか、朝とか関係ないと言われちゃうとそれまでだから、ぜひそういう、民間を借りて区民サービスをよくするためにこういうことをしたんだというのを前面に出していただいたほうがいいかなと思うんで、それはそれだけお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問・要望","question":"いわゆるコイン駐車場も場所によってちょっと値段が違ったりもしているところがあるんですけれども、こういう場合はかなり区のほうも要望したり、設置者のほうとしてはしっかり利用が増えているということになるとは思うんですけれども、利用単価といいますか、利用料金の交渉というのは、それはされているんでしょうか。","respondent":"阿部経理課長","answer":"利用料金は３０分幾らというふうに決まっていますので、それは料金交渉をしましたけれども、一般の車両も入りますので、それの単価でやっていただきたいというふうなことになりました。","voiceIndex":31,"id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"今のセキュリティシステムにつきまして、部品の再調達が必要になるんだということと、センターとの通信のところで不都合が生じたというんですけれども、今は契約を変更して、１２月の末を納期に、今順調だというふうな話を聞いたわけですけれども、この機械は製造中止になって、部品が製造中止になって、いろいろ新たに開発しなきゃいけない、そういう状況になったということなんですけれども。","respondent":"金子企画財政課長","answer":"今現在の進行状況ですけれども、私の聞いている範囲では、端末であるまもるっち、これについての設計と、それから、あわせてそのシステムに関しての再度の設計ということを現在実施している段階で、そういう意味では。","voiceIndex":53,"id":"exchange-014"},{"speaker":"宮崎委員","kind":"意見","question":"今のお話で、再設計というのが、それが順調かというと、それはちょっと順調というふうに言う内容じゃないんじゃないかなと私は思うんですよ。私は少なくとも議会への説明であれば、やはり実際に機械がもう開発できましたというんであれば、今みたいな説明でやればいいと思うんですけれども、ちょっと認識が違うなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":55,"id":"exchange-015"},{"speaker":"須貝委員","kind":"質問・要望","question":"それをこういうふうにやはり切られちゃうということは非常に残念だし、品川区としても大変悔しい思いをされたと思いますが、何かその辺の、危機管理といったらちょっと大げさかもしれないんですが、何か対応策というものはちゃんと考えておいたほうがいいのかなと、製造に対する、どこまでやれるかわかりませんが、それだけちょっと要望はしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-016"}]},{"id":"topic-02","title":"専決処分の報告について（報告第１５号）","agenda":"専決処分の報告について（報告第１５号）","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"私は思うんですが、やはりバックというのは自分らが運転していても本当に危険だと思います。そのときにバックブザーをつけるなり、バックをするときは鳴らすよと。だから、バックするときはハザードランプとバックブザーは必ずつけなさいと、そういうふうにやはり周りの人に注意を喚起するということも１つの事故防止になるかと思いますので、その辺、もし何か対応ができましたらご検討願いたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-017"}]},{"id":"topic-03","title":"新型インフルエンザ対策","agenda":"新型インフルエンザ対策","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"加湿器なんかももちろんいいというお話を聞いているんですが、そういうところにできるだけ、できる範囲、やれることは設置等考えて、区のほうとしても対策をとっておくということは大切じゃないかなという気がするんですが、実際そういうことは、あくまでも今は手洗い、うがい、マスク着用ということで徹底していますが、そういうことというのは何か考えているんでしょうか。","respondent":"伊勢危機管理室長","answer":"そういう面で、いろいろな面で、マスクをするということも場合によってはありますけれども、消毒液を手に塗るということはもちろんですけれども、室内の環境を衛生上きれいにしておくということも大切です。","voiceIndex":69,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"今のところまだそういう、施設に人だとかたくさんいる、お子さんが多いところに対して特段の、先ほどお話しした空気清浄器を設置するとか、加湿器を設置するとか、そういうことに関してはまだ検討段階には入っていないということでいいんでしょうか。","respondent":"伊勢危機管理室長","answer":"職場の衛生環境は今私が申し上げた部分ですけれども、具体的にほかにもいろいろあるかとは思いますけれども、この辺につきましては保健所と連携しながらまた詰めていきたいと考えております。","voiceIndex":71,"id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問","question":"今回は企業、事業所対象に講演会をやるようですけれども、今回はどういうところを主に対象にして案内しているのか。それとあと、事業所の数でいったらもっと全然多いんですけれども、いろいろな例えば業種ごとの対応だとか、そういうところというのは今考えているんでしょうか。","respondent":"伊勢危機管理室長","answer":"このご案内は広報しながわ６月１１日号でも載せましたわけですが、その前段といいますか、保健所に、実は企業の関係の方で、会社の事業継続計画をどうしたらいいかとか、職場の衛生管理をどうしたらいいか、あるいは、社員の方がそういうことでお休みになった場合。","voiceIndex":73,"id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問","question":"今私がちょっと気になっていたのは、先着２００名ということなんですけれども、もっといっぱいあるんじゃないか、そういうところの対応をこれからどうするのかなというところなんですけれども、そこのところを、改めて伺っておきたいんですけれども。","respondent":"伊勢危機管理室長","answer":"広報しながわだけじゃなくて、ホームページにもリニューアルしながら新型インフルエンザのご案内をしていますけれども、区民、あるいは、企業の方、それぞれに周知方法を工夫しながらもっと多く広げていく必要があると、こういうふうに思ってあります。","voiceIndex":75,"id":"exchange-021"},{"speaker":"山元委員","kind":"意見","question":"今の宮崎委員のと関連するんですけれども、やはりまだまだあると思うんですけれども、この時間帯がちょっとこれ１時半から３時半ということで、できれば、逆に仕事が終わった後の時間帯なんかも開催する予定というのはありますか。","respondent":"伊勢危機管理室長","answer":"企業への説明も、今回は保健所と危機管理室で１時半からということでやったんですけれども、やはり企業の方の勤務時間等を考えてどうかなという部分も、この前に検討としてございました。","voiceIndex":77,"id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"意見","question":"その発熱センターの問題も、もちろんあけておかなくちゃならないんだろうけれども、多分この時期本当にそれがいいことなのかというのも、どこでやるんだということもしっかり、それは１回話ししてもらったほうが、役割分担の部分が我々ももう一度、先ほど２４時間東京都がとか、だから、品川区は９時から５時だと、この時間帯の問題ももっとしっかり東京都とよく話をして。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-023"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"行政視察先なんですが、できれば、場所は委員長、副委員長にお任せするとして、東京２３区、特に品川区に類似している、そういう都市に関して、それぞれやはりやっている内容がかなり類似している中で、いろいろな工夫をされて行政活動をつかさどっていると思うんですが、そういうところをもし選定していただければありがたいな。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":89,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1826#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":25909,"voices":99}},{"id":"h21-20090624-14","meetingId":"h21-cm06","date":"2009年6月24日","dateIso":"2009-06-24","committee":"行財政改革特別委員会","time":"午前１０時０３分～午後０時１８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"ただいまから、行財政改革特別委員会を再開します。 これより特定事件調査を行います。 跡地活用に関すること","agenda":"ただいまから、行財政改革特別委員会を再開します。 これより特定事件調査を行います。 跡地活用に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"東品川のほうと大崎第二地域センターのところで、いろいろ２０年の用途の限定があるというお話もありましたが、それぞれについて、具体的にはどのような時期から跡地の活用について区としては考え方をまとめていくのか、それとあわせて、それに対しての区民の皆さんに対する意見聴取というのは、どのような形でいつごろから予定しているのかということをお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"大崎第二地域センターの跡につきましても、権利関係や建物の構造上とか、どういう活用ができるかを今後、調査・研究をしながら具体的な検討を進めていかなければならないですので、今の時点でいつから跡地を考えていくのかというところであれば、もう跡地につきましては。","voiceIndex":6,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"そこで伺ったわけなんですけれども、もう少しそこら辺の意見聴取という点では、どういうタイミングで、どういうところの部分について意見を聞くのか、どういうやり方で聞くのかというようなところを、特に東品川と大崎のほうでは聞きたいと思います。","respondent":"久保田行財政改革担当課長","answer":"先ほどもご説明いたしましたように、まだ今、具体的にこういう活用ということが決まっておりませんので、具体的にいつの時期ということはご回答できませんけれども、私どものほうとしましては、その活用の内容等を研究した上で、どういった活用ができるのかというところ。","voiceIndex":8,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"まとめる時期のあたりというのは、それぞれいつぐらいなのかということと、今考えている時期があると思うんですけれども、それがいつなのかというのを教えていただきたいのと、あと、区が一定の考えをまとめる前にいろいろな形で地域から要望が上がった場合、それはどのように区としては対処、処理していくか、どういうふうに受けとめていくのかという考え方をお聞かせください。","respondent":"久保田行財政改革担当課長","answer":"まとめる時期ですけれども、東品川清掃作業所につきましては、東京都の交渉で用途指定がかかっておりますので、そうした意味では、具体的にいつまとめるといったことは現時点ではお答えできないというふうに考えております。","voiceIndex":10,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、質問なんですが、主体的に区がつくるという案と、そこに区民の声を受けとめていくという答弁がありましたけれども、その主体的な区の案にどのように区民から上がった意見というのは反映されていくお考えがあるのか聞かせていただきたいんですけれども。","respondent":"久保田行財政改革担当課長","answer":"私どもとしましても、そうした中で、荏原地区におきまして、そういう文化施設やスポーツ施設といったものの整備も必要ということで主体的に判断しまして今回の跡地活用をさせていただいたところですので、そうした意味では。","voiceIndex":12,"id":"exchange-004"},{"speaker":"安藤委員","kind":"確認","question":"確認なんですが、大崎第二地域センターに関しては、今年度中に一定の案が出るのかなということで考えているということで、そこに区として一定の考えを主体的に出すという上でも、区民の声を聞かないでつくるというつもりはないというお答えがありましたので、区民の声を聞きながら今年度中に一定の区としての主体的な案を出していきたいということで私は受けとめましたけれども。","respondent":"久保田行財政改革担当課長","answer":"繰り返しの答弁になりますけれども、そういった活用案をつくる中では、区民の声というものも受けとめながら考えていきたいというふうに考えております。","voiceIndex":14,"id":"exchange-005"},{"speaker":"川西委員","kind":"質問","question":"最初に質問いたしますのは、大崎第二地域センター、建築年度が昭和４７年３月ということで大分たっています。さっきの説明では崖ということもありました。昭和４７年築で、新築ではなくて改修工事というのはできるのでしょうか。最初にちょっとそれだけ伺います。","respondent":"久保田行財政改革担当課長","answer":"大崎第二地域センターの建物ですけれども、構造が鉄骨造りというところがありますので、正直言いまして、なかなか改修等でというところは、どこまでできるのかも含めまして今年度調査をさせていただいているというところでございまして、構造的に鉄骨造りということですから。","voiceIndex":16,"id":"exchange-006"},{"speaker":"川西委員","kind":"質問","question":"今の大崎から申し上げますと、やはり１１月にあきまして、あまり廃屋状態に長い間しておくことは私はむだだと。そういうことで、今から、もうそういう状況を、新築できるのかどうか、改修が可能かどうかというような調査活動をされることを希望します。希望ですからお答えはいいです。ですから、やはりかなりああいう状態で長く使われているということもありますし、平米数もかなりまとまっています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどそれぞれの施設、１、２、３、４、５、６の施設の説明で、周辺の環境について幾つかご説明がありましたけれども、伺いたいのは、どういう視点で周辺の環境を調査しているのかという、その視点というのがよくわからなかったんですね。周辺の環境について調査をするそのカテゴリーというんですか、視点というんですか、そこをちょっとご説明いただけますか。","respondent":"久保田行財政改革担当課長","answer":"委員からお話があったように、例えば商業の何かとか、工業の誘致とか、そういうもので調査をした結果を説明させていただいたというところではございません。","voiceIndex":20,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"この委員会のテーマでもあるんですけれども、行政需要をつかむ、地元の要望をつかむ、そういうときにどういうカテゴリーで把握をしていくのか。そこをどんなふうにお考えなのか教えていただきたい。そういう行政需要をつかむときに、どういうカテゴリーで周辺環境を見ていくのか、そういう視点を持つべきだなというふうに思うんですけれども、カテゴリーについてご説明いただけますか。","respondent":"久保田行財政改革担当課長","answer":"そうした集計の中でも、地区別の要望、地区別に分けて集計といったところもありますので、そうしたことも踏まえながら、あとは区の施設の全体の状況、品川区としましては、やはりかなり行政の施設等は充実しているのかなというところでは認識はしているところですけれども。","voiceIndex":22,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"あわせて、その行政需要をつかむときに、やっぱりデータに落としていくというんですか、病院だったり、公園だったり、今、いろいろな行政需要があるわけですけれども、それはやっぱりデータに落としていって、その上で、ある意味、客観的に把握をしていく、そういう視点というのがないと、その地域で本当に何が求められているのかというとき。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-010"},{"speaker":"阿部委員","kind":"質問","question":"大崎第二地域センターの隣にあったシルバーセンターは、あれはいつごろの建築で、構造がどうなっているか、まずわかれば教えてください。４番の第一日野のところというのは、あれ、前回の委員会のときに、駐車場として貸すかもという話だったと思うんですけれども、それは敷地全部を前提とした話だったのか、それとも一部といいますか、それでも構わないのか、その辺をちょっと教えてください。","respondent":"久保田行財政改革担当課長","answer":"昭和４８年の築です。構造も、軽量鉄骨造りというふうに伺っております。第一日野小学校の跡地を代替の駐車場として貸すです。一応、敷地全部ということを想定しております。一部ということではなくて、全部というところです。","voiceIndex":25,"id":"exchange-011"},{"speaker":"阿部委員","kind":"質問","question":"それは、全部フルでなければ向こうの、要は、相手方の意向に沿わないということなのか、とりあえず全部ということなんですか。","respondent":"久保田行財政改革担当課長","answer":"その後、いろいろと細かい話し合いをしていますけれども、向こうのＴＯＣ自体もいろいろ都市計画だとか、そういう関係の進めているところもありますので、細かいところの協議にまだ至っていませんけれども、基本としては全部を貸していくというところを基本としております。","voiceIndex":27,"id":"exchange-012"},{"speaker":"阿部委員","kind":"質問・要望","question":"今の質問というか、ご答弁を踏まえて、それぞれこの先は意見になっていきますけれども、まず１番の土木事務所なんですが、何度もお話に出てきているように、非常に場所がいいということで、いろいろこれから活用策、民間の可能性も探りながら活用策を考えていくことになると思うんですけれども、ぜひ部分的にでも、だれでも使える場所をつくってほしい。これは要望です。ちょっと先走り過ぎました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-013"},{"speaker":"須藤委員","kind":"質問・要望","question":"じゃあ、そのときに絵をかくかというのではなくて、最初からもうこういう方向に持っていきたいんだというものを民間活用含め考えていったらどうかと思うんですけれども、そういう考え方はどうですか。やはり区民、品川区全体の絵から見て、どういうものを落とし込んでいくんだというのが行政側に議会から求めていきたいな、そんなように思っているんですが、いかがでしょうか。","respondent":"久保田行財政改革担当課長","answer":"先ほどもご説明がありましたけれども、用途指定がかかっているというところ以外にも、りんかい線が地下を走っているといったところもありますので、どういった活用ができるのかといった調査・研究も並行して進めていきたいというふうに考えているところです。","voiceIndex":30,"id":"exchange-014"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"それをどうやって資料化する、データ化するというのは、確かにちょっと捩り鉢巻が必要だなというのは感じるんですけれども、おそらく今、パッと出るような資料ではないとは思うんですけれども。要は、基本的に行政需要が満たしている、そういう視点はやっぱり違うなと思うので、よくよく行政需要を土台にした上でみんなで議論できるような進め方にしていただけたらなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5864#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":14555,"voices":36}},{"id":"h21-20090625-15","meetingId":"h21-cm06","date":"2009年6月25日","dateIso":"2009-06-25","committee":"環境対策特別委員会","time":"午前１０時０２分～午後０時３８分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山路委員長","kind":"質問・要望","question":"○午前１０時０２分開会おはようあります。前回、委員の皆様からいただいた意見を踏まえ、今後の委員会の運営方法や建設委員会との仕切りなどについて、正副委員長で再確認をさせていただきましたので、改めて説明をします。建設委員会の調査事項との仕切りの再確認ですが、当委員会は、調査事項として地球温暖化対策に関すること、水辺とみどりの整備に関することの２項目について付託を受けてあります。","respondent":"工藤環境課長","answer":"現在、２０１３年度以降の枠組みについて検討が進められている。締結国会議を中心としてさまざまな検討が始まっているところです。昨年、２００８年７月に、北海道の洞爺湖サミットで、日本が議長国を務めたＧ８の会議がございました。","voiceIndex":1,"id":"exchange-001"}]},{"id":"topic-02","title":"題に供します。今回は、地球温暖化の現状についてと、品川区地球温暖化防止対策実行計画（第二次）について","agenda":"題に供します。今回は、地球温暖化の現状についてと、品川区地球温暖化防止対策実行計画（第二次）について","exchanges":[{"speaker":"南委員","kind":"確認","question":"そういう中で、一番最後のところに、日本が中期目標を掲げてこなかったことに対して、ようやく中期目標ということになったわけですけれども、しかし、１９９０年比ではなくて、２００５年比で１５％というふうになっているんですけれども、これ、１９９０年比にするとどの程度のものなのかというのを共通認識にしておかないと。","respondent":"工藤環境課長","answer":"政府が６月に発表しました中期目標の件です。発表では１５％ですけれども、これは２００５年度比です。それで、新聞報道等で見ますと、１９９０年比でいいますとマイナス８％という部分ですので、逆に１９９０年比でやると表記としてはマイナス８％になる。その差が７％です。","voiceIndex":5,"id":"exchange-002"},{"speaker":"南委員","kind":"意見","question":"マイナス８％に過ぎないというふうに私は思うんですよね。それで、１９９０年比でとらえていかなければいけないというふうに思うわけで、日本のいろいろなところでそういう方向で議論してきた結果、２００５年比になったという状況もあわせて、区としてどういうふうに認識しておられるのかを聞いておきたいと思うんです。","respondent":"工藤環境課長","answer":"この政府目標というのも、またいろいろと世界のこの次の１２月のデンマークの会議にかけるときに、またどう変わっていくのかというのもわかりませんし、最終的に国際間のほうで１９９０年比に戻るのか、それとも２００５年比でいくのかというのは。","voiceIndex":7,"id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"できないこともできるだけやれる方向にもっていくという立場に立たないと、全然進んでいかないと思うし、区民の皆さんにもいろいろとそういう意味で啓発を含めて取り組む姿勢に、後ろ向きととらえられてしまっては効果が出ないというふうに思いますので、やはりこういう認識はあるのではあればやめるべきだというふうに思うんですけれども、改めて２００５年比にしたというところと。","respondent":"工藤環境課長","answer":"ですから、私どもは当然この削減値というものは重く受けとめておりますし、当然そのような認識のもとで今後いろいろと温暖化対策を進めていくというのは間違いございません。","voiceIndex":9,"id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"今の答弁、なおさらちょっと納得できないというふうに思うんですけれども、だから、質問を繰り返すことになってしまうんですけれども、中期目標のところが、いや、今のこのことに関して質問どうですかと言われているから質問しているだけでありますので、ぜひそういうことで理解していただいて、聞いていただきたいと思いますし、もし意見があるのであれば。","respondent":"久保田都市環境事業部長","answer":"ただ、今の目標の立て方というのは、先ほど課長が説明したとおり、実際１９９０年度比で比べるとマイナス８％であるということは、これはもう認めているわけです。","voiceIndex":11,"id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"ですから、そういうことをもって品川区としてそこを受けとめながらやるということは、私はあまりにも不十分だし、もっともっと環境先進自治体というふうにしていくべきだと思いますので、この間の説明はわかりましたけれども、最後のところの部長の答弁では納得できないと思って、その部分だけちょっと意見を表明して終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-006"},{"speaker":"浅野委員","kind":"質問・要望","question":"その上でのマイナス６％を平成１８年度基準にしたと私は認識しているわけなので、このベースとなる部分はしっかりと押さえた上で、例えば２００５年のマイナス１５％も、実は品川区としてはどういうような目標になり得るのかというようなことも、しっかりと連続した形で押さえていっていただきたいなと考えています。","respondent":"工藤環境課長","answer":"１９９０年比、品川区でどれぐらいとらえているかというのは、品川区の実行計画の部分ということでよろしいでしょうか。地域の全体ではなくてということでよろしいでしょうか。それとも……。ちょっとその辺のところがわからないのですけれども。","voiceIndex":14,"id":"exchange-007"},{"speaker":"浅野委員","kind":"質問","question":"１９９０年の数値があれば、ある意味では京都議定書に対してどのぐらいというのが出ると思うんですけれども、数字がないというのは残念ですけれども、推定でもやはりある程度の数字というものは出しておくのがいいのかなと思うんですね。これは実際、どのくらいまで減になったのかというのを私も情報として持っていなかったので、それだけ１つ教えてください。","respondent":"工藤環境課長","answer":"この件につきましては、次の実行計画第二次の部分でご説明しますので、その中の説明の中に入れします。","voiceIndex":18,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"確認","question":"だから、目標を話すことは簡単なんだけれども、実行するにあたってさまざまな対策を講じる基礎になる。そういうことをぜひお伺いしたいのと、やはりそれをするためには、今までの努力ではかなわないわけでありますから、そのことをきちんと把握をしていった上で、私たちも対処していきたいと考えていますので、品川区として例えば１５％削減も含めてどういうお考えをお持ちなのかを聞かせてください。","respondent":"工藤環境課長","answer":"当然その中で、さまざまな検討を行いながら、温暖化に対する対策という部分を計画の中に盛り込みながらやっていく。その計画をつくるところです。","voiceIndex":20,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"何としてでも２℃以内に抑えないと、人類が地球で生存していかない事態になってしまうんだということを強調しているので、私はこの点が一番大事であるなと思うので、その点を確認したいのと。数値目標の認識を一致させないと何ができるのかできないのかというところに至ってくると思うので、ぜひその点をもうちょっと詳しく教えていただきたいと思います。","respondent":"工藤環境課長","answer":"認識としましては、今、お話ししたとおりでございまして、詳細につきましては私どものほうもすべての報告書を読んでいるということではございませんので十分な把握はしておりませんけれども、こういった部分を十分今後把握していきたいというふうに思っております。","voiceIndex":23,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、この３点の目標に対して、世界の国々が、いろいろお国によって事情が違うんでしょうけれども、国の事情を踏まえつつも、どうこの目標に向かっていくのか。東京都はどうなのか。特に、この東京はと書いてあるから、うん、品川区は一体どのくらい上昇したのかなというのを素人目にも知りたいと思うので、その辺はちょっと調査をしているのかどうかもあわせてお聞きしたいと思います。","respondent":"久保田都市環境事業部長","answer":"そういうところから言うと、ヒートアイランド現象と温暖化現象というのは共通するところもあるんですけれども、見方としてちょっと分けて考えたほうがいいというところもありますので、その辺は一緒くたになっちゃうと。","voiceIndex":25,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もちろんそうだと思います。地球温暖化のＣＯ２の排出量の増加でどのくらいなのか。やはり科学的にそういう分析をして伝えてほしいなという部分もありますので、もし、そういうデータがあったら、ぜひ出していただきたいなと思います。そこら辺は出せるんですかね。どんな意見があるのかという、さまざまな意見があるんだったら、ぜひぜひ載せて、ご報告をいただきたいと思います。いかがでしょうか。","respondent":"久保田都市環境事業部長","answer":"今のところで、東京都のデータとか何かであれば、それは出せるんですけれども、なかなかちょっとそこら辺の先ほどの見方もちょっと違ったりというのでばらつきもあるので、そこができなければちょっとお出しできないかなというところをご理解いただければと思います。","voiceIndex":27,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"さまざまなデータとかさまざまな見解があると思うので、本委員会で議論を深めるという意味では、そのさまざまをやはり出していただきたいし、いろいろな角度で検討していくと、より理解が深まると思っていますので、今後の運営でよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-013"},{"speaker":"林委員","kind":"意見","question":"いろいろな国の状況、世界の状況というのをつかみながら、品川区政がどういうふうに導いていくか。この次の２つについて出てくるわけだ、品川区自体がどうするのか。リーダーとしての品川区の考え方はどうするのか。あるいはこの委員の中で、どういう進め方を要請するのかという議論をしながら進めないと、よその批判とか感想とか述べあっていてもしようがないと思うので、それだけはお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"今の委員の話を聞いていたら、私の一番最初の質問のことをとらえて言っているのかなというふうにちょっと聞こえたので、そうであれば、違っていればいいんですけれども、そうじゃないということでちょっと誤解のないように発言させていただきたいと思うんですけれども、共通認識を持って地球温暖化の実態がどうなっているのか。ですから、イデオロギーという言葉は、これは正確ではないし誤解を与える。","respondent":"工藤環境課長","answer":"平成１９年度の実績を報告する前に、全体的に計画につきましての趣旨を、この冊子、５０ページに及びますので、要点をかいつまんでご説明をいたします。こちらのほうの冊子、まず開きまして目次を見ていただきますと、６つの章立てになってあります。","voiceIndex":33,"id":"exchange-015"}]},{"id":"topic-03","title":"ほかにご質疑はないようですので、次に、品川区地球温暖化防止対策実行計画（第二次）","agenda":"ほかにご質疑はないようですので、次に、品川区地球温暖化防止対策実行計画（第二次）","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"係数が変更になったために、電気によるＣＯ２の排出量が削減されたということなんですけれども、それと全体の品川区の組織、第二次計画では第一次計画より対象になる施設が大きく増えたということを、今出てこないのであれなんですけれども、具体的にはどこにどういうふうな対策がされているかというのをもし説明していただければ、全部つぶさにではなくてもいいんですけれども、大まかなところに。","respondent":"工藤環境課長","answer":"対象が増えたということで品川区としてどういった対策をとっているかです。平成１９年度の部分というのはこちらのほうに記していないんですけれども、平成２０年度で説明しますと、ちょうどこの計画書の４９ページをご覧になってください。","voiceIndex":37,"id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"ここで紹介されているのは全体の中の一部で、保育園、児童センター、学校が主なところだと思うんですけれども、それぞれエアコンだとか照明だとか、中には街路灯とか給湯だとかポンプだとかというふうに紹介されているんですけれども、これはもちろんなんですけれども、今後の問題としてやはり太陽光発電だとか、そういったものも含めて設備を整えていく方向で考えておられるんだろうと思うんですけれども。","respondent":"工藤環境課長","answer":"こちらのほうには記載していませんけれども、学校のほうでも改築にあわせて太陽光の街路灯を入れましたり、いろいろと今やっているところでございまして、荏原西地区の小中一貫校や第一日野小学校、第三日野小学校等でも自然エネルギーを入れているような状況ですので。","voiceIndex":39,"id":"exchange-017"},{"speaker":"伊藤委員","kind":"質問・要望","question":"マイナス６％の削減ということを言うと、考えながらこれを見ていたんですけれども、今やっていることはもちろんこれからも進めていただきたいんですけれども、ただ、これだけでいいのかな。これからの考えですけれども、そのことについてお聞かせいただきたい。そういうことについての現時点のお考えをお聞かせください。","respondent":"工藤環境課長","answer":"ただ、そうしますと、やはり経費の部分もありますし、契約の部分、予算の部分もありますので、そういった部分に関しましては私どもも総務部のセクションのほうと、契約の方法でそういった部分を少し前面に出せないのかどうかということは。","voiceIndex":41,"id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、これを具体化していくにはいろいろなハードルがあるのも確かな話なんです。いろいろなことがありますから、非常に難しい質問なんですけれども、そういうことを抱えながらも、品川区がどういう対応していくかということをお伺いしたいと思います。","respondent":"久保田都市環境事業部長","answer":"結論的にお話ししますと、そういう形で今までの積み重ねの上に、これからもやはり委員のおっしゃるように、新たな対策をもっともっと新たな視点でまた考えて、いろいろな取り組みをやっていかなくちゃならないだろうということで、私どももそういう認識を重々持っていますので。","voiceIndex":43,"id":"exchange-019"},{"speaker":"石田委員","kind":"質問","question":"直球で質問をまずします。平成２３年度まで６％削減を目標に掲げているんですが、品川区としてまず、平成２３年度までに本当に６％の削減が実現できそうなのか。その自信があるのかというのがまず１点お伺いしたいと思います。","respondent":"工藤環境課長","answer":"数値等も実際削減をしてきたわけですので、そういった意味ではなかなかハードル、１年に１％削減するという部分、かなりもう今厳しいような状況の中ですけれども、私どもとしましても、当然こういった形で目標を掲げてこの目標値を区民の皆様に公表して。","voiceIndex":45,"id":"exchange-020"},{"speaker":"石田委員","kind":"質問","question":"資料の一番最後で、設備等で削減効果の一覧があるんですが、こういったものはある程度数値が出て計算しやすい部分だと思うんですね。そういうものがある程度数値的にあったら、非常にその目標に近づいて達成ができていくのかなと思うんですが、その辺の率先行動計画の中の削減のある程度の数値のデータというのは調べているのかというのを１点お伺いしたいと思います。","respondent":"工藤環境課長","answer":"そういった中で進めている部分だというところはご了解いただきたいというふうに思っております。","voiceIndex":47,"id":"exchange-021"},{"speaker":"浅野委員","kind":"質問・要望","question":"この排出量ですけれども、３万トンですよ、ざっくり言って。そういうものを今後例えば区役所だけではなくて、さまざまなところ、またご家庭にもいろいろこれからもアクションをかけてまたアピールするときに、もう少しわかりやすい量というんでしょうかね、東京ドームがいいのかわからないんですけれども、例えばそういうようなものに換算できないかな。何が違うんだ。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-022"},{"speaker":"大沢委員","kind":"質問","question":"この実行計画の冊子についてちょっとお伺いしたいんですけれども、９ページに本計画期間は２００７年度から２０１１年度の５カ年間とあります。これは５カ年間、２０１１年度になって第三次、次の計画ができると思うんですけれども、それまではこの計画、この冊子が生きて、これにのっとって進めていくと考えていいわけですか。","respondent":"工藤環境課長","answer":"考え方としましては、５カ年間、２０１１年度までということになります。２０１２年度以降に関しては、また別途さまざまな状況を踏まえて計画を立てるです。","voiceIndex":50,"id":"exchange-023"},{"speaker":"大沢委員","kind":"質問・要望","question":"中の文言についての、例えば資料の中で３６ページになります、これにしても各々推進本部ということで各部の部長さんたちの役職、委員ということで推進本部と書いてあるわけですけれども、明らかに先だっての組織変更で名称、部署も変わっているわけですから、広くこれが見られる冊子なのであれば、多少変わったところを訂正していかないとおかしいと思います。","respondent":"久保田都市環境事業部長","answer":"今のお話、ご指摘のとおりなんですけれども、私ども、この温暖化対策をやる場合に、もう一つ環境ＩＳＯというのをやってあります。これは毎年それこそ見直ししながら進めているんですけれども、そういう中では新しい組織体制として、それぞれ取り組んでいる状況が１つあります。","voiceIndex":52,"id":"exchange-024"},{"speaker":"大沢委員","kind":"質問・要望","question":"なるべく現状に即したようなものを見ても、これは平成２０年３月策定ですから、その時点ではこういうことで、十分それも承知をしておりますけれども、本委員会もでき、また、組織も新しく変わったことですので、その対応方、作業において作業量がうんとかかるようであれば、これは次のことということでお願いをしますけれども、比較的簡易にできるようなすべがあるのであれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この冊子は平成１８年度の数値しか載っていなくて、今日いただいた資料に初めて平成１８年度と平成１９年度の比較が出ていて、エネルギー自体は電気もガスも燃料の使用量においても、どれをとっても量的には増えているけれども、排出係数が変わって主に電気使用量のところのＣＯ２の削減が進んだので、トータルにおいて削減がされているという説明を受けたので。","respondent":"工藤環境課長","answer":"昨年、区民委員会の中で４月につくりまして、すぐ４月の区民委員会のほうでこちらのほうを説明させていただきまして、すべての議員の皆様のほうにも配布しています。２点目の計算式の件ですけれども、ＣＯ２の排出量、活動量掛ける排出係数となっています。","voiceIndex":55,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"量は増えているけれども下がっている、その排出係数というのがどう変化するのか。それは日本国じゅうで一致するところの数字なんですかね、ちょっとその辺のおおもとのところを教えていただきたいのが１つです。その辺の努力の姿勢がどのくらいなのかというのを知りたいと思ったので、この間の１年間で太陽光パネルの増えた部分が、全部じゃなくていいんですが教えていただきたい。","respondent":"久保田都市環境事業部長、工藤環境課長","answer":"ですから、ＣＯ２を吸収するから緑を増やすというよりは、そちらの面での部分も相当あるということを踏まえて、我々はその緑の増という意味を考えていかなければならない。こんなふうに考えます。これはまだ着工の工事で。第三日野小学校で太陽光発電の街灯を設置するということで着工されているです。今後、品川地区の小中一貫校のほうでもパネルを設置するという予定を聞いております。","voiceIndex":57,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"排出係数については少しわかりました。樹木のところにおいては、１本の木がどれだけ吸収できるのかという話になってしまうと、何か夢も希望もなくなってしまうというか、いやしの部分ももちろんあるし、ヒートアイランドの都会のコンクリートで固められた対策としては、本当に樹木が求められているし、私が感じるのは、この間、開発で大きな立派な木が切られているというところがものすごく心痛むんですよね。","respondent":"久保田都市環境事業部長、藤田水とみどりの課長","answer":"これは私もそう思います。ただ、ＣＯ２吸収のために必要だからということではないと。やはりそれだけではないですし、いろいろな要素があるからそれは大事に育てていこうという話だと思うんですね。ただ、これも当然事業者の持っている自分の樹木、自分の財産ですから、そういう中で私どもができる範囲でお願いをしてきているということで、これは今後も同じような形で進めていく考えです。","voiceIndex":60,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後にしますけれども、開発は工場地帯だったのでもともとが緑が少ないという答弁に対してはちょっとそうですかと言い返したいと思いますが、御殿山とか北品川とか確実に緑が減っていますよね。私は大型の開発が行なわれると、緑がなくなるだけじゃないんです。だから、区として積極的に樹木を増やしていくという方向を持っていただきたいなという思いを込めて述べましたので、意見になります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-029"},{"speaker":"林委員","kind":"質問・要望","question":"もっと早く聞けばよかったんだけれども、Ａ４の資料の見方ですか、よくわからない部分があるので、先にそれを説明してください。３にある表がありますよね。３、４と。燃料使用量というところの数字が倍近く上がっているというのは、パーセンテージじゃなくて数字がね、これは何を指して燃料使用量と呼んでいるのか。それをまず教えていただきたいんだけど、何なんですか、これ。","respondent":"工藤環境課長","answer":"燃料使用量に関しましては、車、いわゆる庁舎そのほか施設で使っておりますガソリン、あと車の中でもＣＮＧ、天然ガス、ＬＰＧ、軽油の車、あと燃料というのは灯油の部分が含まれておりまして、灯油という部分は日光林間学園等の使用ということで、燃料の中にガソリン、ＣＮＧ。","voiceIndex":64,"id":"exchange-030"},{"speaker":"林委員","kind":"質問","question":"お金じゃなくて、要するに量なわけね、かさね。こんなに増えた理由は何なんですか。","respondent":"久保田都市環境事業部長","answer":"ですから、比較するときに、倍以上増えたというのはそこの部分で、それが主な理由なんです。ですから、今、リットルで言いましたけれども、これでいうと２０万リットルぐらい日光林間学園で使っていたです。","voiceIndex":70,"id":"exchange-031"},{"speaker":"林委員","kind":"質問","question":"ガスが微増、燃料が増加の結果となりましたけれども、二酸化炭素云々、割合が低いから全体では１.５％の削減になりました。このもとになっている数字なんですよ、これ。マイナス１.５２％という品川区ではさも減らしたような、いろいろな活動をしたおかげでこうなったんだというような言い方をしているんだけれども、単なる計算対象が違っていたというんじゃないんですか、これ。","respondent":"久保田都市環境事業部長","answer":"正直に書くこともあるんですけれども、なかなかその辺は表現が難しい。その辺の書き方は工夫していきたいと思います。","voiceIndex":72,"id":"exchange-032"},{"speaker":"林委員","kind":"質問","question":"もう一つ、聞いておきます。事務事業概要の説明を一番最初にいただいたんだけれども、それの温暖化対策事業、環境課の一番冒頭のところに４項目出ていて、平成２１年度予算額というのは、上のものに対する予算額だよね。ということは、こういう言い方は失礼だけれども、行政って予算がないと何もやらないということなんです。そうとっていいですか。","respondent":"工藤環境課長","answer":"しかしながら、すべての数値等の把握、あとさまざまなデータの公開等に関しましては職員の手で行なって進めていくという部分ですので、そういった意味合いでございまして、対策にかかる費用という部分はそれぞれの課のほうで計上されているものです。","voiceIndex":74,"id":"exchange-033"},{"speaker":"林委員","kind":"質問","question":"そうすると、この１１ページに出ている、これは全部網羅されているよね、品川区の区役所の中あるいは指定管理者だとかほとんど網羅されているんだけれども、ここから全部どういうふうにやって、どういう削減ができたかというのを報告させるわけですか、環境課に。それに予算がなしでやります。","respondent":"工藤環境課長","answer":"報告、すべての集約は環境課でやっております。それぞれの課から必要な情報をもらって、すべて数値として算出して公表をしているです。","voiceIndex":76,"id":"exchange-034"},{"speaker":"林委員","kind":"質問","question":"そうすると、さっき言った数字の間違いだとか、計算式の思い違いみたいな感じで、計算様式があって当てはめていくと、税金の早見表じゃないけど今月の給料だと税金が幾らという早見表みたいなのがあって、そういうところに入れていったらすぐ出せるというのなら予算がなくていいけど、計算式やって、その課あるいは係で人が必要になってくるとしたら、予算は本当に要らないんですかね。","respondent":"久保田都市環境事業部長","answer":"各課からの報告はそれぞれ例えば１施設であったら、施設の電気使用量というのは当然把握していますよね。その報告を環境課でいただくんです。トータルとしてその使用量に対して、今いった排出係数というのがありますので、その計算は環境課でやるというような。","voiceIndex":78,"id":"exchange-035"},{"speaker":"林委員","kind":"質問","question":"トータルだと、この委員会が終わった後だね、集計が出るのはね。だけど、予算がつかないで、なおかつ非常に細かい計算をしなきゃいけないというのは大変だろうと思うので、品川区の行革精神がここにも生きているんだというふうなことであれば、それはそれで受けとめますけれども、ちょっと予算がないというのは大丈夫ですかという疑問を投げておきます。そういう考え方はありますか。","respondent":"久保田都市環境事業部長","answer":"ただ、今言っていた削減状況とか何かというのは、これはそれぞれ個別の区にお聞きしても、なかなか明確に答えてはいただけないところもありますけれども、目標とする削減目標とか何かという数字は、それぞれ品川区と同様に掲げてやっているというのが現状です。","voiceIndex":82,"id":"exchange-036"},{"speaker":"林委員","kind":"意見","question":"だから、２３区で課長会とか部長会があって、うちのところはこういう取り組みを今年度はやるんだというようなことを、じゃあ、例を挙げれば隣同士、大田区がやると言って、品川区もじゃあ一緒にやりましょうとか、そういうような自治体同士の情報交換というか、そういうのは僕はやっていくべきだと思う。","respondent":"久保田都市環境事業部長","answer":"例えば２３区にとどまらず、三多摩の市町村なども入れて、７２市区町村温暖化対策シンポジウムとか、あるいはそういう形でやっているんですけれども、必ずしも今みたいな実行計画とか何かというのは各区の取り組みによるところが多いので。","voiceIndex":84,"id":"exchange-037"}]},{"id":"topic-04","title":"ほかに。では、次に進みます。 次に、品川区地球温暖化対策地域推進計画の策定","agenda":"ほかに。では、次に進みます。 次に、品川区地球温暖化対策地域推進計画の策定","exchanges":[{"speaker":"林委員","kind":"質問","question":"ちょっと委員長、その前に、このペーパーの２の計画の概要の（３）課題の整理の終わり、区の特等と書いてあるんだけれども、これは何ですか。","respondent":"工藤環境課長","answer":"すみません。ちょっとミスプリで、区の特性と課題を整理する。申しわけございません。抜けてございました。","voiceIndex":90,"id":"exchange-038"},{"speaker":"南委員","kind":"質問","question":"構成メンバーの人数と、それぞれの分野からどのぐらい予定しているのかをちょっと伺いたいと思います。それと、当然、平成２１年度中に計画を策定するんですけれども、実施については平成２２年度からというふうに理解していいんでしょうか。","respondent":"工藤環境課長","answer":"今後、計画を策定しまして、その中での事業展開というのは翌年度からということになります。今年度中に計画を策定して、平成２２年度からの実施ということになります。","voiceIndex":93,"id":"exchange-039"},{"speaker":"南委員","kind":"質問","question":"その辺の関係、非常にデリケートな部分なんですけれども、どういうふうにとらえたらいいのかというのを伺いたいと思います。","respondent":"工藤環境課長","answer":"ただ、先ほども説明で申し上げましたように、パブリックコメントを実施する予定でございまして、パブリックコメントの中でもパブリックコメント実施時には必ず議会に報告するということになりますので、所定の手続きにのっとって、その中で報告をするです。","voiceIndex":95,"id":"exchange-040"},{"speaker":"南委員","kind":"質問","question":"区内関係団体の代表６名というここのところが、かなり実質的な区の現状だとか、中心部分になるかなというふうに思っているんですけれども、大体どのようなところを関係団体というふうに区は想定しておられるのか、その辺をちょっとお伺いいたします。","respondent":"工藤環境課長","answer":"この６名ですけれども、まず、１つ目が町会連合会からの選出、あと消費者団体の連合会からの選出、あと商工会議所の品川支部からの選出、工場協会連合会からの選出、商店街連合会からの選出、あと環境活動推進会議という会議体がありますので。","voiceIndex":97,"id":"exchange-041"},{"speaker":"南委員","kind":"質問","question":"その辺も含めて２０人ということであれば、あと１人プラスは少なくとも可能な部分なので、もう少し公募区民のところを枠を広げて運営がうまくいかない、大人数でやれということは全然主張するつもりはないですけれども、２０人の枠の中でできるだけ区民の参加を広げるということで、可能であれば増やしていくべきではないかなというふうに思いますが、その点について最後に一言だけお伺いします。","respondent":"久保田都市環境事業部長","answer":"これは身近に私どもとも連携をとっているんですけれども、ぜひともそういう点では区民に近い方々からメンバーとしてなっていただこうということでやっておりますので、公募区民３人というのは妥当なところじゃないかなというふうに考えています。","voiceIndex":99,"id":"exchange-042"},{"speaker":"南委員","kind":"意見","question":"公募区民３人というふうに、公募区民と見たときに、全体の２０名の中の枠の中の３人というのは、ちょっと少ないんじゃないかなというふうに私は思うので、２０人ということで設定されているのであれば、増やす可能性はなくはないわけなので、できるだけ広げていただけるようにお願いしたいということをちょっと、先ほども申し上げたつもりなんですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-043"},{"speaker":"伊藤委員","kind":"質問","question":"ほかの会議体があって、作業部会、実際は作業部会で何回も会議を開いて、そこで実際積み上げたものを本体、親の会合として決定してもらうという話で、やはりこれもそれぐらいのことをした上でないと、品川区のすべてのことにかかわる削減目標を設定しているわけですから、私はこの５回の予定ですけれども、これだけのことが達成されるのかな。","respondent":"工藤環境課長","answer":"会議の回数という部分は５回ですけれども、１回をやるにあたってのいろいろな調整、あと施策の検討という内部の部分の検討というのがありますので、そこの中で十分に内容を検討して、しっかりした計画をつくっていきたいというふうに考えております。","voiceIndex":102,"id":"exchange-044"},{"speaker":"伊藤委員","kind":"質問","question":"これだけのことを決めるわけですから、緊急性はわかります。だけれども、相当慎重にしていかないと、産業界に与える影響もあるでしょうし、私たち区民の生活にも直接かかってくる部分が出てくるわけですから、それは緊急はもちろんなんだけれども、かつ慎重に対処していっていただきますことをお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6168#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":46018,"voices":109}},{"id":"h21-20090721-6","meetingId":"h21-cm07","date":"2009年7月21日","dateIso":"2009-07-21","committee":"区民委員会","time":"午後１時０２分～午後２時０２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"番、報告事項","agenda":"番、報告事項","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"区商連に委託して、各商店からの弁当を配食する、その商店の数は大体幾つぐらいの商店が、それと、各商店に対して支払うお金というのは、一律幾らで、同じなのかどうかをお伺いします。","respondent":"秋山協働・国際担当課長","answer":"昨年度は５店舗でしたけれども、今年度から１店舗増えまして、６店舗ということでございまして、配食の際の委託料ですけれども、商店街連合会への委託ですので、商店街連合会へ１食幾らという形で委託しておりますので、その中で一律かどうかということは。","voiceIndex":5,"id":"exchange-001"},{"speaker":"三上委員","kind":"質問","question":"これは確定している数字なのか、昼食１１４人、夕食５８人、昼食だけとっても、事務事業概要の中の４８ページ目、ちょうど平成１８年度が１５２人でだんだん減ってきているというこの傾向性というのは、どういうふうに受けとめていらっしゃるんでしょうか。","respondent":"秋山協働・国際担当課長","answer":"この配食サービスの受給者の状況ですけれども、基本的には自分で食事等ができる方ということで、要綱等で定めておりますので、２回以上必要な方、ご要望は数々伺ってはおりますけれども、今のところ週２回というのを実施しています。","voiceIndex":9,"id":"exchange-002"},{"speaker":"三上委員","kind":"質問","question":"介護ではだめです、こちらのほうも、どちらかというと、介護のほうが要支援とかという形でなってきているという話になると、いや、手を出しませんよというようなはざま的な部分で、サービスの提供を受けづらいというか、受けられないという実態というのはつかんでいらっしゃるんでしょうか。","respondent":"秋山協働・国際担当課長","answer":"配食サービスですけれども、民生委員等からのご紹介、それから、地域の方から地域センターのほうに配食サービスを受けたいということでご希望がございましたときには、地域センターの職員が一緒に、一緒というか、配食希望の方を調査に伺いまして。","voiceIndex":11,"id":"exchange-003"},{"speaker":"三上委員","kind":"質問","question":"そこらあたりをどういうふうに地域に喜んでもらえる事業に広げていくかといったことでの将来的な課題というのは、きちっと見えているんじゃないかと思いますので、ぜひともそういった点での考えの中で、こういった事業についてはやっていってもらいたいと思いますが、いかがでしょうか。","respondent":"中山地域活動課長","answer":"地域センターを介しての事業ということでのご質問もありましたので、私のほうからも若干補足的にご説明申し上げます。","voiceIndex":13,"id":"exchange-004"},{"speaker":"南副委員長","kind":"確認","question":"一番最初のところのサービス事業の現状というところに、経費面や管理面等で課題が生じていると書いてあるんですけれども、ここを具体的にどういうことなのかということと、段階的に見直すという方向なんですけれども、どういうことを想定しているのか、その辺を、今、区商連に委託して新しい、異分野で拡大して、継続し、さらに発展していくという方向だと今の中山課長の答弁を聞いて。","respondent":"秋山協働・国際担当課長","answer":"サービスの自己負担額ですけれども、昼食につきましては３５０円、夕食につきましては自己負担が４５０円という状況です。","voiceIndex":15,"id":"exchange-005"},{"speaker":"南副委員長","kind":"確認","question":"そうすると、夏季休業中に限って、商店会連合会に委託して、利用されている方々の食事を確保するということで改めて受けとめていいんですか。その辺は改めて確認したいのが１つです。先ほどご答弁はありましたけれども、改めてもう１回その辺の考え方を伺っておきたいと思います。","respondent":"秋山協働・国際担当課長","answer":"回数につきましては、火木２回の配食、先ほども話が出ましたけれども、元気な方と介護の方とのはざまの問題はありますけれども、基本的には元気で出歩ける方ということがベースになってありますので、今現在のところ火木の２回というのを実施しています。","voiceIndex":17,"id":"exchange-006"},{"speaker":"南副委員長","kind":"質問・要望","question":"私はそういうふうに受けとめたんです。委託業者だと、なかなか専門性という点でもちょっと不安が残るかなと思っているので、そういう点で、衛生面だとか、管理面等で問題が、課題が生じているということで、学校給食は縮小していく、そういう方向の道を選んでいるのかなと私は思っているので、聞いているんですけれども、その辺はどうなんですか。","respondent":"秋山協働・国際担当課長","answer":"管理面につきましては、例えば、休業中は集中校で調理をして、各配食の学校にランチジャーを置いていくということになりますと、そこのランチジャーを、集中校で調理をしていないところに置いておいて、ボランティアとの受け渡しをしなければいけないということがありますので。","voiceIndex":19,"id":"exchange-007"},{"speaker":"南副委員長","kind":"質問・要望","question":"ですから、そこのところで、ランチジャーのいろいろな、管理的な、衛生的な問題が残るというのであれば、具体的にどういうことか、あんまりイメージがわかないので、確認なんですけれども、全校でやるぐらいの食数ではないので、集中校でやっていただいて、調理していただいて、それを配食するのにランチジャーで地域センターに落として、そこから配食していく、こういう形になるのか。","respondent":"秋山協働・国際担当課長","answer":"地域センターに配食を持ってくるということではなくて、各学校にという形で、そういうところで問題が生じていると考えているところです。","voiceIndex":21,"id":"exchange-008"},{"speaker":"三上委員","kind":"質問・要望","question":"今、副委員長が言った、安全面に問題があるという認識をされているのかどうか。そうでないからこそ、いろいろやっているんでしょう。そこのところをやっぱり明確に打ち消しておいていただかないと、私がこう言ったら、区はそれに対して答えもしなかったといって、それこそまたどう言われるかわからないけれども、きちっと言っておいていただきたい。","respondent":"秋山協働・国際担当課長、中山地域活動課長","answer":"安全面、衛生面での問題が生じているということではございません。なおかつ、実施に当たって、高齢者への配食となると、通常のお弁当と違う配慮も必要ではないかということから、各商店のメンバーが決まった段階で、保健所に指導のお願いをいたしまして。","voiceIndex":23,"id":"exchange-009"},{"speaker":"三上委員","kind":"意見","question":"今、副委員長が安全面、衛生面とすごくいっているじゃないかと、ここの文章にありますか、その言葉。配食サービスが経費面や管理面等で課題が生じていることから、段階的に見直しという言葉はあるけれども、安全面とか衛生面で問題があるという言葉はどこに書いてあるの。なければ、ないとはっきり言ってよ。","respondent":"中山地域活動課長","answer":"従前の事業について安全面、衛生面で問題があるということは全くございません。そういうことも踏まえて、従来の安全性をきっちりと継続する意味で、今回の見直しについても当然そういうものはきちんと担保されているということで認識してやっているわけです。","voiceIndex":26,"id":"exchange-010"},{"speaker":"南副委員長","kind":"質問・要望","question":"ですから、さっきの質問の中にもそういうことが含まれた質問だったと理解していただいて、答弁をいただいていると思っているわけです。その辺についてはそういうふうに理解していただきたいし、ぜひほかの委員の方もぜひそういうふうに聞いていただきたいと思っています。ぜひ衛生には十分気をつけて取り組んでいただきたいということを申し添えておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-011"},{"speaker":"稲川委員","kind":"質問","question":"１番の海外展示会出展助成とあるんですけれども、助成は上限５０万円なんですけれども、海外でこういった展示をするというのは、普通に考えてみると、大体一般的にどれぐらい費用がかかるのかというのが１つと、あと国際化対応専門人材の配置と書いてあるんですが、毎月第１・第３月曜日、毎月第２・第４、中国とタイなんですけれども、これだけなんですかというのが１点。","respondent":"福島ものづくり・経営支援課長","answer":"海外展示会の一般的な費用ですが、これは持ち込むものですとか、それによってかなり違います。ですから、一般的というかなり難しいかと思います。ただ、ほとんど上限は使われていますので、１００万円、２００万円ぐらいはかかっているだろうと思います。","voiceIndex":36,"id":"exchange-012"},{"speaker":"三上委員","kind":"質問","question":"４番目のアジア地域使節団の派遣で、品川区の関係者というのは、この４つの自治体で出すという話の中で、品川区の関係する企業というのは、どういう企業なんですか。","respondent":"福島ものづくり・経営支援課長","answer":"品川区の参加する企業ですけれども、これは数としましては、一応今のところ、全体で８ブース押さえてございまして、そのうち４ブースが品川区の持ち分ということを予定しています。","voiceIndex":38,"id":"exchange-013"},{"speaker":"三上委員","kind":"質問","question":"要するに、興味を示しているのが１０社ぐらいあるとか、２０社ぐらいあるとか、現実に、積極的に参加したいと言っているのがこれぐらいあるんだとかという、そこらあたりの感触もわかれば、報告ですから、していただければありがたいなと思います。","respondent":"福島ものづくり・経営支援課長","answer":"実際募集をするのはこれからですので、あれですけれども、感触といたしましては、品川区が４ブースを押さえているということで、それぐらいは来ると、あるいはそれが倍になっても対応できるだろうと計算していますので、大体そのぐらいの数ではないかと想定しています。","voiceIndex":40,"id":"exchange-014"},{"speaker":"南副委員長","kind":"質問・要望","question":"経済的にはかなり厳しい時代にこういうところに出展するというのはかなり力のある企業なんだろうなと想像するんですけれども、どの程度、応募がどうで、現実的にどうだったかみたいな数字がわかれば、教えていただきたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"実績ですけれども、この事業全体といたしましては、今年度新規で行うものでございまして、行っておりますこの海外展示会への出展ということにつきましては、昨年も行ってあります。昨年につきましては４社に対しまして、１７０万円ほど助成しているものです。","voiceIndex":42,"id":"exchange-015"}]},{"id":"topic-02","title":"その他でございますが、その他","agenda":"その他でございますが、その他","exchanges":[{"speaker":"南副委員長","kind":"質問","question":"民間の実行委員会で準備して、まつりが開催されているので、民間のやっていることについてどうこうと言うつもりは全くないんですけれども、今までやってきた区民まつりの参加団体とはちょっと質が違ってきているので、その辺について、区としてはどういうふうに見ているかというのを質問したいと思います。","respondent":"中山地域活動課長","answer":"そういう意味では、区との一定の連携関係があるということで、あそこに出てこられていたのが、自衛隊の東京地方連絡部の五反田募集案内所、たまたま大崎にほど近いところに案内所がある関係から、できるだけ人々が集う場所ということで。","voiceIndex":48,"id":"exchange-016"},{"speaker":"南副委員長","kind":"質問","question":"したがって、区としてどういうふうに承知しているのかというので、聞いてみたんですけれども、さっきも言ったように、戦争をしない国づくりへの意識啓発の必要性と、こういう募集、チラシを配ったことが過去にあったのか、今回よそのところでも含んでやられてきているのか、その辺の認識がどういうふうになっているのか、ちょっと伺いたい。","respondent":"中山地域活動課長","answer":"ただ、あくまでも自衛隊の募集の事務というのは区との関係もあるということ、それから、災害時に協力関係も結び、支援もされるという防災面での連携等もあります。","voiceIndex":50,"id":"exchange-017"},{"speaker":"南副委員長","kind":"意見","question":"これ以上やるつもりは全然ないんですけれども、しかし、ブースを設けることについては、あんまりなかったというのは非常にあいまいな表現なんですけれども、なかったのか、初めてのことなのかというのを聞きたかったんですけれども、その点について回答してください。","respondent":"中山地域活動課長、川西委員長","answer":"過去の地区まつりにおいてどうかというのは、今現在すべてを把握しているわけではございませんので、これは調べて、別途お知らせしたいと思います。なければ、本日の予定はすべて終了いたしました。これをもちまして、区民委員会を閉会といたします。","voiceIndex":52,"id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2556#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":16767,"voices":54}},{"id":"h21-20090721-7","meetingId":"h21-cm07","date":"2009年7月21日","dateIso":"2009-07-21","committee":"厚生委員会","time":"午後１時０２分～午後２時５８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２０年度居宅介護支援事業（ケアマネジメント）のサービス評価実施","agenda":"平成２０年度居宅介護支援事業（ケアマネジメント）のサービス評価実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"基本的なところからお伺いしたいんですが、品川区が行っている介護保険事業を第三者機関が評価して、それをサービスの向上につなげるということはすごく大事なことだと思います。それから、サービス向上委員会というのは、具体的にはどのような方々で、第三者評価という枠組みを担保しているのかという点を、まず、お伺いしたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"任期につきましては、２年ということでございまして、今期の任期は平成２０年４月１日から平成２２年３月３１日までです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"確認","question":"ちょっと確認なんですが、こういったアンケート形式で、利用者と、事業者と、ケアマネージャーから調査をして評価をするというやり方と、それから質問項目とかも、区の独自の評価方法ということでよろしいのでしょうか。品川区としては、この事例の方をこれでよしとしているのか、それとも、こういった事例は存在しないとおっしゃるのか、そこら辺ちょっと、考え方をお伺いしたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"ここでどういうふうに具体的に対応したのかということは、この後の続編がありませんので、姿勢としては、一つ一つ丁寧にどんなケースにも対応して、説明するものについては説明して、了解をいただきながら対応していくという姿勢には変わりございません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"確認","question":"先ほどのサービス向上委員会の点について、確認でお伺いしたいと思います。これは外出補助のサービスだと思うんですけれども、外出したくてもできないと、通院以外は頼むことができないということで、もう少し負担がかからず外出できるようにお願いしたい。介護保険の有効な利用方法をお願いしたいというお願いに対しては、区としてはどのような姿勢で臨んでいるんでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"これについては、こういうご要望があったということで、ただ外出するだけでは保険の対象外ですけれども、具体的にどうなのかということをさらに特定していかないと、なかなか対応ができない部分があります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほどのサービス向上委員会の調査方法というのは、どこまで区独自なんですかという質問もしたので、それもあわせてお伺いしたい。区内の介護事業者の経営状態というんですか、居宅介護支援事業所の経営がどれだけ苦しいか、区としてはつかんでいらっしゃるのか、どうか、これもお伺いしたいと思います。","respondent":"木下健康福祉事業部長","answer":"この点については、国の考え方とかありますので、そのことも踏まえながら、区としては、適切なケアマネジメントに努めていこうと考えているところです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"１９２人中７９人に、負担感についての意見も出されていますし、悩みも、１９２人中１１８人の記載ということで、バーンアウトという言葉もありますが、かなり出ています。ほんとうは地域づくりの活動もやって行きたいが、予防給付で手いっぱいである。すみません、長くなりましたが、ケアマネージャーが打ち込める環境づくりという点では、品川区としてはどのようにお考えでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"個々のケースにつきましては、十分に在宅介護支援センターのバックアップをするのが高齢者福祉課の務めですので、各係を通じまして対応したり、支援をしてまいりたいと考えているところです。","voiceIndex":14,"id":"exchange-005"},{"speaker":"飯沼副委員長","kind":"質問","question":"東京都なんかには福祉サービスの第三者評価というのがありますよね、その辺との違い、もちろん違うんですけれども、さっきメンバーも伺ったんですが、どの辺までを目指しているのかというあたり。第三者評価を強めていくためには、メンバーなんかもすごく重要であると思うんですが、さっき伺うと、かなり事業者がたくさん入っていらっしゃいますよね。ちょっとその辺をお伺いしたい。","respondent":"冨岡高齢者福祉課長","answer":"質の向上というところで、特に６２ページの下あたりのところ、ケアプランの質のチェックを組織的に行っているか、あまりできていないが高かったということでありますが、まさにその後に、福祉カレッジ事業者連絡会議などの。","voiceIndex":16,"id":"exchange-006"},{"speaker":"飯沼副委員長","kind":"質問","question":"今のご説明だと、研修も含めて、それぞれいろいろ交流し合って努力していくというところですかね。それから、９６ページの品川区標準の改定のところのケアプランの品質管理というところで、1)に第三者によるチェックとあるんですが、この第三者というのはだれに当たるのか。","respondent":"冨岡高齢者福祉課長、木下健康福祉事業部長","answer":"９６ページの第三者によるチェックにつきましては、事業者以外ですので、当然、行政も入るという形で、当事者以外によるチェックという意味です。第三者性を有するということの意味は、第三者性が薄いという意味では、決してありませんで、これをつくったときに、この当時、平成１２年のころというのはオンブズマン制度というのが、世の中では大変はやっておりまして。","voiceIndex":18,"id":"exchange-007"},{"speaker":"飯沼副委員長","kind":"質問","question":"一緒に考えていくという意味では、さっきの９６ページの品川区標準のところのケアプランの品質管理というところにおいては、そこにも区は入っているんですよね。一緒に一体となってチェックをしていくという考え方でいいですか。","respondent":"木下健康福祉事業部長","answer":"区と一緒にやるという部分では、１３地区ありますから、すべての在宅介護支援センターにおいて、毎月１回、困難ケースを中心にしたケアケース検討会議を行っておりますし、そこで解決ができないものは、区の行政のほうが直接入る形でやっております。","voiceIndex":21,"id":"exchange-008"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"今回のは結構分厚いですよね。これを十分に理解したいし、生かしていただきたいと思います。よりよい方向に行ってほしいと思うんですが、申しわけないんですが、今日、説明を受けていても、なかなか実態が見えてこない。ちょっと基本的なところなんですが、この３パターンの違いを教えてください。この違いがどうして生れてくるのかというところです。","respondent":"冨岡高齢者福祉課長","answer":"こちらまでは扱えるということで、在宅支援センター系のことははっきりと分かれておりますけれども、民間の事業者については一緒にやっているところもあるということで、三つに分かれているところです。","voiceIndex":23,"id":"exchange-009"},{"speaker":"飯沼副委員長","kind":"質問","question":"というと、介護、介護・予防型というのは、民間で働いていらっしゃるケアマネージャーという受けとめでいいんですね。７７ページにしても、ケアマネジメントの困難なケースが増加をしているということとか、ケアプランの記入が大変というのも８４.６％もありますよね。この辺で、さっき抱えている件数が３９件までと、これを超えてはいないという受けとめ方でいいんですか。","respondent":"冨岡高齢者福祉課長","answer":"４０件を超えると介護報酬が減らされるということですので、ふつうは超えないです。","voiceIndex":25,"id":"exchange-010"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"細かいかもしれないんですが、一つ一つわからないので、せっかくいい機会なので教えていただきたいと思います。私も、アパートに住んでいらっしゃる大家がひとり暮らしで困っているので、どこか入るところがないですかと言われても、行き先がない。その辺の区との連携というか、改善はどういう状況なんでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"区は、介護支援センターの統括をする立場ですので、ケアマネージャーたちの悩みや何かにつきましては対応し、相談に乗るという役割も担っているところであります。","voiceIndex":27,"id":"exchange-011"},{"speaker":"飯沼副委員長","kind":"質問","question":"８１ページの、担当ケースワーカーにもっと相談できるよう、ケースワーカーの成長も必要と感じる。もう１回、ちょっとそこをお聞きしたいと思います。今回、ケアマネジメント、２回目の答申ということで、前回から大幅に改善されて、変化しているというか、よくなっているところと、さらに問題と感じているようなところがありましたから、ちょっと重点的にお話しください。","respondent":"冨岡高齢者福祉課長","answer":"技量も前よりは進んでいるとは理解しておりますけれども、ご指摘のようなさまざまな課題、それから、ケアマネージャーの置かれている状況、困難な状況、これは制度的に解決しなければいけない問題もあれば、区として。","voiceIndex":29,"id":"exchange-012"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"例えば、人が少ないのではないか、ホームヘルパーの人員が足りないとか、介護報酬の問題とか、やはり制度面の改善は、区でできる問題ではないので、そこのところは東京都とか、国とかにどんどんご意見を上げているとは思うんですが、やはりそこのところに力を入れて、介護保険は人によって支えられている、さっきもありましたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"２点だけ、ちょっと確認させてください。一つは、調査したときに、１１ページですけれども、区がやったわけではないけれども、調査対象者の中で、要介護者１,５３６人と出ているんですけれども、それの１から５の中で、５の方の回答、１の方の回答で、何か傾向的なものがあるのかどうか、１点確認です。やり方をどういうふうにしていくかという点を、お答えいただきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"なかなかきていただけない部分もあると聞いていますので、どういう形で利用者にサービスを提供しようとしているかという形を、まずそこの基本から始めていって、区としてできることをまず進めていくというような動き方になるかなと思っています。","voiceIndex":32,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"確認","question":"要介護１から５で、例えば要介護５の人は、回収率が高かったとか、低かったとか、そういうことが特別に出ているのか、そういう傾向があるのかどうか。それもわからないんでしょうか。回収率という意味での確認をしたかったんです。最初の点だけ、何か傾向があれば教えてください。","respondent":"冨岡高齢者福祉課長","answer":"細かい調査までは、申しわけありません、数字が出ておりませんので、約５０％のうちどうだったかということ、実際問題ですが、なかなかお書きになれるかという部分がございまして、場合によっては、家族が書いていただいているというところもあるかなというところもありますので。","voiceIndex":34,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"平成１６年の発達障害者支援法というところで、発達障害の定義が明らかになったというところなんですけれども、どういった定義なのかというのを、私もなかなか難しいなと思っているんですけれども、教えていただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"１２月９日は、国連で決めているもので、それをそのまま日本に持ってきたということです。","voiceIndex":41,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。そこら辺の基本的なことを、ちょっと改めて、障害が重い人ほど負担が重くなってしまうという制度上の矛盾にもつながっている、障害に対してそれをカバーして生きていくということをサービスと見なすという考え方ですね、区は、これをどのようにとらえているのかお伺いしたんです。","respondent":"高橋障害者福祉課長","answer":"サービスの利用料の負担の問題だと思いますが、サービスの利用料そのものについては、今、本人の資産要件もなくなりまして、本人の所得に応じたものということで、ほとんどの方が１,５００円程度上限ということでは、かなり少なくなっている。","voiceIndex":43,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"民主党などの野党が合わせまして、障害者自立支援法の廃止という流れになっていく可能性もかなり高まっていると思うんですけれども、そういった場合に、障害者自立支援法は廃止して、新たに障害者の当事者を含めて新たな法律をつくろうという声がかなり起こっているわけですけれども、それがかなり現実的な可能性が出てくる中で、可能性の段階であまり議論できないとなるかもしれないんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-018"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"資料をありがとうあります。それから、ずっと自立支援法の流れで、障害を持った方々に負担が重くなっているというところにおいて、自治体としては、国との関係で、財源的な変化がどのようになっているのかを、前から一度、お聞きしたいと思っていたので、支援費が始まって、障害者自立支援法の流れの中で、国と地方の負担割合がどういうふうに変わってきているのか、教えていただきたい。","respondent":"高橋障害者福祉課長","answer":"都道府県の段階での負担もなくて、国と地方自治体が２分の１ずつ負担するというような流れの中で、支援費になったときに、きちっとするということで、負担金という形で国が２分の１、都道府県が４分の１、各自治体が４分の１というふうに。","voiceIndex":47,"id":"exchange-019"},{"speaker":"飯沼副委員長","kind":"質問","question":"国と地方自治体が２分の１ずつのところが、都道府県も含めて、２分の１、４分の１、４分の１という負担に変わってきたというところにおいて、負担の額としてはどうなんですか。","respondent":"高橋障害者福祉課長","answer":"ただ、その間、例えば利用促進支援金とか、軽減負担とかということで、品川区が減らした分をそのまま品川区が持つのではなくて、利用料にも還元しているところです。","voiceIndex":49,"id":"exchange-020"},{"speaker":"飯沼副委員長","kind":"意見","question":"展開の年表をつくっていただいたんですけれども、歴史的なところで、長期基本計画なんかにも基づいていろいろ施設ができているわけですけれども、じっくりは見ていないのでよく私も把握していないんですが、健康福祉事業部長としては、経年的な流れを見て、施設面とか、施策で、品川区で次はこういった面を充実させなければいけないと考えていらっしゃるか、ちょっとその辺のお考えがあったら。","respondent":"高橋障害者福祉課長","answer":"今年から総合実施計画１０年間の中で、私どもが考えているのは、自立支援法になり、地域生活支援をサポートするという意味から、基本的には、施設建設ということではなくて、グループホームを地域の中につくっていったらどうかというような、具体的な施設だけを考えれば。","voiceIndex":51,"id":"exchange-021"},{"speaker":"飯沼副委員長","kind":"意見","question":"ちょっとここの表で、最後に２００６年まで書いてあるわけですけれども、グループホームという字が目に入ってしまったのですが、「旗の台朝やけ」と「ミドリホーム」というのは民間ですよね。この辺どういうふうに書いてあるのかなと思ったんですが、この辺の民間の施設に対して、どのような支援が入っているのか、それを最後に聞かせてください。","respondent":"高橋障害者福祉課長","answer":"ただ、設置に当たりまして、東京都に申請しますと、例えば改修工事の場合でしたら補助金もある場合もありますので、私どもにご相談があった上で、東京都のほうに申請に行くという形で、私どもでつかんでいるところの施設として載せました。","voiceIndex":53,"id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3242#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":32040,"voices":62}},{"id":"h21-20090721-8","meetingId":"h21-cm07","date":"2009年7月21日","dateIso":"2009-07-21","committee":"建設委員会","time":"午後１時０３分～午後１時５９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"１点だけ聞かせてもらいたいんですけど、目的の中の最後に、地球温暖化ですとかヒートアイランド問題を考える機会にするというのがあるということですけれども、これまでの取り組みの中で、区民の皆さんから何か意見として、こういう取り組みの問題もそうですし、もっと大きなところでの地球温暖化の問題でこんな取り組みが必要なんじゃないかとか、そういう意見というのは出てきていないんですか。","respondent":"工藤環境課長","answer":"当初は特定の商店街の中で、いわゆるまちの活性化という観点から始めたものでございまして、翌年度から品川区と、先ほど説明いたしました環境活動推進会議のメンバーが中心となって、特定の商店街じゃなくて、もう少し区域全体に広げていきたい、そういった思いから。","voiceIndex":9,"id":"exchange-001"},{"speaker":"武内委員","kind":"意見","question":"保水性舗装は、今のこれで何カ所目ぐらいになったのかということで、保水性にしたほうが打ち水の効果はあるんだと思うんですけど、その辺の効果というのと、それから保水性の場合は定期的に少し水をやらないといけないのか、その辺のことを。","respondent":"齋藤道路公園課長","answer":"平成１８年度にゆたか商店街、平成１９年度に平和坂通り商店街。そのほか、再開発事業で大崎駅東口で１路線、西口で３路線ほど保水性舗装を実施しております。今回ですけれども、３日に１度ぐらいは水をまかないと蒸発して気化熱を奪うという効果は得られないということです。","voiceIndex":11,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"商店街に対して声かけをしているということは、舗装が傷んでいるような場所とか、いくつの商店街があってというのは押さえていらっしゃることなんですよね。そうすると、それは実際問題としてどれぐらいの数のものですか。","respondent":"齋藤道路公園課長","answer":"１０ぐらいはピックアップしてあるんですけれども、それを計画的にと考えております。","voiceIndex":19,"id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"今、保水性舗装だとか、都道の遮熱性のところですか、ああいうもので、とにかくヒートアイランド化を抑えていこうということで進めているわけですけれども、先ほどの保水性舗装の問題点は問題点としてあるんですけれども、じゃあ、全体的にヒートアイランド化を抑えるための対策、これは主に道路の対策の報告ですけれども、どういう形であれ。","respondent":"齋藤道路公園課長","answer":"一度整備しまして１０年たちますと、また老朽化、打ち替えできる商店街が出てくると思いますので、そのときはそのときで精査して考えてです。","voiceIndex":21,"id":"exchange-004"},{"speaker":"阿部副委員長","kind":"質問","question":"先ほどの２件なんですけれども、同じ日の午前１０時と午後３時半に、２回に分けて打ち水イベントをする意味、一緒にやるわけにはいかなかったんでしょうか。一つの場所で朝と夕方、それぞれちがう課で異なるイベントをするのは、不思議な感じがするんですけど。","respondent":"齋藤道路公園課長","answer":"ご指摘のとおりですが、いくつか事情がございまして、一つは、構成メンバーは中身はほとんど同じなんです。その日、終日、町会のお祭りがありまして、私どもは３時から予定しておりましたが、町会長の方から、町会も協力したいので全員参加したいというお申し出がございました。","voiceIndex":23,"id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"資源回収ステーションというのは、今、マンションなんかだと一括で回収していますし、一戸建てが並ぶところでは、何軒かの家で一緒になって回収するという形式のようですけれども、実際に今、この資源回収ステーションと名づけられるものって何カ所あるんですか。","respondent":"太田品川区清掃事務所長","answer":"資源回収ステーションの箇所数ですけれども、区内で約１万カ所。従来の集積所と呼んでいたところですが、約１万カ所あります。","voiceIndex":29,"id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"当然、これはびんのボックスですよとか、そういうものがあるところもあるのか、ないところの方が多いのかもしれないですけれども、とにかく、持ってきたものをばらばらに置かれているんだけれども、その辺の改善をしていかないと、トレイとか紙パックだとかってさらに品目を増やしていくと、さらにばらばらに置かれていくことになっていくんじゃないですかね。","respondent":"太田品川区清掃事務所長","answer":"今回の部分については、先ほど申し上げましたように、２７カ所全体の量自体がかなり減ってきているということもありますので、それが資源回収ステーションの方へ移行しても、１万カ所ありますので、そこでの対応というのは可能だと考えています。","voiceIndex":31,"id":"exchange-007"},{"speaker":"菊地委員","kind":"質問","question":"もう一つ聞きたいんだけれども、例えばびんの回収ボックスとか、かんの回収ボックス、あるいはトレイの回収ボックスという区分けをするようなものを置くということは考えていないんですかね。","respondent":"太田品川区清掃事務所長","answer":"今の時点では、従来どおりの形で実施をしていきたいということです。","voiceIndex":33,"id":"exchange-008"},{"speaker":"武内委員","kind":"質問","question":"エコボックスというのは、あまり見たことないですけど、ボックスがあるんですよね。廃止後は全部捨てちゃうわけですか。","respondent":"太田品川区清掃事務所長","answer":"現在設置している場所から、区で回収をします。","voiceIndex":35,"id":"exchange-009"},{"speaker":"武内委員","kind":"質問","question":"直接関係ないのかもしれないですけど、入れ歯とか携帯というのは、まだ回収した後のルートというのは増えていないんですか。まだあまり回収していないんでしょうか。","respondent":"太田品川区清掃事務所長","answer":"携帯については、基本的には事業者責任でやっています。それから、昨年ですか、東京都がモデルで実施をしていますし、それから今年については、国が携帯の回収率を上げようということで、事業者との中で仕掛けをして実施をしていっております。","voiceIndex":37,"id":"exchange-010"},{"speaker":"武内委員","kind":"意見","question":"時期がずれちゃったからしようがないですね。うまくリンクすればそれに越したことはないです。公共施設の方にボックスが設置されて、携帯とかそういうのが入れられないかと思ったのは、まだまだちょっと時期尚早という感じがありますので、今後、回収できるような形になっていけばと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-011"},{"speaker":"市川委員","kind":"質問","question":"今、トレイの回収は資源回収ステーションでもしていますけれども、拠点回収のトレイは回収していると思うんですけれども、そこのところは今後どのようになっていくんですか。","respondent":"太田品川区清掃事務所長","answer":"ご指摘のとおり、拠点回収においても、月２回で実施をしていますが、これについては、今、検討をしているという段階です。","voiceIndex":40,"id":"exchange-012"},{"speaker":"市川委員","kind":"質問","question":"検討しているということは、なくす方向で検討しているということですか。","respondent":"太田品川区清掃事務所長","answer":"基本的には、今申し上げたように、資源回収ステーションに一元化していく方向でこれまできてありますので、残りの調整事項というのがありますので、それについて、今、検討しています。","voiceIndex":42,"id":"exchange-013"},{"speaker":"市川委員","kind":"意見","question":"食品トレイは、今までは拠点回収とエコボックスでしたけれども、トレイ・トゥ・トレイでトレイに生まれ変わるというようなリサイクルの仕方だったと思うんですけれども、拠点回収をした場合も、トレイだけをトレイ・トゥ・トレイの形で残すのか、それとも他のきれいなプラスチック類と一緒に、コークスを燃焼するためのものとして使っていくのか、その辺を聞きたい。","respondent":"太田品川区清掃事務所長","answer":"今後、資源回収ステーションで回収するようになりますので、その場合には、きれいなプラスチック製品の品目として、他のプラスチックと一緒に収集することになりますので、処理についても、今、委員がおっしゃったようなトレイ・トゥ・トレイという処理ではなくて。","voiceIndex":44,"id":"exchange-014"},{"speaker":"市川委員","kind":"質問","question":"もう一つ、別のところで聞きたいんですけど、エコボックスを廃止して、費用対効果というところでもどうなのかというのも問題なので、廃止というのも仕方ないかなと思うんですが、このエコボックスを廃止したことによって回収、それから中間処理あたりの費用が浮くということなんでしょうか。","respondent":"太田品川区清掃事務所長","answer":"費用対効果の面で申し上げれば、一番大きいのは、この２７カ所に区の方から車を雇い上げております。その部分で、委託業務の経費がありますので、その分が廃止になれば、平成２２年度予算ではその分が削減になるです。","voiceIndex":46,"id":"exchange-015"},{"speaker":"市川委員","kind":"質問・要望","question":"品川区のリサイクルの考え方を伺いたいんですけれども、生活者ネットワークでは、プラスチックでも細分化のリサイクルを検討していただきたいというような考え方を持っているんですけれども、実際、もっと細かくリサイクルをしていくという点では、品川区としてはどのような考え方をしているのか、最後に伺いたいと思います。","respondent":"太田品川区清掃事務所長","answer":"現状では、昨年から実施したばかりですので、そういう意味では現状のまま、このままで遂行していきたいと考えております。","voiceIndex":48,"id":"exchange-016"},{"speaker":"菊地委員","kind":"意見","question":"一つだけ、以前にも聞いたことがあるんですけれども、ここで言う事業再建者向け定期使用住宅なんですけれども、これはこの１年間を見たときに、品川区内の方、あるいは東京全体で、この制度を使われた方というのはおられますか。","respondent":"柏原住宅担当課長","answer":"この時点では、申し込みはなかったと聞いております。","voiceIndex":54,"id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、これは何年間か続けられていますけれども、結局、申し込みもなく、入居する方もなく、だけどこうやって募集をする以上は、一定期間そこをあけておかなくちゃならないということだと思うんですけれども、今回の募集で新たにこういう申し込みはありませんでしたよといった場合に、この１０戸というのは一体いつまであけておく形になるんですかね。","respondent":"柏原住宅担当課長","answer":"申し込みの段階で１０戸あいているということではなくて、あいたところからご案内するということになっているようなんですが、ただ、東京都の方にも確認しましたところ、期間というところまではちょっとあれなんですが、無駄にその期間あけておくということは。","voiceIndex":56,"id":"exchange-018"},{"speaker":"菊地委員","kind":"質問・要望","question":"よく住民の皆さんから聞くのは、「都営住宅、随分あいてるよ」という声を聞くんだけれども、結局は、こういう設定をされた住宅についても、きっと住民の目から見ればあいている住宅になってしまうのかなと思いますので、本当に有効に活用していくんだということであれば、この数年間やってきて、これに申し込む方というのがほとんどいなかったという実態を見て。","respondent":"柏原住宅担当課長","answer":"確かに、もしずっとあいた状態であるということであれば、それは無駄なことでありますので、東京都がどういうふうな考えかというのはあると思うんですけれども、無駄にあいているということであれば、それはよろしいことではないと思いますので、都の方にはこちらの方で。","voiceIndex":58,"id":"exchange-019"},{"speaker":"武内委員","kind":"質問・要望","question":"各地区単位のものは毎年毎年行っていると思いますが、学校避難所単位でやっているところもあるかと思うんですけれども、どのぐらいのところがやっているのか、もしつかんでいらっしゃれば教えていただきたい。","respondent":"佐藤防災安全担当課長","answer":"現在、手元の資料では、開催数は把握しておりません。","voiceIndex":64,"id":"exchange-020"},{"speaker":"武内委員","kind":"質問","question":"区としては、今後、例えばそれは学校避難所にかかわらず、町会だとかにお任せで、自主的にやっていただく、それを全面的にバックアップするという姿勢なんですね。それをもうちょっと積極的に呼びかけて、地区単位はもちろんやるんですけれども、もうちょっと身近な単位で。うちの地区は避難所単位でやっていないですから。そういった部分を区としてどう考えているか。その辺はどうなのか。","respondent":"中山防災課長","answer":"ただその実施が偏っている部分もありますので、私どもで働きかけを行いまして、あるゆる地区で避難所訓練、要するに、教室まで決めているところがありますので、そのような形に持っていきたいと考えています。","voiceIndex":66,"id":"exchange-021"},{"speaker":"武内委員","kind":"質問・要望","question":"うちの地区ではやっていないのかもしれませんけれども、あまりやっているような感じがないな、周知もされていないのかなと思いましたので。ぜひ、そういう身近な単位での避難所訓練も積極的に推進していただきたい。こういうところで報告するかどうかは別としても、推進はしていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-022"}]},{"id":"topic-02","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"藤原委員","kind":"意見","question":"この間の委員会のときに、いろいろな委員から意見をいただいて、そのときには四国なんか出ていなかったような気がするんですが。私の感覚では出ていなかったと思うんですが、大阪は出ていましたよね。副委員長から岡山や広島というのが出ましたよね。そういうふうに行くのかなと思ったんですけれども、何で急にこの四国が出てきちゃったのかと思うんですけど、その辺について説明していただけますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-023"},{"speaker":"武内委員","kind":"質問","question":"商店街、市街地再開発というと、イメージとしてはどんなイメージですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-024"},{"speaker":"阿部副委員長","kind":"質問","question":"商店街の再開発で活性化される面と、それからハード面の再開発が気になって、硬いものとしての再開発というんですか、そういったものと両面でやっているところですので、ソフト面というよりも、ハード面での、そういった考え方についてを調査したいと考えています。","respondent":"伊藤委員長","answer":"高松、堺、大阪市、具体的な対応を含めて、きょうの時点で考えを示していかないと、先方もあるでしょうし、そういうことで今日ご意見をいただきますので、ぜひご発言をお願いします。","voiceIndex":75,"id":"exchange-025"},{"speaker":"阿部副委員長","kind":"意見","question":"前回の委員会のときに、神戸の震災という話が出てきて、それもいろいろと検討したんですけれども、ただ、今のタイミングで、じゃあ神戸に行ってできることって何だろうと。震災記念館の見学ぐらいしか見てこなかったのでは、それでは視察の内容としてはかなり寂しいなという判断も実はありました。結果として、記念館一つ見にいくために、みんなで視察はどうだろうねということでやめました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":77,"id":"exchange-026"},{"speaker":"菊地委員","kind":"意見","question":"委員会でそれぞれいくつか意見があって、論議がされて、その上で正副委員長のところで考えて決めてくださった部分ですので、これはこれでいいんだと思うんです。多少は考えをまとめての視察にしていかなければならないと思いますので、その点で、資料についても、後ほど委員のところにわかるようにお願いをしていきたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":78,"id":"exchange-027"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"藤原委員","kind":"意見","question":"前回の委員会でご報告いただいたバイクのときのベストですが、私も、この委員会の委員なので、出席をさせていただきまして、イベント的には効果があってよかったと思うんですが、その後、問い合わせとかという形でどういう状況なのか、報告していただけますか。","respondent":"諸石交通安全担当課長","answer":"今、委員の方からお話がありました、二輪車の出動式、あわせてボディプロテクターのお披露目もやったんですが、テレビの方はＮＨＫと民放が１社、それと新聞の方も数社取り上げていただきました。","voiceIndex":82,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3952#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":15110,"voices":84}},{"id":"h21-20090721-9","meetingId":"h21-cm07","date":"2009年7月21日","dateIso":"2009-07-21","committee":"文教委員会","time":"午後１時０３分～午後４時０５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"アンケート調査の説明があって、全体として３つぐらい指摘があったと思うんですけれども、このアンケートの目的そのものが、保護者の意向を把握して特色ある学校づくりの参考ということなので、先ほど全体として地元の学校を選ぶ人が多いだとか、学校を選ぶときは自分の目で見てという話がありましたけれども、そういった傾向を踏まえて、どのような学校づくりに反映していこうと思っているのか。","respondent":"富田学務課長","answer":"この学校の特色ある教育活動を考えてという設問への回答は、比較的少ないようにも見えますけれども、学校によっては、先ほど小中一貫連携の数字だけ申し上げましたけれども、習熟度別学習で選ばれた方が多いところだとか、小学校でいえば教科担任で選んだ方が多いところ。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"いまいち、毎年このアンケートをとるんですけれども、それがどうだったのというところが冒頭の説明で見えてこないので、去年も同じような質問をしたと思うんですけれども、ちょっとよくわからないんですよね。傾向を見ますと、例えば小学校でいえば、いわゆる従来の指定校に入学したが６５％で、大体毎年６割強という傾向だと思うんですよね。","respondent":"富田学務課長","answer":"従来の指定校に入学する方が増えてきたということは、学校選択を否定するものでは全くないというふうに思っておりまして、従来の指定校を含めて選択することができるわけでありまして、その選択した結果が従来の通学区域の学校を選んだということであり。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"むしろ保護者も地域も町会関係者も学識経験者も、学校選択制の弊害を指摘する意見、やめるよう行政に求める意見というのが私は強まっているなと思っているんですよね。どうして地域住民の方々は学校選択制について、負の部分、マイナスの部分を指摘しているのか、そういう思いというのは教育委員会はどんなふうに受けとめているのかなと伺いたいなと思っているんです。教育委員会としては把握されていますか。","respondent":"富田学務課長","answer":"この２つの理由に沿って学校選択制を実施して１０年になりますけれども、保護者の方々にも十分定着をしてきており、学校選択がなくてはならないものというふうに保護者のほうで受けとめているというふうに考えております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"保護者たちがどういうところに不安を持っているのかというのが、結局受けとめてくれていないのかなと今の説明で思うんですけれども、選択制を始めた理由が、選ばれる学校とすることで学校の内なる改革というんですか、あともう１つは、保護者の選ぶということを保証したい、２点説明がありましたけれども、そもそも学校選択制の中で地域との関係が崩れているなと私は思うんですよね。ちょっと伺いたい。","respondent":"和氣小中一貫教育担当課長","answer":"さらに私どもは、選択制をやる中で、少なくとも学校が変わったと考えておりますし、先ほど学務課長からもありましたように、学務課で実施したアンケートでも、私どもが実施した保護者アンケートでも高い評価を得て。","voiceIndex":11,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"その際、多様な意見に耳を傾けて、その意見の背景に何があるのか、どんな教育を望んでいるのか、やっぱりいわゆる反対意見を切り捨てる、退けるという姿勢ではなくて、十分な議論を踏まえることが大事だと思いますし、とりわけこの教育の分野ですから、トップダウンではなくて、形ばかりでない丁寧な議論の保証というのが大事ではないのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"浅野委員","kind":"質問・要望","question":"後の日程もあるみたいなので、端的に３点ほど質問させていただきたいと思います。もしかしたら私なんかはもうちょっと、こんなにではなくて多いのではないのかなと、自分の兄弟が行っているから嫌だという子は中にいると思うんですけれども、この母数は、例えばお兄さん、お姉さんがいない人も母数として考えているのかどうかということを先にちょっと１点お聞きしたいなと。","respondent":"富田学務課長","answer":"これは回答した方すべてについての割合です。兄弟のある方に限定するのはちょっと困難です。","voiceIndex":14,"id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"ぜひとも母数を間違えるといけないので、次回、両方とっても構わないと思うんですけれども、考慮した数字をぜひともいただければなと。それと、例えばその他とありますけれども、例えば自分はこう思うという、例えば理科の実験が気に入っているとか、そういうような記入もあったのかどうか、それについてお伺いします。","respondent":"富田学務課長","answer":"当初よりプラン２１の柱として、計画として進めてきているこういった選択肢を設けており、これ以外については記載はしておりません。その他ということでの自由意見については、かなりたくさんちょうだいしております。","voiceIndex":16,"id":"exchange-007"},{"speaker":"浅野委員","kind":"質問・要望","question":"説明は多分学校のほうで当然するわけなんですけれども、教職員の方が説明をする中に、例えばこういう習熟度別ですとか、学校の特色的なものというのは、かなりやはり強調されるのではないかなと思うんですけれども、それは特に統一をとってというのでしょうか、各学校はこのようにやったらどうかとか、そういうような指針といいましょうか、そういうものは教育委員会として出しているのかどうかということと。","respondent":"富田学務課長","answer":"これはありのままの学校を見てもらいたいということと、子どもたちの姿をより多くの方々に見てほしいということで実施をしているものであり、このほかに１学期間に実施するところもありますし、あともう１つ多くは、学校選択の時期、１０月ごろに計画的に学校公開を行いまして。","voiceIndex":18,"id":"exchange-008"},{"speaker":"浅野委員","kind":"意見","question":"これはやはり教職員の方が自分の学校をどうアピールするかという、そういう知恵比べでもあるのかなと、さまざまな観点で学校をアピールするということ、これは非常に私も重要だと思います。ただ、過密した競争になってはこれは当然いけないと思いますけれども、ぜひともそういういい風土というものをこれからも醸成していっていただければと思いますので、これは意見で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"幾つか質問いたします。書き方からなんですが、学校の特色ある教育活動の項目の小中連携教育というところが、「小中一貫教育・連携教育」と書いてあるところと、「小中連携教育」と書いてあるところがあるんですが、何か違いがあるのかという質問をしたいんです。","respondent":"富田学務課長","answer":"これは小中一貫教育・連携教育ということでの選択肢でございまして、差異があるのは、申しわけございません、ちょっとこの表をつくるのに当たっての手違いの部分です。申しわけございません。","voiceIndex":21,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"その体制はどういうふうなお考えで今後やっていくのかなというのがまず１点。平成１９年度は３番に上がっていたんです。保護者の方の意識がかなり変わってしまってこういう形になっているのか、教育委員会としての見解と、学校現場の中でのまちの人からというのは私は推進していただきたいんですが、どういう形になってしまっているのだろうというところがあります。今までは１番じゃなかったんですよ。","respondent":"富田学務課長、冠木指導課長","answer":"それと３点目ですが、中学校の公立中学校に進んだ方々で小中連携の回答が増えているということですが、これは小中一貫に限らず、特に今年度の特徴として。２番目のご質問ですけれども、「町の人々から学ぶ授業」については、昨年度も今年度も地域の方々のご協力をいただきまして、授業自体については活発にやらせていただいているところですけれども。","voiceIndex":23,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"やっぱりこういうＰＲではないんですけれども、本当にいろいろな方が学校にかかわっていただいて、これは保幼小の一体的ないろいろなことをやると思うんですけれども、この中でもやっぱり地域が育てていくという大きな目的があるものですから、それをやっぱり保護者は預けっ放しではない、自分たちも含めて地域の一員だというところの意識づけをしながら。","respondent":"富田学務課長","answer":"特に学校を選んだ理由が学校によりかなり異なるというのが事実ですので、校長会の日に学校長にはお示しをしており、そういった学校ごとのデータをお渡しをしておりますので、今後の学校経営にぜひ参考にしながら生かしていってほしいと考えています。","voiceIndex":26,"id":"exchange-012"},{"speaker":"西本委員","kind":"意見","question":"かなり校長先生にしてみると、非常にシビアな値になると思うんですよね。数値だけで評価はできないところがあると思うので、そこはいろいろ傾向を見ながら、それからその学校がどういうふうなことをやっているからという裏付けをある程度する形で今後につなげていけるような形でとっていただけたらなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-013"},{"speaker":"井上委員","kind":"質問・要望","question":"一番最初の中塚委員の質問にちょっと関連するんですが、このアンケートをどういうふうに使うかというところで、教育計画に生かしてほしいということで学校に返しているということだったんですが、今、アンケートが学校ごとに差があるというところを、そこを伺えばそういうことになるんですが、全体のこの資料を見て。","respondent":"冠木指導課長、富田学務課長","answer":"例えば、１つご紹介いたしますと、習熟度別学習というような項目があるんですけれども、この習熟度別学習にしましても、保護者の意見はその習熟度別学習のどこの部分にターゲットを絞った指導をしてほしいのかとか。後段のご質問ですけれども、小中一貫校、施設一体型の一貫校に入学された方のうち、従来の指定校以外の区立中学校に入学すると答えている方の割合というのは、ちょっと統計上は出せない、出ていない数字です。","voiceIndex":29,"id":"exchange-014"},{"speaker":"井上委員","kind":"質問","question":"そういうふうに考えていいと思うんです。だから、そういう分析も、選んだ中で必要ではないかというふうに思うということなんですけれども、データはどういうふうになっているんでしょうか。","respondent":"富田学務課長","answer":"新１年生につきましては、「施設一体型一貫校に期待して」という選択肢は小学校のほうでは入れておりますが、中学校ではそういったものは入っておりませんので、ここのアの一貫教育・連携教育の回答のみということになります。","voiceIndex":32,"id":"exchange-015"},{"speaker":"井上委員","kind":"質問","question":"本来であれば、地域の人たちがもっと声が上がって通学区域の自由化はやめて、自分たちの地域をつくっていく上で地域の学校にという選択ができるというふうになると思うんですけれども、それに一体校というものができてしまったから、逆戻りは品川区は逆にできないというふうに私は思うんですけれども、その辺のところについての見解を教えてください。","respondent":"和氣小中一貫教育担当課長","answer":"ご質問の趣旨がよくわからないんですけれども、理解しがたいんですけれども、基本的に私ども、各地区に施設一体型一貫校をつくって、各地区に建てない限りは全体の、まだ行かれない人たちが、そもそも選べない人たちもいるわけで、ブロック内で、そういうこともありますので。","voiceIndex":34,"id":"exchange-016"},{"speaker":"井上委員","kind":"質問","question":"今、それぞれの学校を選んでいるわけですとおっしゃったので、だからそれぞれの学校の小中一貫の一体型と、そうじゃない学校を選んでいる比率というのがどのようになっているんですかと、そこがはっきりしないと、してほしいということなんですけれども、今それぞれの学校はどうですか。","respondent":"和氣小中一貫教育担当課長","answer":"例えば、申し込んだからといって、希望したからといって、絶対に入れるわけではないという、残念ながら施設を今整備していますので、ということもあります。それも含めて正しい数値はとれないというように思っています。","voiceIndex":36,"id":"exchange-017"},{"speaker":"井上委員","kind":"意見","question":"私は、今おっしゃっていたブロック内というのを、小中一貫校をつくる上でブロック内という前提があるから各地域に、ブロックにつくりましょうという前提で、そこが全部つくらなければそういう評価はわからないということだったんだけれども、そこ自体がまだ認められないというか、そこが本当にいいのかという立場に立っているので、そこのところではちょっと違うというふうに思っているんです。","respondent":"和氣小中一貫教育担当課長","answer":"そもそも本当に６校構想を立てた最初に各ブロックに建てるのを前提に私ども計画を進めておりますので、さらに、抽選になっているということを考えてください。抽選になっているんですよ、今の一貫校は。こんなに支持されないんだったら抽選にならないと私は考えております。","voiceIndex":38,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"ジュニアリーダーの件で何件か。サマーキャンプという項がありますけれども、ジュニアリーダーそもそもの入会というんですか、そういう形はどうなんでしょう。増えてきているのか、あんまり増えていないのか、いかがですか。","respondent":"小林青少年育成課長","answer":"こちらのジュニアリーダー教室は、月１回程度をめどとして年間を通して活動を行っております。その希望動向ですけれども、昨年よりは若干今年少なくなっておりますけれども、大体定員に対しまして１割弱、残念ながら受けていただけない、お断りする例があります。","voiceIndex":44,"id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"そうすると、ジュニアリーダーの教室へ参加する人は減っているという理解でいいですか。増えているか、減っているか。","respondent":"小林青少年育成課長","answer":"過去５年の推移としては、微増傾向です。ただ、今年は昨年に比べて若干希望者は少のうあります。","voiceIndex":46,"id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"ジュニアリーダーをまず推進してほしいという気持ちと、それから、ジュニアリーダーを卒業した高校生、大学生というのも、ぜひちょっと何か児童センターにつないでいくとか、居場所も含めて、そういう中でこれを発展させていただきたいという気持ちがあるんですが、そういうお考えはありますか。","respondent":"小林青少年育成課長","answer":"今年もジュニアリーダーで育成された人が指導者としてもう活動を始めている例もありますので、そういった流れが大きくなっていくといいかなというふうに期待しながら指導してまいりたいと思います。","voiceIndex":48,"id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"このパンフレットなんですけれども、いつも夏休みが始まる時期に配られたり、子どもたちにも配ると思うんですけれども、それで、どういうふうにこれを使っているのかと、いつも配って終わりというのが自分の子どもたちのときの経験なんですが、これはどういうふうに配って、学校でこれをどのように生かして、生活習慣のこととか、いろいろ携帯やインターネットのわなとか、そういう部分というのを。","respondent":"小林青少年育成課長","answer":"夏休みに向けてということで配布する時期、なかなか学校も終業式等を含めてお忙しいところですので、なかなか制約もあろうかと思いますが、学校等で配布していただくときには、先生から所要のお言葉を添えてお配りいただいていると思いますし、それよりも大切なことは。","voiceIndex":50,"id":"exchange-022"},{"speaker":"井上委員","kind":"質問・要望","question":"家庭でこれを配って子どもたちにというのは、それは役割は役割としてそういう働きかけがないと大変難しいというふうに、希望はそうであるし、私たちもそうは思っているんですけれども、具体的にこういったところで、こんなところに危険がいっぱいということに対して、自分たちがどういうふうな危険があって、それに対してどういう対処をしていこうかということ、子ども自身が育つほうが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-023"},{"speaker":"浅野委員","kind":"質問・要望","question":"これはやはりインフルエンザのことを注意をされているかと思います。そしてまた、特にそれ以外に何か家庭の日ということでやられていることがあれば教えていただきたいのが１つと、あと、表紙のイラストとこちらの挿絵、中身ですけれども、去年、今年も特定の中学校で１校だけからの選出になっていますけれども、これは持ち回りでされているのかどうか。その点についてお伺いしたいと思います。","respondent":"小林青少年育成課長","answer":"表紙等につきましてなんですけれども、中学校の先生にお願いしまして対応していただいているところで、各中学校の中でお話し合いによって応募していただく絵画について利用しています。","voiceIndex":53,"id":"exchange-024"}]},{"id":"topic-02","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"この「しながわアクション」の下に青少年対策地区委員会等、簡単にいうと４団体というか、大きく４団体ありますけれども、この４つで取り組んできた経過というんですか、話し合いの経過を少し教えていただければなと。","respondent":"冠木指導課長、小林青少年育成課長","answer":"ＰＴＡ、それから学校関係につきましては、１つ前の青少年問題協議会の席上、こういう議論がございまして、ご意見ございまして、今まで生活指導担当者であるとか、もちろん管理職も含めまして、子どもたちの携帯電話の使い方。今お話しがありましたように、前回の問題提起を受けまして、各団体ということで、各地区委員会が地域として、そしてＰＴＡ、小学校、中学校のＰＴＡが家庭として、そして学校として、それぞれの課題等を持ち寄る中で。","voiceIndex":59,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"済みません、地図が頭の中にまだよく入っていないのですが、これ、４市ですよね。しかも山口県から熊本まで、これは２泊３日で回り切れるんですか。交通事情もあると思うんですけれども、項目としては非常にどれも捨てがたいというか、行きたいなという部分ばかりなんですけれども、ただ、実際的にあまりきついと、これ、大丈夫かなというところが心配なんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-026"},{"speaker":"林副委員長","kind":"質問","question":"相手の都合もあるわけだから、これがそっくり行程の中に入り込むかどうかはこれからですから。品川区の教育委員会として見たいところはないんですか。","respondent":"市川教育次長","answer":"いずれの自治体でも、それぞれ事情に応じた施策を展開されていますので、見たいと思うところはいずれの地でもあります。","voiceIndex":75,"id":"exchange-027"},{"speaker":"林副委員長","kind":"質問","question":"同じ自治体の中で就学前の教育、育児という部分、保育という部分も含めての就学前と、いわゆる義務教育という中での自治体の教育委員会がありというのとは随分、行政マンの中では差がないんですか、あるでしょう。","respondent":"古川子ども未来事業部長","answer":"こちら側のサイドでは、いずれにしてもそれはそれぞれの自治体が今後の１０年なり、２０年なりを先をどう見越した政策を組織として持つかという問題ですから、どっちにあってもやることはそれほど大きくは変わらないでしょうけれども。","voiceIndex":79,"id":"exchange-028"},{"speaker":"林副委員長","kind":"意見","question":"それが知らんぷりということはできなくなってきているわけだから。かといって、義務教育、ややこしいけれども、学校へ入学する前の段階が義務的、小・中の義務とまた違う行政の仕事になっているわけでしょう。","respondent":"古川子ども未来事業部長","answer":"総務課長で私立幼稚園との関係があって、今度は教育次長になって教育委員会に行きましたときに、やっぱりそうしたときに、自分が育ってきた就学前のものが小・中学校の校長先生とお話をするときも、いや、実は子どもって。","voiceIndex":81,"id":"exchange-029"},{"speaker":"林副委員長","kind":"提案","question":"前に私たちもちょっと提案したけれども、ノルウェーなんかへ行くと、４月ごろから２カ月間ぐらい学校に上げちゃうわけだよね。保育園、上がる前の子どもは。そうすると、上の事情をよく知っていないと上げる子どもたちにいろいろなものをサジェスチョンするのもできないし、受ける側もその保育園でどういうことをやってきて、今、なんで受け入れるのかというのがわかっていないとだめです。","respondent":"古川子ども未来事業部長","answer":"そういうこともあって、保幼小の検討委員会を立ち上げたというのは、まさに教育委員会サイドが事務局になって、ゼロからの育ちの部分を小学校につないでいくという、そこにたどり着いてきたというところだと思います。そこまでに時間はやっぱりかかります。","voiceIndex":83,"id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4676#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":25338,"voices":86}},{"id":"h21-20090721-5","meetingId":"h21-cm07","date":"2009年7月21日","dateIso":"2009-07-21","committee":"総務委員会","time":"午後１時０３分～午後１時５５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の新型インフルエンザ対策","agenda":"の新型インフルエンザ対策","exchanges":[{"speaker":"山元委員","kind":"意見","question":"今、７月１１日から新型インフルエンザ相談センターを開設するということなんですが、具体的な内容で、どういう方たちが対応してくださるのか。","respondent":"伊勢危機管理室長","answer":"そうでない方は、その方の住んでいる近くの一般の医療機関を紹介するというようなことです。それから、担当の方は、保健所の方で担当しています。これまで、会議室を設けてやっていたんですけど、今は保健所内で、保健師がまずはその点を行うということにしております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"宮崎委員","kind":"意見","question":"区民等への周知の(9)のところで、区内企業・事業所インフルエンザ対策意見交換会、詳細はこれからということですけれども、危機管理室なので、インフルエンザ患者の対応とか、そういうことなのか、あるいは区内企業・事業所なので、発生した場合の経済的な影響だとかも考えられるんですけれども、そういうところも想定した意見交換をやるのか、どこら辺まで想定しているのか。","respondent":"伊勢危機管理室長","answer":"そこの担当の方々と意見交換をしながら、８月２０日の会合をどういう形で運営するか、例えば会社でこれからＢＣＰをつくろうとする場合にどうやったらいいか、それに向けて講師を呼んだほうがいいかとか、あるいは企業方針でやるだとか、あるいは業種別にやるだとか。","voiceIndex":7,"id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"一般質問で、経済的な影響が関西の方でいろいろ問題になって、いろいろな経済的な対応なんかも必要じゃないかとご質問したんですけれども、そういうことも含めてやっていく、あるいは事業所の中でインフルエンザの発症があって、患者が発生した場合の対応はどうするのか、そういう話なんですか。","respondent":"伊勢危機管理室長","answer":"それで、経済的損失も当然出てきますし、その辺については、商工部門の融資だとかというのもできましょうし、区の方でも、事業をまず継続していかないと、区民生活に重大な影響がありますので、それを継続させるための方策をどうしていったらいいのか。","voiceIndex":9,"id":"exchange-003"},{"speaker":"土井委員","kind":"質問・要望","question":"要するに、国を含めてこの新型インフルエンザに対する対策・対応が、「入ってこないように」というところから、「もう入っちゃっている中でどうするか」という方向に移ってきたと。というのは、この種のものはホットなときはものすごくホットなんですけど、もにゃもにゃと小さくなっていくとすっかり忘れちゃう可能性があるので、そうではないんだよと。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"}]},{"id":"topic-02","title":"の「男女共同参画のための品川区行動計画（第４次）」の策定","agenda":"の「男女共同参画のための品川区行動計画（第４次）」の策定","exchanges":[{"speaker":"土井委員","kind":"意見","question":"今まで、第４次までいろいろ行動計画をされてきたという形になっていて、したがって、その間に何らかの進歩をしたり、何かが変化をして、初めは必要だったものがもう要らない、あるいはあまり大声で言わなくても周知できている、でも、これから新しいのをやる、こういうめりはりのところの部分を説明いただくと、皆さんに説明するときにしやすいんですが。","respondent":"中山人権啓発課長","answer":"当初は、女性が家にいるのではなく、外に、社会に出ていくということを特に重点に置いていたと思うんですが、ここ最近の傾向としましては、それぞれの法律の整備も進んでまいっておりますので、今は女性のみというよりは、男性も女性もワーク・ライフ・バランスのようなもので。","voiceIndex":16,"id":"exchange-005"},{"speaker":"土井委員","kind":"質問","question":"そういう中で、新しい考え方、特にワーク・ライフ・バランスなどは相当新しい取組みですから、そういう形で、男性・女性ともに、採用するのは当然よ、対等なのは当たり前みたいな発想じゃない、男でも女でもあるということをうまいことわからせるようにしていかなきゃならんのではないかなと思っているので、今のご説明で結構ですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問・要望","question":"実際、窓口がどうなって、どういうふうに対応されているのか。それはそれでいいんだろうと思うんですが、実際、相手があるので、行政としてもどこまで対応するのかというのが見えないんですが、その辺の流れというか、そこもあわせて、参考までに教えていただきたいなと思うんですが。","respondent":"中山人権啓発課長","answer":"私どもの方に相談にいらっしゃって、話をして、ちょっと落ち着いて帰られるという方から、すぐに対応してほしいというような方につきましては、子育て支援課の方におつなぎして、子育て支援課が、今度は東京都のウィメンズプラザというようなところと連携をして。","voiceIndex":19,"id":"exchange-007"},{"speaker":"山元委員","kind":"質問","question":"第４章のところに、女性のチャレンジ支援というのがありますが、具体的にどういう部分と考えたらいいですか。","respondent":"中山人権啓発課長","answer":"女性が社会に出ていくためのチャレンジ支援ということで、例えば起業家セミナー。独立されて、起業するためのことを学習して、実際にお店を出されたりとかという方もいらっしゃいます。具体的にはそういうような支援をすることも、ここに入ってきます。","voiceIndex":21,"id":"exchange-008"},{"speaker":"山元委員","kind":"質問","question":"方法としては、その企業家セミナー一つだけですか。ほかにまだ考えていらっしゃいますか。","respondent":"中山人権啓発課長","answer":"そのほか、就職あっ旋ということで、在宅ワークあっ旋ですとか、再就職に関するセミナー、それからパソコン講座の開催、そういったものもやっております。","voiceIndex":23,"id":"exchange-009"}]},{"id":"topic-03","title":"の鈴ケ森小学校1)棟耐震改修工事請負契約","agenda":"の鈴ケ森小学校1)棟耐震改修工事請負契約","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"工法について、よくわからないので説明していただければと思うんですけれども、制震ブレースというのは、要するに車のダンパーと同じようなことだと思うんですが、その場合、ダンパーがエネルギーを吸収してやるんだということだと、建物自体は変形するとか、そういうことになるわけですよね。ならないんですか。","respondent":"宍戸施設整備課長","answer":"普通の斜め材で補強するのと、形としては非常によく似ているんですけれども、考え方はちょっと違っていて、斜め材で力を加えることによって強くするということではなくて、実は二重構造になっておりまして、摩擦ということですけれども、そこで力を吸収するということです。","voiceIndex":29,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"例えばＣのところだと、鉄板を巻いて柱そのものを地震が来ても変形させないということなんですよね。鉄板を巻いた柱はがっちりしている。だけど、プレースで力を吸収するというのは、建物自体については変形するんじゃないですか。こうなったり、こうなったり。そういうことではないですか。","respondent":"阿部経理課長","answer":"５ページの工法図をごらんください。一番上に制震ブレースと書いてありますけれども、ここの中に、ちょっとわかりにくいんですが、「鋼管ブレース」、その下に「摩擦ダンパー」と書いてあります。鋼管ブレースと摩擦ダンパーというのはくっついています。","voiceIndex":31,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問","question":"要するに、柱に行く力をそこで吸収するということで、柱への力を弱めるということなんですか。私が疑問だったのは幾つかあるんだけど、結局、建物は歪んだりするのかなというのがちょっとわからなかったので。要するに、柱への力を弱めるということで考えたらいいですか。","respondent":"宍戸施設整備課長","answer":"結果的には柱への力を弱めると思います。制震ブレースで吸収するわけですから、本来であれば、柱とか梁に地震力が直接かかる力をこの制震ブレースで吸収するというものです。","voiceIndex":33,"id":"exchange-012"},{"speaker":"土井委員","kind":"質問","question":"要するに、値引率がさほどないものを、通常の他のものと同じような、もしくはそれに類するような形で値引率をかけて出したというようなことだとすると、次の段階では、少なくとも正しいというか、実勢に従った積算が出てきて、さてそれをどうするかという形で、また元に戻れば、「ちょっと間違いがありましたけど、また一般競争入札をやりますよ」でもよかったのではないかというふうにも思えますし。","respondent":"阿部経理課長","answer":"先ほどもご説明いたしましたけれども、基本的には１,０００万円を超えるものにつきましては、制限付き一般競争入札を行うということを原則としております。","voiceIndex":37,"id":"exchange-013"},{"speaker":"土井委員","kind":"質問","question":"というのは、さっきちょっと心配したのは、最初に一生懸命やった業者が、最初にちゃんとした値段だったら受けられたかもしれないというのが気になったものですから伺ったので、これが、どこに原因があったのかということでちょっとしっかり分析していただくということで、ある意味ではダブルチェックの問題であるのか、もともとの教育訓練の問題なのか、幾つかあるんだろうと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-014"},{"speaker":"山元委員","kind":"質問","question":"初歩的なことでお恥ずかしいんですが、このブレースの形と言いますか、学校によって違うところがあるような気がしたんですが、何かあるんでしょうか。","respondent":"宍戸施設整備課長","answer":"先ほどもちょっと申し上げたんですが、技術評価を受けている関係上、通常の工事会社が制震ブレース、ＳＲＣブレースを使うときに、ある程度限られた会社にしか発注できないというようなこともございまして、当初は分散をするように設計したということがあります。","voiceIndex":40,"id":"exchange-015"},{"speaker":"若林副委員長","kind":"質問","question":"先ほどの続きになるかもしれませんが、積算を出すときに、徹底をされていなかったというお話があったんですが、これは区の内部の方で値引率が低いということが徹底されていなかったのか、それとも区から積算に出すときに設計会社に徹底をされていなかったのか、どちらの意味でしょうか。","respondent":"宍戸施設整備課長","answer":"実は耐震工事は５年目ぐらいになるんですが、一番初期のころは、私どもの方も実勢価格について手探り状態でしたし、受ける工事会社の方も手探り状態だったようなこともございまして、当初は相当手探りで。","voiceIndex":42,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1828#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":14127,"voices":48}},{"id":"h21-20090722-14","meetingId":"h21-cm07","date":"2009年7月22日","dateIso":"2009-07-22","committee":"行財政改革特別委員会","time":"午後１時０２分～午後４時５１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5866#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":1795,"voices":11}},{"id":"h21-20090723-15","meetingId":"h21-cm07","date":"2009年7月23日","dateIso":"2009-07-23","committee":"環境対策特別委員会","time":"午後１時０３分～午後２時４０分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"地球温暖化対策に関することとして、「グリーン電力証書システム活用」","agenda":"地球温暖化対策に関することとして、「グリーン電力証書システム活用」","exchanges":[{"speaker":"稲川委員","kind":"質問","question":"発行しているところが日本自然エネルギー株式会社というところなんですが、これを発行するのはここだけなのかどうか、とりあえず教えてください。","respondent":"工藤環境課長","answer":"３点のお尋ねです。この証書ですけれども、個人でも販売はしていると聞いてあります。ただ現状として、購入先として、やはり自治体、企業等が多いです。","voiceIndex":9,"id":"exchange-001"},{"speaker":"稲川委員","kind":"意見","question":"いまいち理解できないんですけれども、では、その環境価値を買うわけですよね。もう１点は、例えばここに書いてあるしながわエコフェスティバルとか、太陽エネルギー見本市とか、第９回まちづくり事業展、第２６回品川区防災フェアの４件あるんですけれども、これは要するにここで使う電力というのは、普通に電気を使っているわけですよね。その辺、ちょっとおかしいかもしれないですよね。","respondent":"工藤環境課長","answer":"どこで発電するのかという部分、私どもも会社のほうに、どこでどういった形で発電したもののかを教えてほしいということで問い合わせたんですけれども、そこの部分までは詳しく答えることはできないということなんです。","voiceIndex":11,"id":"exchange-002"},{"speaker":"稲川委員","kind":"質問・要望","question":"グリーン電力証書システムというのは、イベントを通して多くの区民とか事業者に知らせると書いてあるんですけれども、それをしっかりやっていただきたいのと、もしこれが区民がこれを利用したとき、わかるようでわからないんですけれども、非常に不透明じゃないですか。でも電力は普通に東京電力が供給しているわけですから、そこでお金を払うわけですよね。その辺はどういうシステムで……。","respondent":"工藤環境課長","answer":"それとあともう一つは、区民の皆さんへの啓発という部分をしっかりしていくですけれども、私どももこのグリーン電力証書というのはなかなかなじみがないというか、なかなかご理解していただけないという部分がありますので。","voiceIndex":13,"id":"exchange-003"},{"speaker":"浅野委員","kind":"質問","question":"今回のグリーン電力証書システム、私も事前にいろいろ調べてはみたんですけれども、確かにシステムとしては非常に理解するのは難しいなとは思いましたけれども、考え方としては、結局二酸化炭素を削減するかわりにと言うと語弊があるかもしれませんけれども、グリーン電力証書を購入することによって、それにかわるものということで、国自体が、先ほど言われたとおり。","respondent":"工藤環境課長","answer":"この取り組みをあとどのようなイベントで広げていくことができるのかとか、またグリーン電力証書という部分じゃなくて、カーボンオフセットという考え方で品川区の事業全体の中で何かできないのかというのは、今後考えていきたいと考えております。","voiceIndex":15,"id":"exchange-004"},{"speaker":"浅野委員","kind":"質問・要望","question":"その数値に信憑性がある・ないというのはまた別の論議だと思います。そういう傾向をぜひとも、大田区のまねをしろとは言いませんけれども、そういう例もあるということも鑑みながら、品川区としての目標率の設定も含めた、地域推進計画の策定を含めた流れに持っていってもらいたいなと、再度これは要望しておきます。もしお考えとかがありましたら。","respondent":"工藤環境課長","answer":"品川区の地域推進計画の策定にあたりましては、基準年度をどのような形にするのかという部分、大変大きな問題だと思ってあります。私どもも策定にあたりましては、今後鋭意検討させていただきたいと考えています。","voiceIndex":17,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それを持つのはいいんだけれども、だけれども、これからのことを考えていくと、そこでほかの委員から質問があったように、品川区の地球温暖化対策という地域推進計画の中で、品川区独自、具体的にどういうふうにＣＯ２を削減していくかということを着実にしていかないと、いつまでもどこかの自治体のバイオマス発電を買っていくとか。","respondent":"工藤環境課長","answer":"ですから、自分の中でできるところまでやると。そしてそこでできない部分をさまざまな手法を使ってＣＯ２を相殺するというのが一つですので、グリーン電力購入というのはあくまでも一つの手法だと考えていただきたいと思ってあります。","voiceIndex":19,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"意見","question":"今日はこれでやめますけれども、私たちの思いとしては、今は確かに今のシステムを使って、グリーン電力なり、カーボンオフセットすることになる。だけれども、品川区独自の計画をつくるのであれば、そういう受動的な態度じゃなくて、品川区がより具体的な責任を持って、区内の事業者を含めて、さまざまな試みを利用していただいて、品川区独自でＣＯ２削減施策をつくっていく。よろしくお願いします。","respondent":"工藤環境課長","answer":"削減対策はさまざまな方法があろうかと思います。今後、品川区もそれに十分照らし合わせて、いろいろとさまざまな手法を検討してまいりたいと考えております。","voiceIndex":21,"id":"exchange-007"},{"speaker":"石田（慎）委員","kind":"質問","question":"つくるときに大分ＣＯ２がそこで発生されている部分があって、それを相殺しての相殺なのか、それともあくまで電力をつくった部分だけで相殺をしているのかなという、その部分をぜひともお答えいただければなと思います。","respondent":"工藤環境課長","answer":"何度も何度も循環するという、そういった考え方を用いて、要はエネルギーは出すんだけれども、バイオマス発電に関しても、いわゆるＣＯ２の発生はゼロだという概念にしているというのが、世界的な考え方です。","voiceIndex":23,"id":"exchange-008"},{"speaker":"石田（慎）委員","kind":"意見","question":"最終的にはそこそこ相殺しているということだと思うんですけれども、今の地球温暖化ってただ地球温暖化だけが先走ってしまって、それに対してさまざまな電力というのが実際に使われているわけですね。例えば風力発電にしても、風力発電をしているときには一切ＣＯ２がかかっていなくても、風力発電の物をつくる際はＣＯ２ができるわけですね。","respondent":"工藤環境課長","answer":"ただそこまで見ても、なかなか進まない。必ず２年、３年後には当然そこの部分以上の上回る効果ができるわけですから、そこの部分は切り離して考えようというのが今の考え方です。","voiceIndex":25,"id":"exchange-009"},{"speaker":"林委員","kind":"質問","question":"構成メンバーが１９名で、平成２１年度内に計画をつくるということを僕らは聞かされて、ああそうですか、平成２２年度から本格的にスタートするんだな、地球温暖化対策に対する品川区の考え方がスタートする。とりあえず試し打ちみたいに今年度やってみようと。平成２２年度の計画を今つくっている最中でしょう。それを平成２１年度にとりあえずやろうということは何なんですか。","respondent":"工藤環境課長","answer":"そのグリーン電力の購入ということで、区民の皆さんに啓発を図っていただいて、さまざまな形でそれが広がれば、いろいろと業務部門における削減や家庭一人ひとりの環境配慮という部分につながっていきますので。","voiceIndex":27,"id":"exchange-010"},{"speaker":"林委員","kind":"質問","question":"やっぱり試し打ちなんだ。年５回ぐらいやるんだと書いてあるけれども、そこ自体の推進計画というのは、区の行政に非常に大きい役割を持っているわけでしょう、その計画そのものが。そうすると、計画そのものが決まる前に、見切り発車と言ったら言葉はいけないかもわからないけれども、やれるところからやっていこうという感覚で、とりあえず３,０００kWhを買ってみようということじゃないんですか。","respondent":"工藤環境課長","answer":"決して私ども見切り発車というわけではございませんで、さまざまな事業の中で、今、現事業の中で環境に関する中でも、ＣＯ２の削減につながっているものはたくさん実施しています。","voiceIndex":29,"id":"exchange-011"},{"speaker":"林委員","kind":"確認","question":"実行計画でＣＯ２削減のために、いわゆる区立学校とか、品川荘、箱根荘、日光林間学園なんかも含めて、地球温暖化対策、ＣＯ２削減というものに区は取り組んでいく、こういう区の姿勢というのが打ち出されているのはわかる、今、課長がおっしゃったように。それでこの協議会がスタートしましたという報告を僕らにしてくれないと、メンバーが決まってスタートしたんですか、改めてこれだけ確認しておきます。","respondent":"工藤環境課長","answer":"品川区の今年度つくる地球温暖化対策地域推進協議会の計画の策定につきましては、前回報告したところです。５回を予定しておりまして、今、１回目が開催されたということで、２回目の開催は８月の終わりに予定しています。","voiceIndex":31,"id":"exchange-012"},{"speaker":"林委員","kind":"質問","question":"わかりました。では、品川区の全体的な方向性、計画についてはスタートしたばかりだということになって、今年度中に計画をつくり上げていく。改めて聞きます。そうすると、このイベントをやるという価値、目的、この４つのさっきもお話にでた３,０００kWhを買って消費をしたところで、１軒のお宅の１年分にも満たないということをやることの意義って何なんですか。","respondent":"久保田都市環境事業部長","answer":"というのは、今年度、確かに審議会を設置して、区全体の削減計画を策定しようと考えているわけですが、では、策定して終わった平成２２年度から即削減対策をできるかというと、なかなかそうはいかない。","voiceIndex":33,"id":"exchange-013"},{"speaker":"林委員","kind":"意見","question":"もう一つ。今週やるイベント、さっきパンフレットの説明を受けながら、ソーラーＦ１をつくるとか、子どもたちを対象にしたイベントというか、内容が盛り込まれているわけで、その案内が学校には行っていますか。","respondent":"工藤環境課長","answer":"私どもホームページ、あと区報のほうでお知らせしておりまして、各学校まで行っているかどうかというのは私のほうでは確認しておりませんけれども、区報等でやっております。学校には行っておりません。","voiceIndex":35,"id":"exchange-014"},{"speaker":"林委員","kind":"質問・要望","question":"平成１２年、１３年、１４年ごろに、一番子どもさんに伝えることが、資源回収とかごみを分別するということが親に伝わりやすい話だというのは、あなたはそのころ聞いていないかな。それを改めてこれから何かをやるときに、そういう考え方を忘れないようにしていただきたいというのをお願いしたいんだけれども、子どもたちの、それこそエネルギーってすごいものがあると思うんだけれども、どういう考えですか。","respondent":"工藤環境課長","answer":"ちょうど私どものほうも広報のほうで周知している中で、かなりの反響があるんじゃないかと思ってございまして、その中でなかなか人員が集まらないということになれば、各学校に周知というのを２段階で考えてございまして。","voiceIndex":37,"id":"exchange-015"},{"speaker":"林委員","kind":"質問","question":"その推進計画の協議会を開く中で、今の話は環境課として忘れないでください。電気とは切り離しという。電気なんでしょこれ、電気そのものじゃないの、環境付加価値という呼び方は違うけれども。そういうことを区民の人に知らせていって、また区民の人の考えを区に届けてくださいというやり方をしないと、新しい取り組みをしているんだという意義を自分たちで感じてやってほしい、やってくれますか。","respondent":"工藤環境課長","answer":"私どもも「切り離す」という言葉を別の言葉に言いかえて、例えば「環境価値を評価する」とか、何かそういったものに、より区民の方がわかりやすいような形の周知というものを、せっかく事業でやっている部分ですので、そういった部分は十分認識して。","voiceIndex":43,"id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"その辺の見解を一つ伺いたいのと、それからこの太陽エネルギー見本市、こういうイベントにグリーン電力証書システムを使うということで、ようやくさっきの説明でリンクされて理解したんですけれども、３,０００kWhとの関係がリンクされて、どういう意味なのかなというのが、これだけ読んでもわからなかったんですけれども、ようやくそれがわかりましたのでよかったんですけれども。","respondent":"工藤環境課長","answer":"２点目の件ですけれども、区民が啓発のレベルから行動のレベルに進むには、それが重要ではないかですけれども、まさに私どももそのように考えているです。","voiceIndex":45,"id":"exchange-017"},{"speaker":"南委員","kind":"意見","question":"外国、特にヨーロッパのこういう問題への取り組みというのは非常に進んでいると大分前から言われているんですけれども、私なんかはさまざまな資料程度の調査しかできていないんですけれども、ドイツでは風力とか、太陽光とか、バイオマスという活動というのは、国レベルですけれども、１２％ぐらい進んでいるということで。","respondent":"工藤環境課長","answer":"国がそのようなことを検討しているということで、今後十分注目していきたいと考えております。","voiceIndex":47,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこの仕組みのところを一つ教えていただきたいのと、あと自然エネルギーはグリーン証書うんぬんかんぬんで売り買いする、お金で済ませるものじゃないというのは当然で、自然エネルギーをもっと拡大していって、もっと活用していくというところを目指していかなくてはいけないと思うんですけれども、さっきヨーロッパの例も出たんですけれども。","respondent":"工藤環境課長","answer":"これを近いうちに１０％ぐらいに持っていこうという部分は、いろいろと目標を定めようという動きがあるというのは私どもつかまえているところです。品川区としましても、当然そのような動きの中で何ができるのかというのは、考えていかなければいけないと考えております。","voiceIndex":49,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう１点、太陽光の見本市のところなんですけれども、見本市を実際に新しいブースなんかで紹介をする、太陽エネルギーセミナーを開催するなどをやられると、区民の皆さんの関心がより啓発されるということにおいて、今日ご報告いただいた実績のところで、平成２１年度１７件の中で、完了届が出たところから助成を行っているというところで、平成２１年度は申込数１７というのが全部通るのかどうかというのと。","respondent":"柏原住宅担当課長","answer":"こういった形で件数も増えておりますので、いろいろ考えなくてはいけないところ、例えば国と都が平成２２年度まで２年間の助成制度ですので、そういったことも考えながら、予算の計上をどうするのか、これは検討していかなければいけないと考えています。","voiceIndex":51,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"共同住宅のところはぜひポイントにしていただきたいと思いますし、あと今日いただいた資料の裏面を見たら、２３区いろいろで、大田区はすごいなと思ったんですけれども、１kW当たり１０万円で上限が１００万円となっているんですが、品川区は工事の費用の１０％の助成で、よその区を見たらば発電量に対しての助成となっていて、その辺の考えの違いとか。","respondent":"柏原住宅担当課長","answer":"ただ他区のこのkWという考え方、おそらくですけれども、国と都が平成２１年度からこういった形の助成、キロワット当たり幾らという助成を始めましたので、それにならった形だろうと考えております。","voiceIndex":53,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ区民の皆さんが見本市などで関心を示されてやってみようかなというときに、利用しやすい制度に広がっていきますように、私たちもこれからも求めていきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6170#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":28173,"voices":59}},{"id":"h21-20090824-6","meetingId":"h21-cm08","date":"2009年8月24日","dateIso":"2009-08-24","committee":"区民委員会","time":"午後１時０２分～午後１時５７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１ 報告事項","agenda":"の１ 報告事項","exchanges":[{"speaker":"南副委員長","kind":"質問","question":"２番の未申請者への対応ということで、２万８,０００世帯とありましたけれども、下に書いてある数字は、合計しても１万世帯ぐらいですよね。そうすると、１万８,０００弱ぐらいですか。郵送返送分の調査はそれぞれやるということなんですけれども、１万８,０００世帯が宙に浮いたという言い方はあれなんですけれども、どういうふうに見るのかというのを教えてください。","respondent":"中山定額給付金担当課長","answer":"したがって、どういう理由で住まいでないところに住民登録があるのか、これはいろいろなご理由があるかと思いますが、特に住民登録の調査というよりは、単純なミスがないようにということで確認しておりますので、これについてはとにかく確認できないものについて。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南副委員長","kind":"意見","question":"とりあえず、この定額給付金についてはそういう執行実態だということがわかりましたけれども、いろいろなご事情で、それだけの方々がいらして、さらに発送してという区の方の事務的な事業を進める上での二重三重の取り組みというのは本当に大変なんだなと、改めて実感しました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-002"}]},{"id":"topic-02","title":"お元気ですかサービス（訪問ボランティア事業）の開始","agenda":"お元気ですかサービス（訪問ボランティア事業）の開始","exchanges":[{"speaker":"南副委員長","kind":"質問・要望","question":"希望した方に届けるわけですよね。この夕食配食サービスというのは一定程度のペースで夕食を宅配するわけですよね。訪問して安否を確認するという目的で「お元気ですかサービス」というのをやるんだろうと思うんですけれども、会話とか、ふれあいをより一層充実させるためにということで、新しいメニューとしてやるということですよね。","respondent":"秋山協働・国際担当課長","answer":"その辺を解決しながら、サービスの方を広げていきたいと考えているところです。","voiceIndex":12,"id":"exchange-003"},{"speaker":"南副委員長","kind":"質問・要望","question":"そういうところへの別な手立てはもちろんやっていらっしゃるわけですけれども、本当に町がみんな挙げてそういう状況を１件たりとも出さないという覚悟で取り組んでいく必要があると思いますので、ボランティアの確保ができないからなかなか広がらないよというふうなことのないように、積極的にこの問題に取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-004"}]},{"id":"topic-03","title":"地域と在住外国人の交流促進","agenda":"地域と在住外国人の交流促進","exchanges":[{"speaker":"南副委員長","kind":"質問・要望","question":"防災訓練を年１回やっているんですけど、思い出してみるとあまりお見かけしないような気がするんです。普段、高層ですから防災、不燃化になっていますのでそんなに心配ないのかもしれないんですけど、防災意識の高揚とか、地域コミュニティーという点では、特に地域コミュニティーのところでは大事かなと思うんです。その辺の考え方を教えてください。","respondent":"秋山協働・国際担当課長","answer":"今後も、地域で住んでいる方、特に八潮地区にインド人の方が多いということも聞いておりますので、そういったインド人の方たちとコミュニティーに対してどういう働きかけをしていくかというのも一つの課題だと認識しております。","voiceIndex":23,"id":"exchange-005"},{"speaker":"南副委員長","kind":"質問・要望","question":"だけど今度は外れてしまったので、国際交流担当という新しいセクションが入ったという関係では、当然、今のようなことになっているんだと思うんですけれども、今までの経過を見たときに、今までどういうふうに検討されてきたのかも含めて、もうちょっとお話ししていただければありがたいなという思いも含めて伺いました。","respondent":"宮地地域振興事業部長","answer":"今、防災の中で何が最も最新の情報で、どうやっていくかというのを常に情報収集しながら、それをまたフィードバックしていくところが、まさに協働・国際担当のセクションかと考えていますので、そういう意味では常にアンテナを張って、一緒に進めていきたいと考えています。","voiceIndex":25,"id":"exchange-006"},{"speaker":"南副委員長","kind":"質問・要望","question":"それで、国際交流担当と、それと同時に地域振興という点でも、八潮の外国人の方々の部分で見たときに、ほかの地域ももちろん大勢の外国人、いろいろな国の方々がいらっしゃるということですけど、自分の住んでいるところだけでちょっと言うと、地域振興という点と、それから国際交流という点と、あとは防災という点、この問題で言えば三つの課が共同して取り組んでいかなくちゃいけないと思っているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-007"},{"speaker":"三上委員","kind":"質問","question":"大崎第一地区ということで、先日行われた区民まつりでも課長のところがやられていたんですけれども、地域の中で国際交流的なことを行うということは大事なことだと思います。そちらの方との連携というのがどういうふうにとられているのか。むしろ、そういうふうにこれまで築いてきた財産を、地域としてどう活用するかというのは大事なことになってきますので、そういった点での考えを教えてください。","respondent":"秋山協働・国際担当課長","answer":"今後、国際友好協会は、日本語教室等いろいろな事業をやっておりますので、その中で外国人に対するＰＲもあわせて、私どもとしても連携を進めて、今後の国際交流を進めていきたいと考えております。","voiceIndex":28,"id":"exchange-008"},{"speaker":"三上委員","kind":"質問・要望","question":"国際交流としてはそれを広げていっていただきたいと思います。今、防災訓練というような話になってくると、大使館とか領事館だけということになると、そこの職員だけの参加ですから、区民とはほとんど関係がないという区内在住の外国人の方。「こういうことをやっています」という事業報告だけで終わるということにはしてもらいたくないなということで要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-009"}]},{"id":"topic-04","title":"近隣セキュリティシステム（３Ｇ）の開発状況","agenda":"近隣セキュリティシステム（３Ｇ）の開発状況","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"「まもるっち」で、今お話にもあったんですけれども、端末が変わることによって、センターシステムの方も今回大幅に変えられるということで、基本的な考え方なんですけれども、今までの２Ｇタイプから３Ｇに変わるということによって、協力者ですとか、保護者に対する連絡体制、いわゆる、何かことが起こったときに協力者とか保護者に行く体制とかに変更が生じるようなことは一切ないのかということと。","respondent":"矢部生活安全担当課長","answer":"ただし、当然３Ｇに伴う変更はありますので、これにつきましては、お知らせ等をもって各協力者の方にはご連絡をする予定です。","voiceIndex":35,"id":"exchange-010"}]},{"id":"topic-05","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"三上委員","kind":"質問","question":"経済対策ということをおっしゃったと思いますが、そこらあたりをもう少しご説明願いたい。空調工事ということですから、機械そのものをそっくり取りかえるという話になっているんですか。","respondent":"中山地域活動課長","answer":"昨年度の補正を含めまして、特に集会所関係で区内業者に発注できる工事はないかということで、老朽化している空調関係、若干規模の大きいものとそうでないものとありますけれども。","voiceIndex":45,"id":"exchange-011"},{"speaker":"南副委員長","kind":"確認","question":"緊急経済対策という点で、こういう部分でも区は積極的に区内業者に発注しているという計画を持ったんだということを改めて認識したので、そういう関係で、全庁的にどういう状況でこういう対策がとられているのかなというのを知りたくて伺ったんですけれども、そういう点で言えば、施設を休止させてやるということでこれだけは報告したんだという話でした。そこを確認したいんですけれども。","respondent":"中山地域活動課長","answer":"ただ、いずれにしましても、こういう工事外注について、例えば部内においても速やかに発注して、そういう工事についてもできる限り区内業者発注を進めながらやっていくということは、部の中でも徹底していますので。","voiceIndex":49,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2558#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":16407,"voices":52}},{"id":"h21-20090824-7","meetingId":"h21-cm08","date":"2009年8月24日","dateIso":"2009-08-24","committee":"厚生委員会","time":"午後１時０２分～午後２時４４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２１年度高齢者福祉週間行事","agenda":"平成２１年度高齢者福祉週間行事","exchanges":[{"speaker":"山内委員","kind":"質問","question":"ちょっと教えてください。白寿以上の方で男女の割合というんですか。今、予定人数が５１名、１０２名、８８名とありますが、男女の割合がわかれば、それだけ教えてください。","respondent":"永尾高齢者いきがい課長","answer":"白寿以上の方の男女の割合ですが、おおよそですけれども、男性１０人に対して女性が１１０人ぐらいの割合になっております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"山内委員","kind":"質問","question":"高齢者いきがい課長がおっしゃった、５名に対して１０６名というのは、それはどういう数字なんですか。","respondent":"永尾高齢者いきがい課長","answer":"７月１日現在の実績ですので、基準日によって多少ずれることはあるとは思うんですけれども、実際にお渡しするのは９月１５日現在の状況で判断をするようになります。","voiceIndex":11,"id":"exchange-002"},{"speaker":"山内委員","kind":"質問","question":"今年度ではなくて、昨年度の結果というか、その資料の中で、男女の関係はどんな感じだったのか。例えば百歳訪問の人数的なものと、それから、昨年の男女の割合はどんな感じなのか。多分、年が変わったからって、そんなに比率は変わらないと思うんですけれども、その辺の比率だけ数字で教えていただければ、何となく読めてくるかなと思うので、お願いします。","respondent":"永尾高齢者いきがい課長","answer":"昨年の新百歳の人数ですけれども、男性が４人で女性が４９人、百一歳以上ですと、男性５人で女性が７７人となっています。","voiceIndex":13,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"幾つかお伺いします。在宅介護者激励のつどいの予定人員２００名ということなんですけれども、選定基準がちょっとわからないので、教えていただきたいと思います。最後なんですが、２枚目の７６歳以上の低所得世帯と生活保護世帯の方に、敬老祝品の贈呈ということなんですが、低所得世帯とはどういう収入の方を言うのか、教えてください。","respondent":"冨岡高齢者福祉課長、永尾高齢者いきがい課長","answer":"在宅介護者激励のつどいの予定人員２００名の基準ですけれども、これにつきましては、対象者のところに書いてありますように、要介護１以上の高齢者を在宅で介護している方に、在宅介護支援センターを通じてご招待をする。長寿お祝い事業ですが、平成１０年度から開始しております。最高年齢の方ですけれども、１０７歳が、現在のところ最高年齢となっております。","voiceIndex":15,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"すみません、最初のところだけなんですが、在宅介護をされている方のうち、中でも２００名程度ということだったんですが、その２００名を選ぶ選定基準がちょっとわからなかったんです。それから、在宅介護をしている方というのは、在宅サービスを受けている方になるのか。ちょっとそこら辺もわからなかったので、教えてください。","respondent":"冨岡高齢者福祉課長、須藤委員長","answer":"在宅介護をされている方は、要介護１以上の方を在宅で介護されている方であって、その方自身はずっとヘルパーがきていたり。在宅介護をしている方にご案内するわけでしょう。それで、申し込んでもらって、多かったら抽選という形ですよね。そういう説明ですよね。申しわけありません、そのとおりです。","voiceIndex":18,"id":"exchange-005"},{"speaker":"飯沼副委員長","kind":"質問","question":"１点だけ。シルバーパスの一斉更新のところなんですけれども、税制改定があったときに、非課税から課税になった方への経過措置があったんですが、それが、今どういうふうになっているのか。それから、該当する人がどのぐらいいらっしゃるのか、わかったら教えてください。","respondent":"永尾高齢者いきがい課長","answer":"平成２０年度の経過措置を受けていた方につきましては、そのまま継続をして受けることができます。","voiceIndex":22,"id":"exchange-006"}]},{"id":"topic-02","title":"品川健康づくり宣言認証制度","agenda":"品川健康づくり宣言認証制度","exchanges":[{"speaker":"金野委員","kind":"提案","question":"実は、私も、去年の第３回定例会で、バランスのいい食事をと、昼間、やはり外食をとられるといった方も多い中、品川区の外食店の方に協力をいただいて、区民の食事、健康面をという提案をさせていただいたのが、こういう形になったのかなということで、非常に喜んでおります。そこら辺の意気込みも、もう少し教えていただきたいと思います。そこら辺の流れを教えてください。","respondent":"山岡健康課長","answer":"委員おっしゃったように、こういうことをやっているんだということがわからないと話にならないわけですから、今後、できるだけ広がるような周知の仕方を考えてまいりたいと思います。","voiceIndex":29,"id":"exchange-007"},{"speaker":"金野委員","kind":"意見","question":"いずれにしても、お一人お一人が自分の健康に意識を持つ、このやり方は非常に大事なことですし、これから、だれかに何かをしてもらおうというよりも、みずからしていくということでバックアップをしていただくこの取り組みを、私も応援をしていきたい、また取り組んでいきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"事業予算の点なんですが、出どころといいますか、補助金とかがあるのかどうかをお伺いしたい。ちょっと戻るんですが、同様の制度を実施している自治体の先行事例などがあったら、教えてください。","respondent":"山岡健康課長","answer":"補助金の関係ですけれども、特に考えておりませんで、金額的にはこういうふうなものをつくる経費ですので、私どものほうの財源でやりたいと思っています。","voiceIndex":32,"id":"exchange-009"},{"speaker":"安藤委員","kind":"意見","question":"これはちょっと意見なんですけれども、そういった中小零細商店のところでは、そういう取り組みをやるのであれば、費用を少し助成するとか、そういうことも、お金の使い方としては必要なことになってくるのかなと思いますので、ちょっと意見としてとどめておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-010"},{"speaker":"鈴木委員","kind":"確認","question":"１点だけ確認ですけれども、チェックシートをつくったのは大変だったと思うんですけれども、どういうふうに配っていくのか、そこがちょっとわからなかった。応募があったとして、例えば健康づくり推進委員が持って行くのか。要するに、縦割りでいくのか、地域振興事業部と関連を持ってやっていくんですよということなのか、その辺の考え方はどうなっているんでしょうか。","respondent":"山岡健康課長","answer":"必要に応じて、ほかの課とも連携をとりたいとは思っていますが、今現在の段階では、私どものところで、一応取り組んでいるです。","voiceIndex":35,"id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問","question":"ほんとうにやるんだったら、やっぱり品川区の中にこのステッカーをいっぱい出そうという思いがあるんだったら、担当部署だけで当面やっていきますという考えよりも、すぐに今の段階でも、ぽんと１課ではなくて、各部、各課を通じてやるべき話になっていくのではないのかと思います。そこら辺の取り組みに対する意識が、ちょっと私がわからないので、もう１回お聞きしたいんです。","respondent":"山岡健康課長","answer":"おっしゃるように、飲食店に限らず、いろいろな事業を展開して店舗、そういうところにこの制度をどう周知して、かかわっていただけるか、それを含めて、今のご意見を参考に、今後、関係するところと、つなげるところはつないでいきたいと考えております。","voiceIndex":37,"id":"exchange-012"},{"speaker":"飯沼副委員長","kind":"質問","question":"ほかにないというところでは、どの辺をベースにしてつくったのかとか、協議会の方たちが、この間、健康づくりで地域でいろいろ活動をしてくださっていますけれども、その辺の連携とか、話し合いがされてできたのかどうかという疑問が１点があるんです。十分に活用していただくという立場で、その辺の、今段階の連携と、これからどう広げていくのかというあたりを、もうちょっとお伺いしたいなと思います。","respondent":"山岡健康課長","answer":"ですから、今までのところは、中での連携でやってきた。ただ、これからは、先ほどの話にもありましたけれどもこれを広めていくためには、関係する外との連携をかなり強力に考えていかなければならないというのは、そのとおりだと考えております。","voiceIndex":39,"id":"exchange-013"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"やっぱりこれをみんなでやっていこうという意気込みを高めていくためには、魅力あるものなんだというアピールをたくさんしていただきたいと思いますので、今後に期待をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-014"}]},{"id":"topic-03","title":"女性特有のがん検診推進事業の実施","agenda":"女性特有のがん検診推進事業の実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"受診の実態についてお伺いしたいんですが、毎年、何名ぐらいなのか。それから、対象者の何％ぐらい検診を受けていらっしゃるのかというのをお伺いしたい。それから、区内で乳がん検診、子宮がん検診、それぞれ検診ができるところはどれぐらいあって、どんな感じなのかということを、ちょっとお伺いしたいんです。","respondent":"山岡健康課長","answer":"それ以外に、現在、二つの医療機関と契約を取り交わすところまでいっておりまして、９月からお願いできます。それから、検診車も、今、お願いしているところではない別の医療機関でお願いする予定になっております。それを全部入れれば、合計で１０機関になろうかと思います。","voiceIndex":47,"id":"exchange-015"},{"speaker":"山路委員","kind":"質問・要望","question":"今、品川区の受診率をお伺いしたんですけれども、これと逆に、実際の発生率のデータを、ちょっと聞かせていただきたいんです。新聞によりますと、全国的なものだと思うんですけれども、女性のがんが３人に１人というデータがあって、品川区、東京都では、どのぐらいの割合でがんの発生率があるのか。発生したら、２人に１人の割合で亡くなると、新聞に載っているんですよ。","respondent":"山岡健康課長","answer":"先ほど、乳がん検診の悪性の数字を申し上げましたけれども、子宮頸がん検診を９,８００人が受けられたんですけれども、私のほうは医学的な細かいことはわからないんですけれども、レベルは１から５までありまして、一番深刻な５という判定を受けた方が１人。","voiceIndex":49,"id":"exchange-016"},{"speaker":"山路委員","kind":"質問・要望","question":"今回、５歳刻みで受けられるという国の指定があるんですけれども、やっぱりこの年齢の方に一番多いということだと思うんですけれども、それでいいんですか。区も同じ状況ですか。そういう点について、どのように考えているのか、お聞かせいただきたいと思います。","respondent":"山岡健康課長","answer":"５歳刻みというのは、便宜上で、全員というのは難しいということで、５歳刻みにしたものと思います。子宮がんにつきましては、２０歳から４０歳までということで、今回、国のほうはやります。私どもも、２０歳からということなんですけれども、上はございません。","voiceIndex":51,"id":"exchange-017"},{"speaker":"山内委員","kind":"確認","question":"先ほど、乳がんだと思うんですが、重病の方が３名で、疑わしい人が５３名と。それから、陽性の方に対してのアフターケアというんですか、そういうのは非常に大事だと思うんです。例えば病院を紹介するとか、そういうところまでのケアというのは、品川区が指導するとか、医師会とのコミュニケーションがとれているのかという２点を、ちょっと確認させてください。","respondent":"山岡健康課長","answer":"重症というよりも、悪性という判断をされた方が３名、悪性の疑いが５３名ということですね。検査結果で、何らかの注意が必要だ、あるいは陽性といった場合には、委員からご質問があったように、できれば、その方に医療機関に直接お出でいただいて、検査結果を説明する。","voiceIndex":55,"id":"exchange-018"},{"speaker":"山内委員","kind":"質問","question":"例えば、検診車で受けられた方っていうのは、どうされるんですか。医療機関で受けた方は、多分、そこに行って、先生から直接、説明を受けることは可能だと思うんですが、検診車で受けられた方は、ここの病院に行ってくださいとか、そういう形で通知されるんですか。","respondent":"山岡健康課長","answer":"そこで、どこを受診していいかわからない場合はご紹介する。だから、事前にここというところまではやっていないんですけれども、リアクションというんでしょうか、どこか紹介してくれという話があれば、紹介するという形になっています。","voiceIndex":57,"id":"exchange-019"},{"speaker":"金野委員","kind":"質問・要望","question":"国の制度としてスタートするということですけれども、確認を２点、します。だとすると、子宮がん検診の対象の方はほとんど働き盛りで、２２カ所ある病院で、土曜日の検診はできる体制なんでしょうか。そこら辺を確認をさせていただきたい。それから、周知方法ですね、区統合掲示ポスターは、なぜ１月なのかということの確認をさせてください。","respondent":"山岡健康課長","answer":"開始日については、希望される方との関係もあるんですけれども、一応、考えているのは、最低でも月に５回はやっていただきたいと考えています。１回当たり、大体４５人から５０人ぐらい、朝から夕方までやっていただけるのではないかなと考えております。","voiceIndex":59,"id":"exchange-020"},{"speaker":"金野委員","kind":"提案","question":"検診車、増やしていただいて、ありがとうあります。健康課長のおっしゃるように、ちょうど時期を置いて中ほどというのは理解はできるんですが、であるならば、もう６カ月ですから、女性の多く集まる美容院だとか、あるいはスーパーだとか、そういったところにも掲示をするという方法も一つには大事なことであろうと思いますので、これは提案をします。","respondent":"山岡健康課長","answer":"提案ということで伺わせていただきましたけれども、実は、９月に入ったら早々に配付したいということで準備が進んでおりまして、中身の印刷につきましても、ほぼでき上がって、今は、先ほど申し上げた区分けの整理を始めている段階ですので。","voiceIndex":61,"id":"exchange-021"},{"speaker":"金野委員","kind":"意見","question":"もう準備が進んでいるということなので、わかりました。お知らせの広報も９月１日とおっしゃっていたので、どこか土曜日もということを、もう一歩押し出し、あるいはお知らせということが、タイミングがもし合うようであれば、ぜひお願いしたいという思いです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-022"},{"speaker":"鈴木委員","kind":"確認","question":"そうではなくて、病院が増えるということですか。なぜかというと、先ほど来、受診者数なんかの確認があったけれども、「しながわの福祉」の中にもう数字も出ているんですけれども、ここに病院名も出ているので、２機関増えるのだったら、もう既に９月に可能性があるんだったら、今、どこが入るか教えていただいてもいいのではないのかと思います。","respondent":"山岡健康課長","answer":"９月から２カ所増えるのは、検診車以外の普通の医療機関でございまして、一つは、東芝病院です。もう一つは、あじさい診療所という荏原中延にある診療所です。去年ぐらいに新しくできたものだと思います。その２カ所がやっていただけることで、話がまとまっております。","voiceIndex":64,"id":"exchange-023"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"前に新聞報道などで、子宮頸がんですか、若い世代で増えていると。その辺の傾向を教えていただきたい。この辺の中身がすごく重要で、今日、どんなものなのか知りたかったんですけれども、この辺の中身を皆さんに周知させるという立場でしっかり書かれていると、検診に行く気持ちももっと高まると思うので、ちょっとその辺も含めて、この手帳の中身も教えてほしい。","respondent":"山岡健康課長","answer":"今日、持ってくればよかったんですけれども、ただ、そういうふうな早期発見、早期治療につながるがんの啓発の中身になっているです。それから国の事業が今後どうなるのかということですけれども、これは私のほうでは何とも申し上げられません。","voiceIndex":66,"id":"exchange-024"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"体がんというのは、確率的にはそんなにないんですか。年齢的なものとしても、高いほうの方が多いんですかね。だから、ドクターがいらっしゃるので、もうちょっと私は中身を知りたいと思って質問したので、その中身も教えていただきたい。それから、マンモグラフィの検診車も増やしていただいたんですけれども、２年に１回ということですけれども、待てば希望者は全員受けられるんですか。","respondent":"山岡健康課長、太田品川区保健所荏原保健センター所長","answer":"今、１００％と言ってしまいますと、完全に全員できますと言ってしまうと、全員が希望された場合にどうするかという問題がありますので、希望された方は全員できるような形で、今、取り組んでおります、努力してまいります。体がんのほうは、子宮体部と言いまして、もっと奥のほうにできるがんでありまして、子宮内膜という、発生する細胞も違いますし、５０歳以上で閉経の影響等がありますので、ホルモンの影響を受けるがんであります。","voiceIndex":70,"id":"exchange-025"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"今の体がんのところは、定期的に受けなくても、不正性器出血とか、ちょっと異常だなと思ったときに受ければいいということですか。何回もお伺いしていますけれども、２年で何とか大丈夫なんだというご答弁をいただいているんですけれども、その辺はやっぱり、きちんとチェックをするという意味と、マンモグラフィも２年に１回で、もしも希望が通らなくて受けられないと丸々あいちゃうわけですよね。","respondent":"太田品川区保健所荏原保健センター所長、山岡健康課長","answer":"７０歳以上にマンモグラフィの検診を行っていないというのは、受け皿である検診機関が、４０歳以上に対してもまだ足りない状態であるということで、がん検診は、まずは壮年期の死亡を防ぐということが本来の目的でありますので。そうした場合は、該当する年ではないですけれども、次の年にできるだけ配慮したい。現にそういう方は、今年については配慮させていただいているところです。できるだけ２年に１回という形は守っていきたいとは考えております。","voiceIndex":73,"id":"exchange-026"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"金野委員","kind":"確認","question":"１点だけ確認させてください。これから先、秋以降、ほんとうに流行してくることを考えると、受験生のお母さん方が非常に心配しているという声を伺っております。まだまだその体制は具体的というところまでいってないでしょうけれども、国のほう、あるいは区としては、どのようなお考えでしょうか。","respondent":"中村品川区保健所長","answer":"供給、あるいは実際にどこの医療機関で接種をするかとか、そういうことも一元的に国が検討して決めると伺っておりますので、私どもとしては、国、あるいは東京都の実際の供給、あるいは接種の体制がわかりましたら、それに対して準備をしていきたいと考えています。","voiceIndex":83,"id":"exchange-027"},{"speaker":"飯沼副委員長","kind":"確認","question":"今、区立保育園３園、そして区立の学校ですまいるスクール関係で２校ということなんですが、何人確認をされているのかというのが１点。それから、登園自粛要請って、この辺がどういう中身か、わかったら教えてください。","respondent":"中村品川区保健所長","answer":"自粛要請は、私どもの管轄ではございませんが、なるべく休んでいただく、しかし、保護者の事情、仕事の関係とかいうことで、どうしてもやむを得ない場合につきましては、十分にそこの施設でのその後の感染もあり得るということを、ある意味でご納得いただいて、お預かりをすると。","voiceIndex":85,"id":"exchange-028"},{"speaker":"飯沼副委員長","kind":"質問","question":"医療機関の対応は、すみません、どうなっているのか、具体的に教えてください。","respondent":"中村品川区保健所長","answer":"かかりつけの医療機関がない場合につきましては、私どもで、東京都で把握しているご近所の医療機関というようなこと、あるいは、特に症状が重いということであれば、保健師等が対応して、実際の病院等を紹介するというような体制を組んでいるところです。","voiceIndex":87,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと１点。最近、路上生活者が増えているなという印象を持っていたんですが、ネットカフェ暮らしで生活保護の相談に区役所に行ったという３９歳、男性の方が、私どものところに相談に見えまして、対応についてお伺いしたいんです。このような路上生活者が見えた場合に、どのような対応をとっているのか、改めてお伺いしたいんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-030"},{"speaker":"飯沼副委員長","kind":"質問","question":"個別の案件というのは、個別では相談に行っているんですよ。そうではなくて、こういう場合の基本的なところはどうなのかという質問であると思って、私は聞いたので、基本的なところでお答えを。この人についてということではなくて、路上生活者が今、増えているのではないかという具体的な事例があったので、こういう場合はどういう対応するのかという質問であると受けとめました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"私も、本会議のほうで、路上生活者の生活保護の相談の対応などを質問していて、部長も答えているので、基本的な対応として、どのような対応をされているのかということをお伺いしたいと思ったのです。といいますのは、原則的には、緊急保護施設というのが、今、雇用状況も大変な中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"ただ、答えられる方がいらっしゃるじゃないですか。一般質問で質問しているので、課長…。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-033"},{"speaker":"鈴木委員","kind":"意見","question":"こういう案件は、その場ですぐにもむ話ではないと思うし、その他として、副委員長もいらっしゃるし、委員長に事前に話しておけばわかるけれども、次回、その答えをくださいとかいうのならわかるけれども、今日突然の話では。個別の話ではないというのは、私は理解しますけれども。は最終的には、委員長のご判断にお任せします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":99,"id":"exchange-034"},{"speaker":"山路委員","kind":"質問","question":"今日、質問して、次回に答えをもらうとか、委員長にお願いするとか、そういう形をとればいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"わかりました。では、その対応をどうしていますかということを質問させていただきたいので、次回、直接の担当者からお答えを伺えたらと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3244#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":29139,"voices":104}},{"id":"h21-20090824-8","meetingId":"h21-cm08","date":"2009年8月24日","dateIso":"2009-08-24","committee":"建設委員会","time":"午後１時０３分～午後２時１４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに(1)の区民住宅（あき家）入居予定者登録募集","agenda":"はじめに(1)の区民住宅（あき家）入居予定者登録募集","exchanges":[{"speaker":"武内委員","kind":"質問","question":"昨年ので結構なんですけれども、申し込みされた方の数と入れた方の数をお聞きしたいと思います。","respondent":"柏原住宅担当課長","answer":"昨年の９月の申し込みの際、申し込みの全住宅の総数、申し込みされた方ですが２２０件です。その後、登録していただいた方が１２４件でございまして、現在までのところ、入居の手続き中という方も含めまして、今２７件まで手続きをしています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"武内委員","kind":"質問","question":"そうすると、残りの２２０件申し込まれて登録したのは１２４、残りの１００件近い方はもう順番が決められているみたいで、それで入居は少し難しいかなという気がいたしました。それと２７件が入れたということなんですけれども、これは単純にあきが今のところ、年間大体この位出てくるということですか。","respondent":"柏原住宅担当課長","answer":"２２０件の方が申し込まれた後に登録の抽せんを行っております。それで、抽せんに該当された方が１２４件ということで、それ以外の約１００件近い方はもう抽せんから落ちてしまったです。それから、現在２７件ということで、大体あきの状況がそのぐらいの状況です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"藤原委員","kind":"意見","question":"報告事項で、区営、都営、区民の住宅が報告されましたが、なぜ都民住宅は報告事項の中に入ってこないのか。","respondent":"柏原住宅担当課長","answer":"都民住宅ですけれども、年に１回、都のほうからの依頼があるんですけれども、こちらのほうも問い合わせ等も全然ないわけではないんですが、ほとんど問い合わせ等がないという状況でございまして。","voiceIndex":9,"id":"exchange-003"},{"speaker":"藤原委員","kind":"意見","question":"都民住宅の申込書も区で扱っているのかということもわからないんですけれども、その辺、区で都営とか区営とかと同じようにやっているのかどうか。","respondent":"柏原住宅担当課長","answer":"都民住宅ですけれども、申込用紙等、区役所の本庁だけなんですけれども、書類等は届いておりますので、お申し出があったときには説明等も含めてお渡しは可能です。","voiceIndex":11,"id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"先ほど２７件が年間で入居をされたということなんですけれども、そもそも住み替え可能であるということで、この住宅は当初、打ち出されていますけれども、実際にファミーユそれぞれに建ち上がってきてから、住み替えをされた方というのはどれぐらいいるんでしょうか。","respondent":"柏原住宅担当課長","answer":"今年度、前回の申し込みから今現在ですけれども、住み替えをされた方は２件です。","voiceIndex":13,"id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"住み替えをする場合に、応募されて、通常こうやって募集される状況の中で取り扱いはされているんですかね。実際に希望されて、実質的には新しいところに移れないという方は実際にいらっしゃるのかどうか、それをちょっと。","respondent":"柏原住宅担当課長","answer":"応募された方をご希望のお部屋のところに合うかどうかということで、あきの状況があるか、そういったことを見ているんですけれども、なかなかご希望に沿ったところはあかないであるとかいうところで、住み替えができない方も中にはいらっしゃるです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、当然部屋の大きさで一定程度家賃が違いますけれども、子どもがいなくなって狭いところでもいいよということで住み替えを希望される方が、実質的にはなかなか、今までで２件だということですから、なかなかできない状況にあるということなんですかね。その別枠として、こういう一般的な募集とは別枠として今言われた各住み替えの案内を配布してという形でやられているのか。その辺も。","respondent":"柏原住宅担当課長","answer":"９月はこれは一般の方、住んでいない方の募集ですので、住み替えの方の場合は別枠といいますか、住んでいる方たちだけに募集の案内は出しておりますので、その中で、実際あきが出たときには住み替えの方たちを優先的に入れるような形では運用しているところではありますけれども。","voiceIndex":17,"id":"exchange-007"}]},{"id":"topic-02","title":"の大井町西地区再開発事業","agenda":"の大井町西地区再開発事業","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"１つは、最後に今、説明があった事業費のところなんです。補助金が２０％ぐらいということなんですけれども、従来事業そのもので私の覚えている範囲だとせいぜい多くて十七、八パーセントぐらいの補助金だったと思うんですけれども、２０％の補助金というのは、どういう理由をもってその２０％になっていくのかというのをお聞かせ願います。","respondent":"青木都市開発課長","answer":"今回のものについては、規模も小さくて住宅等、補助対象になる項目が施設建築物の中で割合多く占めておりますので、結果として２０％近くなっているということでご理解いただければと思います。","voiceIndex":23,"id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"今回の計画でのちょっと細かい部分になってしまうかもしれないですけれども、図面のところでお聞きしたいんですけれども、いただいた図面の中で区画道路２号ですか、ここで見て狭い路地というか、１.５メートルから２メートルぐらいの路地になっていますけれども、ここの道路、一番後ろの図面を見ますと、よく見えないんだけれども、６メートル道路ぐらいになりますよね。","respondent":"青木都市開発課長","answer":"道路として整備した際には区道認定する予定ですので、これは権利変換の中で新たな公共施設として６メートルの道路に整備できますけれども、建物自体については施工地区の外になっておりまして、買収とか移転とかというものの対象にはなってございません。","voiceIndex":25,"id":"exchange-009"},{"speaker":"菊地委員","kind":"質問","question":"それだと、現実には私道をこの計画の中に入れる上で、当然それぞれの権利者の皆さんの了解をとらなくてはならないんだと思うんですけれども、その辺は今現状はどうなっているんでしょう。七、八軒家屋が並んでいたと思うんですけれども、すべてがそれぞれに権利者なのかどうかはわかりませんけれども、その辺をもう少し教えていただけますか。","respondent":"青木都市開発課長","answer":"このこび、権利変換計画の認可に先立ちまして、土地調書、物件調書というものをそれぞれの財産を確定するために作成したものに署名、押印いただいているんですけれども、ご指摘をいただきました何軒かの方々、すべての方からその調書には署名、押印いただいておりますので。","voiceIndex":27,"id":"exchange-010"},{"speaker":"菊地委員","kind":"意見","question":"押印いただいたということが、それではその権利を組合に売りますよ、あるいは任せますよということイコールではないんですよね。その部分での権利をこの事業に協力しますよという形では、その法律の部分は今の話だと売りますよという話ではないように聞こえたんですけれども、そこをもう少しご説明いただけますか。","respondent":"青木都市開発課長","answer":"市街地再開発事業の仕組みの説明になってしまいますけれども、まず、市街地再開発をやっていい地区であるということにつきましては、事業を都市計画決定する段階でまず決めております。これは品川区の決定で平成１７年３月に決定しました。","voiceIndex":29,"id":"exchange-011"},{"speaker":"菊地委員","kind":"質問","question":"今回の計画の場合、まちの皆さんが商業施設を改めて見直して、盛り上げていきたい。だから、現時点で、それじゃあ、その権利変換には応じませんよという方たちがいらっしゃるとすれば、事業そのものは進んでいくわけですから、極端な話、強制執行等もあり得るんだよという話なのか。そこをちょっと教えていただけますか。","respondent":"青木都市開発課長","answer":"権利変換計画等については認可されておりますので、なおかつ都市計画事業ということで行われる事業ですので、いわゆる収用法に準じた扱いが適用される事業になってあります。","voiceIndex":31,"id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"やはり、必要な道路をつくるとかという話とはまた違って、実際にまちの皆さんが同意をして協力して新たな建物をつくるだとかという話ですから、やはりしっかりと最後まで皆さんが同意できる中身というものをつくり上げるという必要性があるんだと思うんですね。住民の皆さんと最後まで話して煮詰めるということをぜひやっていっていただきたいというふうに思いますので、それだけ言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-013"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"２点教えていただきたいんです。この地域の中に借家人さんはいらしたのかどうか。借家人さんがいらした場合はどのようにしたらいいのかということを教えていただきたいと思います。それとも、新たに何か新しいテナントが入ってくるという形になるのか。","respondent":"青木都市開発課長","answer":"こちら、ちょっと細かい図面はまだつけていなくて大変申しわけないんですが、一、二階部分に商業施設を入居する予定としてございまして、基本的には権利者の方々で営業継続をする方々のお店を確保しつつ、それとは別に比較的大きな規模の商業床を設置しまして。","voiceIndex":34,"id":"exchange-014"},{"speaker":"阿部副委員長","kind":"質問","question":"前半の借家人という方なんですけれども、４７人ほどが借家人ということで、この方々はどんな権利が確定して、ここの方々はどうなっているんですか。","respondent":"青木都市開発課長","answer":"ご説明が不足しておりました。借家人の方々は、権利変換の前におおむねほとんどの方が地区外に転出するという形で補償金を受け取って転出する予定です。","voiceIndex":36,"id":"exchange-015"}]},{"id":"topic-03","title":"の第９回（平成２１年度）まちづくり事業展の開催","agenda":"の第９回（平成２１年度）まちづくり事業展の開催","exchanges":[{"speaker":"武内委員","kind":"質問","question":"というのは、子どもたちが例の子どもたちが企画する公園というのが今年度中に出来ると思うんですが。それとは関係ないんですか。何かそれと関連しているのかどうか。","respondent":"藤橋都市整備下水道課長","answer":"ご質問のあった公園の今後の検討についてですけれども、今年度、子どもたちからのアイデアをもとにした公園の実現性について、どういったところにどういった公園ができるのか。それについて今年度検討するという状況になっております。","voiceIndex":44,"id":"exchange-016"},{"speaker":"武内委員","kind":"質問","question":"そうすると、子どもたちの夢というか発想に伴うような形というよりも、現実的に活用できそうなものが展示されているという形で、また、今後の公園づくりにも役立つようなものだという理解でよろしいでしょうか。","respondent":"松代都市計画課長","answer":"子どもの小さなアイデア集というような形にしておりますので、そういったものもぜひご覧いただきたいと考えています。","voiceIndex":48,"id":"exchange-017"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"どうしても海岸のほうだけで見ていくとあまり目につかないものですから、どの辺で実際に水害が現状で起きていて、どういう対策をとろうとしているのか。その辺をもう少し教えていただけませんでしょうか。","respondent":"藤橋都市整備下水道課長","answer":"そういった施設につきましては、民間開発事業者はもとより、個人のお宅様のご理解を得て設置を増やしていきたい、可能な限り連携を増やしていきたい。","voiceIndex":54,"id":"exchange-018"},{"speaker":"菊地委員","kind":"質問・要望","question":"新しい幹線をつくられて、それで低減をさせていくというところではわかるんだけれども、最初の説明にあった家屋ですかね、家庭での対策ということで、実質的には家庭での対策というのを進めても、水利上の問題で言えば大きな話ではないのかなと思うんですけれども、実質的に目標とするところにまで到達するために、浸透ますをつくったり何とかして家庭でやっていったときに。","respondent":"藤橋都市整備下水道課長","answer":"それと、あと各ご家庭での浸透施設の設置等がございまして、そうやって進めてきたわけですけれども、平成３年に計画を策定してから平成２０年、１８年間で５７％に達したという状況でございまして、目標としております２０２５年、平成３７年になりますが、これまでには１６年。","voiceIndex":56,"id":"exchange-019"},{"speaker":"菊地委員","kind":"質問・要望","question":"一般のご家庭だと、現実的には指導があってもなかなか設置できないのかなというところは、都心部での土地の状況ですから、ただ、１００％に達するためには、そこもなくちゃいけないよという話ですよね、今の話ですと。ちょっとその辺の数字、１００％にするために一般の方たちに求める数値というのは一体どの辺にあるのか。どの辺を考えているのかというのを教えていただきたい。","respondent":"藤橋都市整備下水道課長","answer":"先ほどお話ししました平成３年の策定につきましては、私どもの区の計画では公共施設と大規模民間施設、道路等の道路施設、これに設置することを目標とした計画でございまして、それの対策量が１５万３,２００立米ということで。","voiceIndex":58,"id":"exchange-020"},{"speaker":"武内委員","kind":"質問","question":"３ページの表で、平成１１年だと思うんですけれども、これは１００ミリを超えたことはなかったんでしょうかね。何か１年で２回ぐらい、１００ミリを超えたようなことがあったような気がするんですけれども。はかり方が違うんですかね。","respondent":"藤橋都市整備下水道課長","answer":"お尋ねの平成１１年８月の降雨ですが、ここでお示ししていますのは東京都の水害記録に載っている品川区のデータで時間最大で７７ミリとなっています。委員もご指摘のとおり、その当時、高浜というところでは１時間１１５ミリを確かに観測しています。","voiceIndex":60,"id":"exchange-021"},{"speaker":"武内委員","kind":"質問・要望","question":"５ページの整備中の施設の表ですけれども、これは品川区内で行っている工事というか事業なんですけどね、ここでやはり東京都の課長さんもいらっしゃるので、特に第二立会川幹線でやっぱり豪雨のときなんか相当気になるので、なかなかこういうのが同じ表の中に整備状況とかあまり報告が、東京都がやっているからということなんでしょうけれども、載ってこないので。","respondent":"藤橋都市整備下水道課長","answer":"しかしながら、まだ現在、その最上流部のほうでの水を取り込む工事を今年度下水道局が実施している状況でございまして、今年度の末、平成２２年２月に暫定的にその施設は完了するということで、水が取り込めるような状況になるというふうに聞いています。","voiceIndex":64,"id":"exchange-022"},{"speaker":"武内委員","kind":"質問","question":"そうすると、平成２２年度、来年の２月ごろに、一応予定では暫定的に完了して中延までつながるということ、そうすると、それは最終的にポンプ所のほうにつながないと流れないけれども、暫定的に立会川幹線のほうで、たまってきたものをそちらに一時流せる。それによって少し浸水被害が軽減できるという考えでいいんでしょうか。","respondent":"藤橋都市整備下水道課長","answer":"その全体的な貯留の容量ですが、約３万５,０００トンほど水がためられる構造になるというふうに伺っておりまして、ためた水につきましては、当然満水になれば既設の下水道管に排水して流れていくということになります。","voiceIndex":66,"id":"exchange-023"},{"speaker":"武内委員","kind":"意見","question":"そうすると、最近は少ないと思うんですけれども、あの辺のところで今まで下水道から逆流して浸水になったようなものが、これが暫定的にでも地域の浸水を防ぐようになれば、被害が軽減できるというふうに考えてよろしいですね。","respondent":"藤橋都市整備下水道課長","answer":"効果ですが、第二立会川幹線には３万立米以上の水をためるということで、これは地域にとってはかなりの浸水被害の軽減につながるというふうに考えます。","voiceIndex":68,"id":"exchange-024"},{"speaker":"武内委員","kind":"質問・要望","question":"先ほどおっしゃったように、そういうのもご報告をいただくなり、また、できれば、東京都の方から地域の方にお知らせをしていただくなり、せっかくやっている工事がそれを機会としてある程度効果が見込めるのであれば、そういうご報告をやっていただくようなタイミングを作っていただきたいという要望をします。","respondent":"伊藤委員長","answer":"今のお話の続きで、第二立会川幹線の関連工事の視察を当委員会で今予定をしております。実際、現場に行って、今、武内委員がおっしゃるように進捗状況であるとか、今後の計画であるとか、そういうことを現場で事務所から聞くようなことを予定しております。","voiceIndex":70,"id":"exchange-025"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"４ページなんですけれども、この真ん中の図で、すずかけ歩道橋を境に、中小河川改修事業というのと高潮対策事業と分かれているんですけれども、これは何か流域によって危険の種類が変わってくるとか、何かそういうことを含んでこういうふうに分かれているんですか。その水防本部のコアなメンバーの人たちの皆さん、この６キロ圏内に住んでいらっしゃるということなんでしょうか。３点教えてください。","respondent":"藤橋都市整備下水道課長、中山防災課長","answer":"１点目ですけれども、４ページ目の図の４ですが、高潮対策事業区間と中小河川改修事業区間を分けてありますのは、いわゆる下流の高潮対策事業区間におきましては。今、１２１名と申し上げましたのは、管理職を抜いた数でございまして、管理職を入れますと係長も含めまして６キロメートル圏内１３９名います。","voiceIndex":72,"id":"exchange-026"},{"speaker":"阿部副委員長","kind":"質問","question":"この１８人を考えれば、防災本部をきちんと回していくために必要な管理職の方というのは、この１８名の中に入っているというふうに理解してよろしいでしょうか。それと、先ほども答弁がありましたように、高潮対策のほうが洪水対策よりもさらに基準が高いので、高潮対策に適合していれば洪水のほうでも大丈夫なんだという理解でよろしいんでしょうか。","respondent":"中山防災課長、藤橋都市整備下水道課長","answer":"先ほど管理職１８名ということですが、情報部、対策部等とありますけれども、ここの部長クラス、副部長クラスということで、指示を出す、統括する者として位置づけてあります。したがいまして、下流まで、ここで橋の下が１時間５０ミリの雨が降ると当たってしまうような状況になりますので、下流側までは今現在のところ水が、ネックになってそこであふれてしまうというような状況になっています。","voiceIndex":75,"id":"exchange-027"},{"speaker":"阿部副委員長","kind":"質問","question":"それに対しては何か今後の対策みたいなものは考えていらっしゃるんですか。それとも、もう構造上仕方ないんでしょうか。","respondent":"藤橋都市整備下水道課長、伊藤委員長","answer":"先ほど東京都の豪雨対策の取り組み状況を東京都のほうでは今、目黒川流域豪雨対策計画の策定作業を進めているという説明をさせていただきましたけれども、この中でいわゆる河川の整備。ほかにないようですので、本件を終了いたします。なお、所管事務調査については今後も報告事項等の状況を見ながら、正副で調整させていただきまして、可能な限り調査・研究していきたいと考えておりますので、よろしくお願いいたします。","voiceIndex":78,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3954#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":22138,"voices":86}},{"id":"h21-20090824-9","meetingId":"h21-cm08","date":"2009年8月24日","dateIso":"2009-08-24","committee":"文教委員会","time":"午後１時０３分～午後３時３９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それがちょっとわからなかったのでちょっと教えていただきたいんですけれども、つまり学校選択制を実施して１０年ぐらいたちますけれども、選択できると言いながら、今回はすべての小・中学校で受入枠の上限を定めるわけですね。その制度じゃなくて手続と言えばいいんですかね。手続の意義が何なのかよくわからなかったので、もう少し教えていただけますか。","respondent":"富田学務課長","answer":"ちなみに他の学校選択を実施している自治体につきましては、おおむねすべての学校についてこういった受入学級数等については公表しております。","voiceIndex":7,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこの理由がよくわからなくて、保護者の人がわかりにくいという話があったんですけれども、その辺がよくわからないのでもうちょっと教えていただきたいのと、あと具体的に、例えばこの数字を見ていますと、杜松小学校では受入人数が３５人という上限がありますけれども、初めから単学級に定めている理由というのは何なのか。","respondent":"富田学務課長","answer":"そこのところで学級数の予定が単学級を予定しているということもあり、大間窪小学校について２学級、杜松小学校について１学級ということで受入学級数を設定したものです。","voiceIndex":9,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"杜松小学校の説明がありましたけれども、同じように清水台小学校が単学級に下がるというのは、つまりは複数の学級を認めないのはなぜなのか、教えていただきたい。同じような質問なんですけれども、小学校と中学校で、小学校だから１、２、３、４クラスの学校を初めから定める。中学校では２、３、４、５クラスの学校を初めから定める。","respondent":"富田学務課長","answer":"清水台小学校につきましては、学校施設の状況もありますし、今後の耐震化工事の予定等々を勘案し１学級としたものです。","voiceIndex":11,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"どうしてもよくわからないのが、人口のことだったり、施設の状況だったり、これはある意味あらかじめわかっていることで、今までもそういう条件の中で進めてきたわけですよね。その中で学校選択制をやり、また今回上限を定めるというこの理由がどうもよくわからないんですね。もう１度ご説明いただきたいと思います。わかるようにもう１度ご説明いただけますか。","respondent":"富田学務課長","answer":"通学区域で希望するお子さんがその定める学校に入ることができるというのがまず大前提でございまして、これが公立学校の基本であると考えております。そのほかに学校施設には必ずさまざまなハード面での施設の制約というものが当然ながらあります。","voiceIndex":13,"id":"exchange-004"},{"speaker":"井上委員","kind":"意見","question":"１点目は、平成２１年度から平成２２年度に学級数が増えたところというのは、どういう理由で増やしているのか。転校してきた人たち用の枠、今回４０人学級で３５人設定だと思うんですけれども、平成２１年度の場合にはどのくらいの人が入ってきて埋まった状態になったのかというのはわかりますか。","respondent":"富田学務課長","answer":"１点目ですが、平成２１年度の実績というのはあくまでも実際に入学した数ということでございまして、平成２２年度の受入予定数というのは、受入することが可能な学級数ですので、必ずしもこの学級数が平成２２年度の実際の学級数となるとは。","voiceIndex":15,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"１つ、ここのところで受入可能数が３,０８５名ということなっていますが、まだこれから出入りがあるかと思いますけれども、どのくらいの就学前のお子さんたちがいるのかという状況を教えてください。","respondent":"富田学務課長","answer":"来年の入学予定者は、今年の４月１日現在の住民登録の数ですと、２,３３６名が小学校、中学校が２,０３１名が住民登録の数です。","voiceIndex":17,"id":"exchange-006"},{"speaker":"西本委員","kind":"確認","question":"幾つか確認させてください。それは表現の仕方を変えたほうがいいんじゃないかと思いますので、そのご見解と、それから、ブロック外の考え方というのが今までと同じなのかということ、それから、区外の方たちの受入についてはどういう考えをお持ちになって、学校選択の申し込みの際に対応しているのかということを聞きたいと思います。","respondent":"富田学務課長","answer":"学校案内等々の作成にあたり、表現については十分検討してまいりますが、保護者の案内については、昨年度もこういった数はあまり載せていなかったと考えています。","voiceIndex":19,"id":"exchange-007"},{"speaker":"西本委員","kind":"意見","question":"昨年同様というのがよくわからないんですけれども、ブロック外のものについては考え方がわかっているんですけれども、ブロックの中での抽選をしてという形で、ブロック外の人たちは抽選に入れないという理解でいいんですね。","respondent":"富田学務課長","answer":"委員ご指摘のとおりで、ブロック内で抽選をし、残余の部分について、可能であれば指定校変更の条件を判断しということになります。","voiceIndex":21,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"もう１つ、区外のほうですけれども、いろいろな事情があるのはわかっているんですね。しかしながら、教育委員会として区外というのを基本的に受け入れないよということをどこまではっきり明記するかということだと思うんですけれども、どういうことをお考えなんでしょうか。","respondent":"富田学務課長","answer":"区域外就学の基準につきましては、昨年９月でしたか、改定した内容を今回もそのまま適用してまいりますので、現在ある区域外就学の基準に照らし判断してまいります。","voiceIndex":23,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"兄弟関係とかいろいろあって。ある程度の経過措置という部分も出てくると思うんですが、品川区の考え方というのはそれなりに言っていかないと周知できないと思うので、品川区の考えとしては品川区外は基本的に受け入れられないというところまで、はっきりとしていくという形のほうがクリアでいいと思うんですが、どうなんでしょうか。","respondent":"富田学務課長","answer":"原則的には、委員おっしゃるように、通学区域以外の特段の基準に当てはまる理由がある場合に可としていくです。","voiceIndex":25,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな理由があると思うんですよ。と思うんですよね。だから、そこは品川区としては考えをきちっとしていただきたい。そこまでするなと言っているわけではないんですけれども、ある程度品川区としての考え方をはっきりしないと、品川区の中でも細かいところが出てきてしまうので、はっきりしていただいたほうがいいんじゃないでしょうかということを言っているんですが、いかがでしょうか。","respondent":"富田学務課長","answer":"ご指摘いただきましたように、基本的には区外からの就学は認めないということで取り組んでまいります。","voiceIndex":27,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"教科書採択の事務のことで伺いたいんですけれども、毎年教科書を採択する際、教育委員会の定例会に大勢の方が傍聴を希望しておりますけれども、抽選という格好で傍聴が確保されていないという問題が毎年続いていると思うんですね。伺いたいのは、教育委員会として定例会への傍聴を、とりわけこの教科書採択への傍聴の目的というのはどのように考えているのか、ご説明いただけますか。","respondent":"田村庶務課長","answer":"ですから、原則公開の上、常設の委員会で議論することが必要だろうということで、案件により傍聴人数を想定して会場を設定することも現実的には不可能ということで、通常どおり、傍聴人員１０名ということで、それを超えた場合には抽選という形で公開しているものです。","voiceIndex":34,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"お伺いしたかったのは、教育委員会自身が定例会への傍聴についてどういう目的として考えているのか、そこを伺いたいんですけれども。","respondent":"田村庶務課長","answer":"教育委員会という行政機関は、会議の運営についても先ほどの規則を定めてありますので、別に教育委員会以外に事務局としての考え方というより、先ほど申し上げたとおり、教育委員会の中の運営について会議規則に定めて、先ほど１０人までという傍聴人数も定めておりますので。","voiceIndex":36,"id":"exchange-013"},{"speaker":"中塚委員","kind":"意見","question":"会議規則にあるという説明ですけれども、なぜ傍聴を会議規則の中で位置付けているのか、傍聴の目的をどう理解しているのか、そこを聞いているんですけれども。","respondent":"田村庶務課長","answer":"ご存じのとおり、委員会を公開でやっていますが、通常だと公開の、人がいない場合、あるいはいても数人の場合というのがほとんどでございまして、やはり審議をなす中で、一般の公開をしたときに。","voiceIndex":38,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどからの答弁ですと、教育委員会自身がなぜ定例会を公開し傍聴を定めているのかという、その傍聴の目的の説明が私はないなと思うんですね。同じような意味かもしれませんけれども、公正な審議を保証する。決まりがそうだからやっているだけという後ろ向きの話なのか、いやいや、どうぞ大勢の方に来てください。どのように傍聴を位置づけているのか、そこの説明がないのでご説明いただきたいと思います。","respondent":"田村庶務課長","answer":"私の説明が不十分だったかもしれないですが、教育委員会自体は人事案件を除いて公開、いわゆる審議自体を公開という大原則があります。","voiceIndex":40,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"公開すればいいというものじゃない。そこはしっかりご説明いただきたいと思います。ですから、この定例会の場合には、事務的なことはわからないんですけれども、あらかじめ参加者の名簿を書いて、ガラガラという抽選を用意して、あらかじめ用意するわけですから、定数を超えることはあらかじめ予測しているわけですよね。なぜそういう対応ができないのか、あわせてご説明いただけますか。","respondent":"田村庶務課長","answer":"先ほど来答弁しているんですが、人事案件以外は公開するという大前提で教育委員会を進めていますので、それと傍聴の人数を定めるのとは、ハード的なスペースの問題で１０人と定めざるを得ないということですので、それが公開に反するとか。","voiceIndex":42,"id":"exchange-016"},{"speaker":"井上委員","kind":"提案","question":"前回そういった私たちが提案をしたときに、他区の事例も調査をしたときに、その都度そういったときには対応するということがあるわけで、常設の委員会だからそこでやるのが定例会として当たり前だというような門前払いということではよくないと思っていますので、規則を変更しても、事務局として先ほど特別な見解はないということでしたけれども。","respondent":"市川教育次長","answer":"これは仮に今、議論されている教科書採択の案件を通しましても、私は４年前、あるいはその前の年、これまで小学校、中学校の教科書採択の審議に携わってまいりましたけれども、すべての教科書採択の案件に傍聴者が殺到するか、定員１０人に対して。","voiceIndex":44,"id":"exchange-017"},{"speaker":"浅野委員","kind":"質問","question":"教科書については、学校教育という観点から大きな役割といいましょうか、重要なことだと思うんですけれども、たまに新聞で教科書云々という話が出たりして、私も興味のあることなんですが、例えば私も今まで教科書採択とか、そういうことについてはほとんど不慣れなもので、基本的なことをお伺いしたいんですが、結構な発行者があるかと思うんですね、種類としまして。","respondent":"冠木指導課長","answer":"品川区の教科書の採択につきましては、品川区立小・中学校使用教科用図書採択要綱というのを定めてございまして、その中で教科用図書の調査検討委員会、それから調査研究会、これは学識経験者や保護者、それから学校の先生方、校長先生方等を含む会ですが。","voiceIndex":46,"id":"exchange-018"},{"speaker":"浅野委員","kind":"質問","question":"その中で期間としてどのくらいかかるんですか。多分教科ごとですから並行して走ると思うんですけれども、ほぼ１年がかりなのか、そこら辺のことについて。","respondent":"冠木指導課長","answer":"今年の例ですと、教科用図書の見本ができたのは５月の中旬になってございましたので、約３カ月ほどかけて採択となっています。","voiceIndex":48,"id":"exchange-019"},{"speaker":"井上委員","kind":"意見","question":"今、通常学級の教科書を原則使用するということがあって、学習効果が認められないときにこういうものを使うことができるということだったと思うんですが、今、現状でどの程度の通常学級の教科書が使用されて、継続というのもあるわけなので、こちらも使われていると思うんですけれども、現状はどのようになっているのかご説明ください。","respondent":"冠木指導課長","answer":"ですので、子どもたちの状況、そして教科の特性などに合わせて、今日ご案内のような、附則９条本といっておりますけれども、この教科書を使うということも出てまいります。","voiceIndex":54,"id":"exchange-020"},{"speaker":"井上委員","kind":"質問","question":"ということは、特別支援学級の中では幾つかの教科書をその子どもに合わせて提供して授業をされていると考えていいんですか。","respondent":"冠木指導課長","answer":"特別支援学級については、在籍するお子さんの状況に合わせて、学級の担任の先生方が、中から適したものを選んで使っていただいているという状況です。","voiceIndex":56,"id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"じゃ、その判断は学校ごとということなのか、基本的な考え方として、そういった通常の教科書を使って、会話とか、特別支援学級の子どもと通常の学級と交流があるわけですから、そういう中で共通の話題になったり、子ども同士のそういうことはないと私は考えられないので、そういう意味では、原則こちらを中心にという考え方を教育委員会は持っているのか。","respondent":"冠木指導課長","answer":"これはいずれにいたしましても、在籍するお子さんの状況によるかと思いますので、ですので、そのお子さんによって通常の学級との交流の度合いも違いますし、教科の学習の進め方も違いますので、学校の先生方が判断をしていただいている部分がかなり大きいと思ってあります。","voiceIndex":58,"id":"exchange-022"},{"speaker":"西本委員","kind":"確認","question":"１点だけ確認したいんですが、先ほどから議題に上がっていると思うんですけれども、子どもさんによって状況が違うと思うんですね。それとも全く一教師のそういうものに任せているという現状なのか、品川区の先生方からの情報交換も必要だと思うし、学習も必要だと思いますし、そこがどのように仕組みになっているんでしょうか。","respondent":"冠木指導課長","answer":"基準というところはなかなか、言葉は基準というひとつの言葉なんですけれども、とらえようがいろいろと学校によっても違ってこようかなと思ってありますが、いずれにいたしましても、子どもたちの学びの状況というのは非常に多様ですので。","voiceIndex":60,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"そうすると、この情報交換というのは、幼稚園、保育園のときがどういう状況だったのか、生活も含めて。その情報が小学校に行き、小学校の中でこういうことだからこういう教材を使ってこういうふうになってきた。それを今度中学校になっていくときのつながりというのは一連の流れになっているものなので、これから推進していくとなると、どういう方向なんでしょうか。","respondent":"冠木指導課長","answer":"委員のおっしゃるとおり、特別支援学級においても、小中一貫教育の理念というのは当然のことでございまして、お話のようなところがどの学校にも進んでいくように私たちも推進していくです。","voiceIndex":62,"id":"exchange-024"},{"speaker":"林副委員長","kind":"質問","question":"ちょっといいですか。終わっていいです。終わっていいんだけれども、報告事項３つ終わったところで、教育委員会が今日持ってきているヘルメットは何のために持ってきているのか。委員会の中にヘルメットを持ち込むというのは委員長に断ってあるのか、その辺を最初にだれかが説明しないと困るんだよね。委員会のデスクにヘルメットが載っているというのは異様な光景だから、それだけちょっと教えてくれますか。","respondent":"田村庶務課長","answer":"今日、視察を２時から予定しているので、委員会が２時に休憩に入ったときに、すぐにバスに乗り込めるように持ってきているだけでして、委員のほうの分は区議会事務局で準備していて、理事者側のほうは今日持参して、そのまま現地に行けるようにという形で。","voiceIndex":66,"id":"exchange-025"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"井上委員","kind":"質問","question":"ちょっと保育園のほうだけ状況を伺いたいんですけれども、病気で保育園が休園とか、年齢によってというところで、保護者のほうからは困惑の声とかがあるんじゃないかと思うんですけれども、対応とか、できる人はいいですけれども、できなかった人もいるだろうと思うんですけれども、相談とか、そういったところの、区が把握している範囲で結構ですので、何かあれば。","respondent":"吉岡保育課長","answer":"保護者の方のほうはこちらの受け止め方ですけれども、今のところ夏休みで、もともとお休みをとって、ご家族のいろいろご予定があるようでありますけれども、登園の自粛をお願いしますと、かなりの方がお休みをしていただいております。","voiceIndex":75,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"どんなふうに聞いたらいいかなというのが悩ましいんですけれども、小学校と保育園の新型インフルエンザについてですけれども、学校名だったり保育園名だったり、公表するしない、また保護者には教えるけれども、マスコミ対応についてはどうなのかとか、その辺というのはどういう対応をしているのかというのを教えてもらいたいと思います。","respondent":"吉岡保育課長、田村庶務課長","answer":"ただ出ましたみたいなことを広く公表するようなこともしておりませんけれども、考え方としてはそういうことです。ですから、今後も基本的にはそのような考え方で、あとほかの小・中学校にも影響するので、当然指導課長のほうで、こういう学校でこういう状況なので、周知して手洗いの励行。","voiceIndex":77,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4678#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":20674,"voices":85}},{"id":"h21-20090824-5","meetingId":"h21-cm08","date":"2009年8月24日","dateIso":"2009-08-24","committee":"総務委員会","time":"午後１時０２分～午後４時４８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の平成２１年度都区財政調整交付金当初算定の結果","agenda":"の平成２１年度都区財政調整交付金当初算定の結果","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"よくわからないんですけれども、いつも疑問に思っているところを伺いたいんですが、基準財政需要額の考え方についてなんですけれども、これは「特別区がひとしくその行うべき事務を遂行することができるように、合理的かつ適正な方法により算定する」ということでありますが、その辺各区の事情というのは考慮されていないと思うんですけれども、そこら辺のところはどういう考え方なのかということと。","respondent":"金子企画財政課長","answer":"ただご指摘のとおり、先ほど申しましたとおり特別交付金に関しましては特殊な事情が発生した場合の対応ですけれども、それ以外に各区においてさまざまな事業の差異、あるいは地理的条件の差等々さまざまな差があります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そうするとその区、その区の考え方によっていろいろ住民の要望に基づいて施策を行っていくと、等しく行うべき事務と言いながらもかなり政策的判断で加味されていく要素が強くなっていくことになるのかなと思うんですけれど、そのところはどうなのか。","respondent":"金子企画財政課長","answer":"ある事情である区が突出して事業量が多いというのは、この標準算定のところでは反映しづらいものがありますけれども、それがだんだんほかの区にも広がっていく過程においては、協議が整いやすくなっていくということはあるだろうと考えています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとお聞きしたいんですが、平成２１年度でこういう算定結果が出たんですが、上から２番目の市町村民税法人分が１,５０９億円ですか、約２割減と。それが今年に入って相当企業活動も停滞して、今日も尾を引いて、一部では明るい兆しとはいうものの、それは昨年と比べての比較ですから、かなり悪いことは悪いと思うんですね。大まかにもしわかる範囲で、お答えできる範囲で持っていましたらお願いします。","respondent":"金子企画財政課長","answer":"いずれにしましてもこれからの平成２２年度予算編成に向けて、その辺はあまり大きく数字がずれないように精査していきたいと考えています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"意見だけで。これから来年度の予算編成もまたしていくと思いますが、十分その辺はしっかり、よろしくやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-004"}]},{"id":"topic-02","title":"の新型インフルエンザ対策","agenda":"の新型インフルエンザ対策","exchanges":[{"speaker":"土井委員","kind":"意見","question":"前もってそういうことの予想をして対応されたかどうか、聞かせてください。","respondent":"伊勢危機管理室長","answer":"休園につきましては、現在子ども未来事業部と打ち合わせしている中では、場合によっては保護者の状況によりましてその園で預かることも検討しています。","voiceIndex":17,"id":"exchange-005"},{"speaker":"土井委員","kind":"質問・要望","question":"保護者の状況等もあり、その子がかかっていないというか症状がないという状況の中では、親も大変困ると思うんですよね。ですからできるだけ病児、病後児の関係も含めてきちんと対応ができるように、ある意味では相談も含めて受けとめていただきたいなという思いがあります。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"じゃあ、だれが、それだけの量しかワクチンがないということに関して品川区として、厚労省からまた来ると思うんですが、区としても何か対応とか検討とかされているんでしょうか。要はワクチンが足りないということに対して、さらに大流行する可能性があるわけですから、その辺について今の範囲でご見解をお聞かせ願えればと思います。","respondent":"伊勢危機管理室長","answer":"ワクチンの件につきましては保健所といろいろ情報収集しているわけですけれども、今ちょうど国のほうで優先順位につきまして検討しているということですので、品川区の保健所といたしましても都や国の方針を受けて実際にどうするかということを、情報収集に当たっている状況です。","voiceIndex":21,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"かなりの人数が一斉に１つの施設に入っていく、学校に通うということになると、私なんかは相当心配だなと思うんですが、その辺に対して、もういろいろ対応は検討されていると思うんですが何か今の段階で、今までどおり手を洗う、うがいということにとどまるんでしょうか。それとも何かそのほかに有効な検討策等、対処法を考えているんでしょうか。","respondent":"伊勢危機管理室長","answer":"教育委員会にも東京都からの通知等がございまして、基本的には手洗い、マスクは今はあれですけれども、特に手洗いを重視するようにということで、先週あたりですか教育委員会も学校あてに通知を流したり、感染の把握を迅速にするような検討を教育委員会としてもやって。","voiceIndex":23,"id":"exchange-008"},{"speaker":"須貝委員","kind":"意見","question":"これもちょっと前回話をしたんですが、有効とされているということなので申し上げますけれど、空気清浄機みたいなものが電機メーカーで開発されて、ある程度有効だという見解が出されておりますが、そういうような対応索も、予算的にはかかるのかもしれないですけれど、できる限りの対応索は私はとるべきじゃないかと思いますので、それはちょっと意見として。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"一つ伺いたいんですけれども、登園の自粛とか、場合によっては保育園の閉鎖ということですけれども、その基準というのはどういうふうになっているのかということと、それは国とかあるいは東京都のほうで決めるのか、あるいは区で決めるのか。どうなんでしょう。","respondent":"伊勢危機管理室長","answer":"品川区の場合も５月ごろからいろいろどうしたらいいか考えてございましたけれども、基本的にはそこの園の感染状況あるいは特定のクラスだけだとか、広がっているとか、その辺を総合的に判断いたしまして、休園するかどうかの措置を最終的にはするようにしています。","voiceIndex":27,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"国とか東京都から大体こういう判断の基準ですよとかいうのは全然出てきていなくて、区独自で考えるということなんですね。そういう対応でいいのかなと思うんだけれども、そこら辺は行政のほうはどう、自治体ごとで対応が違うというのもしようがないということなんでしょうか。","respondent":"伊勢危機管理室長","answer":"５月以降、東京都のほうでも、そういう施設で出た場合、休園の要請をすることがありますということだったんですけれども、それ以降１度も、区内で相当発生していますけれども特段の要請はしないということで来ているところです。","voiceIndex":29,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問","question":"例えば大田区ではこのぐらい出たのにちゃんと預かってくれるのに、品川は厳し過ぎるんじゃないのとか、そうなると混乱が出るのかなという気もするんですよね。そういうことでいいんですか。学校なんかでも学級閉鎖とか、国とか東京都とかそういうところの考え方はあるのかないのか。それも区のほうで決めるのか。","respondent":"伊勢危機管理室長、市岡総務部長","answer":"保育園等で集団感染した場合、経路とかあるいはその発生が確認できた場合、既に治っている子がいるかとか、増えつつあるかとか、保育園を通して保育課のほうに情報が上がってきて、それでどういうふうに判断するかということで。すべてが決定打ではないんですが、いろいろなところに目配りをしながら、事前に十分区民、保護者の方に説明をしながら、的確に進めていきたいと。こういうことが品川区の方針です。","voiceIndex":31,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"意見","question":"ニュース等ではやはり子どもが重症化するケースが多いということで、そういう意味では親のほうも、そういう場合だったら休みたいとか、休ませたいという気持ちもある一方で、やはり仕事のほうはどうするんだという両方の板挟みになっちゃうんですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-013"},{"speaker":"山元委員","kind":"質問・要望","question":"ちょっとお伺いします。７月１１日に新型インフルエンザの相談センターが開設されましたけれども、ずっと平日だけで行くのか、休日対策はどうなのか、何かお考えがあるならば教えていただきたいと思います。","respondent":"伊勢危機管理室長","answer":"内容といたしましては、レスキューナウの市川氏からは、この件に向けての事前準備が大切であるとか、あるいは会社全体ではなくても小さな単位で早目早目の対応をしたらどうかということだとか、あるいは会社の情報収集と迅速な意思決定の体系を整えることが大切だとか。","voiceIndex":36,"id":"exchange-014"}]},{"id":"topic-03","title":"の災害対策荏原職員待機寮改築の概要","agenda":"の災害対策荏原職員待機寮改築の概要","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"以前、例えば火災に遭った方たちが、住むところがなくなって待機寮にお世話になった方もいらっしゃると思うんですが、今のお話ですともう全戸入居者が決定しているということは、こういう場合は入れない、また別にあるんですか。","respondent":"榎本人事課長","answer":"災害時の部屋につきましては別の寮のほうに移しまして、伊藤職員待機寮と、従前居住者用住宅のほうに１部屋確保しておりまして、従前と同じ数を確保しています。","voiceIndex":42,"id":"exchange-015"},{"speaker":"土井委員","kind":"質問","question":"この建物は近隣に密着しているものですから、そこら辺についていろいろ説明もされ、工事中も問題なくいったということで、今後も起きないということで、よろしいですね。","respondent":"榎本人事課長","answer":"近隣の皆様には大変ご迷惑をおかけいたしまして、特に地下の基礎を壊す、要は防火水槽が埋まっていた部分を壊すときには、ほとんど３ｍぐらいしか離れていない一軒家がかなりありまして、その方々に大変ご迷惑をおかけしたところで、その点、今後。","voiceIndex":44,"id":"exchange-016"},{"speaker":"宮崎委員","kind":"質問","question":"倍率が２.３倍と３倍とおっしゃったんですけれども、選抜の方法はどうやったんでしょうか。","respondent":"榎本人事課長","answer":"家族につきましてもほぼ同じですけれども、家族予定者も含めて募集をかけておりまして、これから結婚するとか結婚する予定があるという者を含めて募集をかけておりまして、基本的には合算年収を基本にして、住宅困窮度の高い方からという形にしております。","voiceIndex":46,"id":"exchange-017"}]},{"id":"topic-04","title":"の旗台小学校他１施設歩道状空地整備その他改修工事請負契約","agenda":"の旗台小学校他１施設歩道状空地整備その他改修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"旗台小学校を見ますと、ウサギの飼育小屋、雲梯とか砂場がありますよね。結局ここが現存のままでは使えなくて、移動するというか、これを寄せないとできないと、かなり大がかりな工事になるのではないかと思うんですが、実際にここをセットバックしなきゃいけないという理由について、まずちょっとお聞かせ願いたいと思います。","respondent":"阿部経理課長","answer":"この地区は密集市街地住宅整備促進事業の区域です。ここの旗台小学校が避難場所になっているですので、この２カ所、旗台小学校の前と旗の台シルバーセンターの歩道状空地を確保して、避難場所に避難できるように道路整備をするです。","voiceIndex":52,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"今のはよくわかるんですが、地域の住民説明会もきちんとやられているということですが、実際例えば旗台小学校は、校庭は狭くなるわけですね、面積的にも。こういうときはほとんどお金も都市開発費ということで出ているわけですが、これはすべて品川区の一般会計ということですか。それとも東京都のほうから出ているのか、その辺ちょっと教えてください。","respondent":"金子企画財政課長","answer":"合計しますと４,８００万円ほどの金額が、国と都から合わせて出ているものです。その名目は密集市街地住宅の整備が主として出ていまして、シルバーセンターのほうは介護用施設の指定がありますので、その補助も若干あるという内容です。","voiceIndex":54,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"せっかく緑のきれいな庭があるんですが、その辺について一部カットしますが、区として問題ないんですか。","respondent":"宍戸施設整備課長","answer":"シルバーセンターにつきましては昭和４７年に建築されておりまして、築３７年になるんですが、内部も含めてほとんど手を加えていない状況でした。","voiceIndex":56,"id":"exchange-020"},{"speaker":"須貝委員","kind":"意見","question":"１点。そこは都市計画道路ではもちろんなかったわけで、災害路として区でお願いして区民の避難道として確保していくということで。それはあくまで今度の建て替え時、そこに住まれている方が建て替えるまではそのままで、セットバックはしなくていいという考え方で、場合によっては５０年、６０年ぐらいの期間がかかると思うんですが、それは構わないんですよね、後からそういうふうに要請されたということで。","respondent":"阿部経理課長","answer":"申しわけございませんけれども、事業の中身までは承知してございませんので。","voiceIndex":58,"id":"exchange-021"}]},{"id":"topic-05","title":"の南大井文化センター耐震改修その他工事請負契約","agenda":"の南大井文化センター耐震改修その他工事請負契約","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"アスベストの件ですけれども、アスベストの除去には、このぐらいの施設ですとどの程度の費用がかかるものなんでしょうか。","respondent":"宍戸施設整備課長","answer":"そのふきかえも含む費用ですが、ちょっと手元に申しわけありませんがございませんが、そういうことで今回は大きな金額となったものです。","voiceIndex":65,"id":"exchange-022"},{"speaker":"宮崎委員","kind":"質問","question":"アスベストはしばらくちょっと忘れていたというのは何ですけれど、一時期に比べたらあまり言わなくなったんですけれども。アスベストそのものはかなり使われているわけですが、当然中身によって対応できる業者、対応できない業者というのがあるかと思うんです。業者というのは当然今回の仕様を把握されて工事の受注ということになっているんでしょうが、その辺はどのようになっているんでしょうか。","respondent":"宍戸施設整備課長","answer":"それから完全に除去した屋根材について普通のふきかえ工事をすると。そういった手順になってあります。したがいまして、アスベスト除去の部分につきましては専門業者が行います。","voiceIndex":67,"id":"exchange-023"},{"speaker":"山元委員","kind":"質問","question":"今、アスベストのお話がありましたが、ここのすぐ隣にマンションが、それこそすぐ隣接しているわけですけれど、その辺のご説明というか、もう終わっているんでしょうか。","respondent":"宍戸施設整備課長","answer":"基本的には、計測しながら除去するということで、内部ですべて行うものですから、説明は今のところ考えていなかったんですが。要請があれば主管課とも相談しながら、その辺のご説明は丁寧にしていきたいと思いますが、今のところちょっと考えておりませんでした。","voiceIndex":70,"id":"exchange-024"},{"speaker":"山元委員","kind":"質問","question":"ということは、外に漏れることはないという意味でよろしいんですか。","respondent":"宍戸施設整備課長","answer":"その辺は環境課ですけれど届出もいたしますが、常時負圧にいたしまして、何カ所かで計測をしながら、安全性については支障がないように監視しながら行いますので、その辺は万全の体制をとってまいります。","voiceIndex":72,"id":"exchange-025"}]},{"id":"topic-06","title":"の平成２１年８月３０日執行 衆議院議員選挙・最高裁判所裁判官国民審査執行要領","agenda":"の平成２１年８月３０日執行 衆議院議員選挙・最高裁判所裁判官国民審査執行要領","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"ちょっと聞きたいのは、衆議院選挙と最高裁判所裁判官の国民審査の期日前投票の日が違うんですけれども、期日前投票をした場合、最高裁の国民審査の投票ができなかったという話を聞いているんですけれど、これはなぜこういうふうになるんですか。期日前投票を一緒にできないのかという意見なんですけれども、何でこういうふうに。","respondent":"早津選挙管理委員会事務局長","answer":"これは、実は法律の中に最高裁は１週間と決まっているんです。それがなぜかというのは実は公式な説明はないんですが、おそらくこういうことだと思います。","voiceIndex":78,"id":"exchange-026"},{"speaker":"宮崎委員","kind":"質問","question":"ここでどうこうしようと言ってもしようがない話なんですけれども、ぜひ機会があればやはり同じにすべきという話をしていただければと思います。実際に何人かから質問が来ました。","respondent":"早津選挙管理委員会事務局長","answer":"おっしゃるとおりで、全国の選挙管理委員会の連合会があるんですが、ここで総務省のほうに改正要望は既に出しております。ただ、法律の改正がなかなか進まないということで、認識としては私どもも同じ考えです。","voiceIndex":80,"id":"exchange-027"},{"speaker":"土井委員","kind":"質問","question":"そうすると例えばの話、両方ともどこかへ入れてしまったり、あべこべに入れてみたり、ということも含めて、起こり得る中身をわざわざ誘発するようなことをやっているようにも見えるんだけれど、これは何か問題でこうなっているんですか。","respondent":"早津選挙管理委員会事務局長","answer":"ということを防止するために、比例代表分と一緒にお渡しすると。比例代表分は必ず記載所に行って、一定の時間で書いて、それを持ってきて投票するということがあるので、最高裁の国民審査の秘密を守るためという説明です。","voiceIndex":82,"id":"exchange-028"},{"speaker":"土井委員","kind":"質問","question":"先ほどの書かない人がいるから秘密を守るためというのは、それはある意味では詭弁なので、本来ならばそういう人たちのプライバシーも守れるような形の投票所をつくって、別にするというのが正しいやり方で、性質が違うものを一緒にやるんですから。本来そうだとは思いますけれども、これ以上は言いません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1830#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":25022,"voices":90}},{"id":"h21-20090825-14","meetingId":"h21-cm08","date":"2009年8月25日","dateIso":"2009-08-25","committee":"行財政改革特別委員会","time":"午後１時０３分～午後３時４６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１の報告事項を行います。大崎第二地域センターおよび旧品川・大崎土木事務所跡の暫定活用","agenda":"の１の報告事項を行います。大崎第二地域センターおよび旧品川・大崎土木事務所跡の暫定活用","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"在宅介護支援センターというのは、多分事務所っぽいところだと思いますし、サービスセンターというのは、多分デイサービスとか、実際にサービスを提供するところだと思うんですけれども、それがこんなに離れてしまうというところで支障はないのかなというのが１つと、あと、資材置場の件ですけれども、この前視察に行きましたけれども、旧土木事務所の機能、今。","respondent":"久保田行財政改革担当課長","answer":"建物以外のところに置いてあったと思うんですけれども、あれにつきましては、在宅サービスセンター等の車の出入り等もありますので、整理させていただいて、そうしたサービスセンターの利用に支障がないように対応していきたいと考えているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"国勢調査の事務スペースなんですけれども、庁舎の耐震工事実施に伴い、確保できなくなったというご説明でしたが、前回の国勢調査の場合、どのようなスペースで、どこでそういう作業をしていて、今回なぜ庁舎内に確保できないのかというのをもう少し詳しくお伺いします。最近頻繁に地震があるので、ちょっとそこら辺も不安な点があるんですが、そこら辺もあわせてお伺いします。","respondent":"久保田行財政改革担当課長、宍戸施設整備課長","answer":"こちらにつきましては、こちらの資料に書いてありますとおり、庁舎内に耐震工事の関係でスペースを確保することが難しいということで、できるだけ庁舎に近いところというところで。それとあと、庁舎の耐震について少し補足説明をしますと、今、居ながら工事、免震工法ということで進めしていますが、第三庁舎だけは通常の耐震工法で行います。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"提案","question":"第三庁舎は通常のということで、半年から８カ月、居ながら工事というのはできませんということなんですが、第三庁舎全体がそのような、５階の会議室、これだけではなく、そういうふうになるということなのかという確認と、あと、なぜ先ほどのような質問をしたかというと、この暫定活用の仕方といたしまして、優先順位というのがすごくあると思うんですけれども、例えば、大崎地域ですと。","respondent":"宍戸施設整備課長、久保田行財政改革担当課長","answer":"前段の庁舎の耐震工事の関係なんですが、今、具体的にはどの範囲というのは詰めているところですが、第三庁舎については、基本的にはしばらくの間、講堂や何かも含めて使えないと考えております。そうした中で、空き施設、跡地施設の有効活用といった点から、大崎第二地域センターといった部分が、庁舎からも一定程度の距離、一定程度近いということもありますし、また、その中で大崎在宅介護支援センターといったものも。","voiceIndex":10,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"所管が地域活動課ということで、国勢調査、地域活動課はそういうスペースを探していたということがあると思うんですけれども、さまざまな課が、所管がさまざまな区民の皆さんの声を聞きながら、こういうところが必要なんじゃないかというニーズを把握されていると思うんですけれども、それを暫定活用ということで、跡地をどう使うかという、どこがどう。","respondent":"久保田行財政改革担当課長","answer":"そうした中で、今回国勢調査につきましては、来年度実施していかなければならないということもありますし、法に定められた事務ですので、一定のスペースを確保しながら、１年間ではありますけれども、集中してやっていくといった必要がありますので。","voiceIndex":13,"id":"exchange-004"},{"speaker":"須藤委員","kind":"意見","question":"両方の暫定活用を理解いたします。それぞれ将来的にどういう形に持っていくかということは、３年の間に暫定的にもしっかり調査をして、どういう方向性がいいんだろうということを皆さん方、また我々も考えていきたいと思いますので、よろしくお願いしますと思っているんだけれども、そういう考え方でよろしいかどうか、我々はそういう理解をするんですけれども。","respondent":"久保田行財政改革担当課長","answer":"そちらにつきましては、長期的な、将来にわたる活用ということで検討していますけれども、そうしたものも踏まえながら、今回３年間ではありますけれども、暫定的に施設を有効に活用していきたいという観点から暫定活用をするものでございまして、委員がご指摘のように。","voiceIndex":15,"id":"exchange-005"},{"speaker":"川西委員","kind":"質問","question":"３つありますけれども、１つは、第三庁舎の耐震工事の予定を教えてください。それから、さっきご説明のときに、在宅介護支援センターが３階に移っていく。相談業務もあると。ですから、大変だなとやや思いますけれども、それでもセンターのほうで何とか使いこなして、ケアマネージャーとか、いろいろな職員の方はいいですよ。活動的な、動き回っている方ですから、事故のないように、これはお願いで結構です。","respondent":"久保田行財政改革担当課長、宍戸施設整備課長","answer":"これにつきましては、多分近隣の方なんですけれども、たまたま今回あそこのところから、防災の毛布とかがしまってあったと思うんですけれども、あれを今回移すといったことがございまして、入れ替えとか。したがいまして、大体平成２２年の前半あたりに６カ月から８カ月ぐらいの形で工事をするという大ざっぱな見当はつけているところですが、もう少し細かく決まりましたら、所管の委員会でご報告をするなど。","voiceIndex":17,"id":"exchange-006"},{"speaker":"川西委員","kind":"質問・要望","question":"ですから、区としては今後こういうものを考えているぐらいのことは、どこかのルートで言えないものかどうか、これも今お答えいただくのは無理かと思いますので、要望しておきますから、だれも反対しないと思うんです、この在宅サービスセンターなり、こういう施設について、暫定的にここに来るよということは、反対はないと思いますので、ごく近隣でいいですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-007"},{"speaker":"阿部委員","kind":"質問・要望","question":"具体的なことに絞ってお伺いしたいと思います。これについては何かお考えを持っていらっしゃってのフロア割りなのかなという気もちょっとしたものですから、全く予定がないのか、それとも２年後、平成２３年からの利用について何かお考えがあるのか教えてください。","respondent":"久保田行財政改革担当課長、宍戸施設整備課長","answer":"３階部分に在宅介護支援センターですけれども、実は今回在宅介護支援センターにつきましても、スペース的にいっぱい、いっぱいといったところもございまして、現在考えているところでは、今回１年間だけ国勢調査が使いまして。少し補足しますと、いわゆるプレハブの建物というのを考えておりまして、そういう意味では、パーツ、パーツはもちろんまた再利用するのを前提に賃貸借という形で、借りるというものです。","voiceIndex":21,"id":"exchange-008"},{"speaker":"阿部委員","kind":"質問・要望","question":"それぞれありがとうございました。フロア割りの件なんですけれども、伺っていると、何か区の職員の方の働きやすいさを優先しているようにも聞こえてしまったんですけれども、在宅介護支援センターの方が不便なく働けるように、ぜひいろいろとご配慮を、強くお願いしたいと思います。最後に、ちょっと要望を１つだけお願いします。これは要望です。","respondent":"久保田行財政改革担当課長","answer":"ちょっと説明が漏れまして、国勢調査につきましては、調査票等、調査員の方にお願いいたしまして、そういったものを持ってきていただくといったところもありますので、そういった意味では、１・２階、１階のところでそういう書類を受けられるような形にさせていただいて。","voiceIndex":24,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"現大崎第二地域センターと旧品川・大崎土木事務所の暫定活用についてですけれども、いつ決まったのかというご質問の中で、いつかがよくわからなかったので、この暫定活用がいつ決まったのか、どこの部署なのか、それをちょっと教えていただきたい。","respondent":"久保田行財政改革担当課長","answer":"本日は、こちらの行革委員会で跡地活用につきましてご検討いただいておりますので、方向性がこうなりますということで、報告をさせていただいているです。","voiceIndex":26,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"今のご説明ですと、これは方向性で、これからもんでいくといいますか、ご意見を伺うという話だったんですけれども、やっぱり計画案であれば、計画案として出していただかないと、こうしたほうがいいんじゃないか、ああしたほうがいいんじゃないかという議論が、議会もそうだし、あとここを利用している人もそうだし、周辺の人もそうだし、そういう進め方というのはすごく大事だなと思うんです。","respondent":"久保田行財政改革担当課長","answer":"今後暫定活用後の本格活用につきましては、今現在検討も進めているですけれども、こちらにつきまして、仕組みということでございましたが、それぞれの施設にある地域の課題等、立地上の問題とか、地域上の問題、地域の特性等もありますので、一律に何か仕組みをつくりまして。","voiceIndex":28,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後は要望ですけれども、進めるに当たっての仕組みづくりは、私は必要だと思います。そこを示してもらわないと、何を検討していいのか、私も正直よくわからない部分が出てくるので、そこはよく検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"それからもう１つ、両方とも平成２５年３月ということで、平成２６年度からは、いわゆる一体化も含めた本格的な施設で行うと一応理解していいのかどうかということを１つお聞きします。それから、要望も含めて、１階の相談窓口はぜひお願いいたします。３階は無理です。同時に、隣にシルバーセンターがあります。","respondent":"久保田行財政改革担当課長","answer":"サービスセンターの仮移転先の検討ですけれども、私ども、所管を中心ですけれども、やはり大崎地区でどこか適地はないかということで検討してまいりました。","voiceIndex":31,"id":"exchange-013"},{"speaker":"市川委員","kind":"確認","question":"最後に１つだけ確認させてください。ニーズとしてあるのかということは、全庁に伺っているということだったんですけれども、この２つの跡地活用については全庁的に聞いたときに、何かほかにこういう活用をしたいということがあったのか、そういうことが出たのか、それとも全くなかったのか、その辺を伺いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"大崎第二地域センターにつきましては、それぞれの所管課にもいろいろと跡地活用ということで話はしたんですけれども、場所的にもなかなか難しいということで、今回国勢調査の部分と在宅介護支援センターということで活用させてもらえないかという話もございまして。","voiceIndex":33,"id":"exchange-014"}]},{"id":"topic-02","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"川西委員","kind":"質問","question":"申しわけないんですけれども、この文章の中に、維持管理費用が集中すると書いてありますけれども、実際にこういうものは人の命にかかわる問題なんですけれども、財源内訳というのは、国と都と区の関係というのはどうなっているか、１つだけ教えておいてください。","respondent":"藤橋都市整備下水道課長","answer":"今後、橋梁の架け替えにつきましては、今の全国的な動きで、橋梁の長寿命化修繕計画を策定した橋梁に対して、国から補助が出るというような仕切りになってございまして、今後、架け替えに要する費用等を確保するためには。","voiceIndex":39,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5868#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":19378,"voices":44}}]);
